INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89640, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用武力打垮旧政权；或否定已有的决定、说法。", "primary_collocate": null, "pronunciation": "tuī fān", "ipa": "tʰweɪ̯˥ fan˥", "syllable_count": 2, "sentences": [{"text": "人民起来推翻了旧政权。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人民推翻了国王。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用武力推翻了旧王朝。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院推翻了原来的判决。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新证据推翻了警察的说法。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生推翻了上次的诊断。", "target_word": "推翻", "complexity_tier": "T3", "furigana": "yī shēng tuī fān le shàng cì de zhěn duàn", "sentence_source": "generated"}, {"text": "一百年前，他们推翻了皇帝的统治。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司推翻了昨天的决定。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项研究推翻了过去的看法。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们想推翻不合理的制度。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推翻了", "label": "体标"}, {"form": "推翻过", "label": "体标"}], "register": "中性", "sense_fingerprint": "武力打垮旧政权，或否定已有的决定、说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc2d5b0-68ed-4568-9f5e-5076fc78fec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推翻", "is_correct": true, "explanation": "推翻：武力打垮旧政权，符合句意。"}, {"text": "建立", "is_correct": false, "explanation": "语义：“建立”指新建，与“旧政权”相矛盾。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”的对象是食物，不说品尝政权。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”用于植物，与政权无关。"}], "explanations": {"推翻": "推翻：武力打垮旧政权，符合句意。", "建立": "语义：“建立”指新建，与“旧政权”相矛盾。", "品尝": "搭配：“品尝”的对象是食物，不说品尝政权。", "种植": "语义：“种植”用于植物，与政权无关。"}, "sentence_index": 0, "correct_answer": "推翻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他推翻了年迈的父母。", "explanation": "这里应该用〈照顾〉。推翻只用于政权、决定、说法，不用于照顾人。"}, {"text": "大家推翻了他的勇气。", "explanation": "这里应该用〈赞美〉。推翻指否定已有的决定或说法，不用于勇气这类品质。"}, {"text": "她推翻了一份礼物。", "explanation": "这里应该用〈收到〉。推翻不用于礼物，它否定的是决定、说法或政权。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推翻", "is_correct": true, "explanation": "推翻：武力打垮旧政权，符合句意。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是建筑，不说修建统治。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”指量度长短高低，与统治无关。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”用于种子，与统治无关。"}], "explanations": {"推翻": "推翻：武力打垮旧政权，符合句意。", "修建": "搭配：“修建”的对象是建筑，不说修建统治。", "测量": "语义：“测量”指量度长短高低，与统治无关。", "播种": "语义：“播种”用于种子，与统治无关。"}, "sentence_index": 6, "correct_answer": "推翻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校推翻了明天的阳光。", "explanation": "这里应该用〈迎来〉。推翻不用于阳光，它只用于否定已有的决定或说法。"}, {"text": "他推翻了很多友谊。", "explanation": "这里应该用〈收获〉。推翻只用于政权、决定、说法，不用于友谊。"}, {"text": "她推翻了一阵笑声。", "explanation": "这里应该用〈听到〉。推翻不用于笑声，它只用于否定已有的决定或说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "起义军推翻了了那个腐败的政权。", "corrected_sentence": "起义军推翻了那个腐败的政权。", "error_description": "“了”只能出现一次，紧跟动词“推翻”；说“推翻了那个腐败的政权”，重复的“了”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府没有推翻了这个决定。", "corrected_sentence": "政府没有推翻这个决定。", "error_description": "“没有”否定动作时，动词后不加“了”；应说“没有推翻这个决定”，“没有推翻了”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa508e6a-fa39-443f-af9d-507b929dab0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
