INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89644, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提出主张或建议供大家讨论。", "primary_collocate": null, "pronunciation": "tí yì", "ipa": "tʰi˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "经理提议下周开一次会。", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在会上提议增加预算。", "target_word": "提议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "代表们提议修改这个规定。", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人提议投票决定，大家都同意。", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小组提议把活动时间延长一周。", "target_word": "提议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提议了三次，领导才同意。", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王主任提议先讨论这个问题。", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会上有人提议成立一个新小组，我表示支持。", "target_word": "提议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她提议过很多次，可是没有人回应。", "target_word": "提议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们提议每月开一次讨论会。", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "提议了", "label": "体标"}, {"form": "提议过", "label": "体标"}, {"form": "提議", "label": "繁体"}], "register": "正式", "sense_fingerprint": "在会议等场合提出主张供讨论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e9126ca-4af1-43ae-8d7f-a545c9374384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是衣物、身体等，不能用来说“开一次会”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”接机器、房屋等具体物品，不接“开一次会”这类事情。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指用布等抹掉污物，与“下周开一次会”的意思不相容。"}, {"text": "提议", "is_correct": true, "explanation": "“提议”指在会上提出主张请大家讨论，与句中“经理……开会”相符。"}], "explanations": {"洗": "语义：“洗”的对象是衣物、身体等，不能用来说“开一次会”。", "修理": "搭配：“修理”接机器、房屋等具体物品，不接“开一次会”这类事情。", "擦": "语义：“擦”指用布等抹掉污物，与“下周开一次会”的意思不相容。", "提议": "“提议”指在会上提出主张请大家讨论，与句中“经理……开会”相符。"}, "sentence_index": 0, "correct_answer": "提议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经理提议了这个月的工作情况。", "explanation": "这里应该用〈报告〉。“提议”的对象是办法或建议，陈述工作情况要用报告。"}, {"text": "他提议了迟到的原因。", "explanation": "这里应该用〈解释〉。“提议”的对象是办法或建议，说明迟到的原因要用解释。"}, {"text": "他提议了自己的错误。", "explanation": "这里应该用〈承认〉。“提议”不能接“错误”，承认错误要用承认。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是把一种语言转成另一种语言，句中没有语言转换。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”不接“讨论这个问题”这类抽象的行为。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹断，不能用来说“先讨论这个问题”。"}, {"text": "提议", "is_correct": true, "explanation": "“提议”指提出办法供大家讨论，与“先讨论这个问题”相符。"}], "explanations": {"翻译": "语义：“翻译”是把一种语言转成另一种语言，句中没有语言转换。", "拍": "搭配：“拍”不接“讨论这个问题”这类抽象的行为。", "咬": "语义：“咬”指用牙齿夹断，不能用来说“先讨论这个问题”。", "提议": "“提议”指提出办法供大家讨论，与“先讨论这个问题”相符。"}, "sentence_index": 6, "correct_answer": "提议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张提议大家都同意了。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌子等扁平的东西，提议不能用“张”来计量。"}, {"text": "这辆提议很有道理，我们可以考虑。", "explanation": "这里应该用〈个〉。“辆”用于车辆，提议不能用“辆”来计量。"}, {"text": "这只提议很好，我们应该认真考虑。", "explanation": "这里应该用〈个〉。“只”多用于动物，不能用来数提议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他曾经提议了设立一个奖学金。", "corrected_sentence": "他曾经提议过设立一个奖学金。", "error_description": "错误：“曾经”表示有过的经历，动词后应用“过”，这里误用了“了”。正确：“他曾经提议过设立一个奖学金”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这封提议很有道理，大家都同意。", "corrected_sentence": "这个提议很有道理，大家都同意。", "error_description": "错误：用“封”来数“提议”。正确：应说“这个提议”，“封”用于信件，不能用来数提议。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
