INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他开车的时候撞过了一辆自行车。", "corrected_sentence": "他开车的时候撞了一辆自行车。", "error_description": "体标错误：“过”和“了”不能同时用在动词后，应去掉“过”，说“撞了一辆自行车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
