INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89651, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "昨天的晚上。", "primary_collocate": null, "pronunciation": "zuó wǎn", "ipa": "tswɔ˧˥ wan˨˩˦", "syllable_count": 2, "sentences": [{"text": "昨晚的风很大。", "target_word": "昨晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨晚我没有睡好。", "target_word": "昨晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨晚电视里有一个很好看的节目。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚弟弟哭了很久。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚你为什么没接电话？", "target_word": "昨晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨晚我做了一个奇怪的梦。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚我作业太多，写到很晚才睡。", "target_word": "昨晚", "complexity_tier": "T3", "furigana": "zuó wǎn wǒ zuò yè tài duō, xiě dào hěn wǎn cái shuì.", "sentence_source": "generated"}, {"text": "昨晚老师发了一条短信给我。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚他们在公园里散步了。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚的饭很好吃，今天我还想去那家饭馆。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "昨天的晚上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20c5325b-005c-476c-b1df-5f348cdc042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昨晚", "is_correct": true, "explanation": "昨晚：指昨天夜里，与“风很大”所描述的时间相符。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：咖啡不会刮风，“咖啡的风”无法搭配。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是刮风的事物，“电视的风很大”说不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不会刮风，句中“的风很大”无法用来修饰钥匙。"}], "explanations": {"昨晚": "昨晚：指昨天夜里，与“风很大”所描述的时间相符。", "咖啡": "搭配：咖啡不会刮风，“咖啡的风”无法搭配。", "电视": "语义：电视不是刮风的事物，“电视的风很大”说不通。", "钥匙": "语义：钥匙不会刮风，句中“的风很大”无法用来修饰钥匙。"}, "sentence_index": 0, "correct_answer": "昨晚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天昨晚都给我讲故事。", "explanation": "〈每天晚上〉。昨晚只指过去的一个夜晚，不能表示经常性的动作；表示习惯应说“每天晚上”。"}, {"text": "昨晚一早，妈妈就去了菜市场。", "explanation": "〈昨天〉。昨晚指夜间，不能与表示清晨的“一早”搭配，应说“昨天一早”。"}, {"text": "昨晚下午，我们去公园散步了。", "explanation": "〈昨天〉。昨晚指夜间，不能与“下午”搭配，应说“昨天下午”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨晚", "is_correct": true, "explanation": "昨晚：指昨天夜里，与“写到很晚才睡”的时间相符。"}, {"text": "早上", "is_correct": false, "explanation": "语义：早上写到很晚才睡，时间上自相矛盾。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午写到很晚才睡，与“很晚才睡”的时间描述矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：桌子不会“作业太多”，句首的桌子与“我作业太多”搭配不当。"}], "explanations": {"昨晚": "昨晚：指昨天夜里，与“写到很晚才睡”的时间相符。", "早上": "语义：早上写到很晚才睡，时间上自相矛盾。", "中午": "语义：中午写到很晚才睡，与“很晚才睡”的时间描述矛盾。", "桌子": "搭配：桌子不会“作业太多”，句首的桌子与“我作业太多”搭配不当。"}, "sentence_index": 6, "correct_answer": "昨晚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨晚弟弟将去奶奶家。", "explanation": "〈明晚〉。昨晚指已经过去的夜晚，不能与表示将来的“将”搭配；将来的安排应说“明晚”。"}, {"text": "昨晚我们去看电影吧。", "explanation": "〈今晚〉。“吧”用于提议将来或现在的事，昨晚已经过去，提议应说“今晚”。"}, {"text": "昨晚我现在正在写作业。", "explanation": "这里应该用〈今晚〉。昨晚指已经过去的夜晚，不能用来指此刻正在进行的写作业；指这个夜晚应说“今晚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我那个昨晚洗衣服洗了一个小时。", "corrected_sentence": "我昨晚洗衣服洗了一个小时。", "error_description": "错误：“那个”这类指示词加量词不能修饰“昨晚”这样的时间词。正确：应去掉“那个”，说“我昨晚洗衣服洗了一个小时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个昨晚我们聊天聊到很晚。", "corrected_sentence": "昨晚我们聊天聊到很晚。", "error_description": "错误：“那个”这类指示词加量词不能修饰“昨晚”这样的时间词。正确：应直接说“昨晚我们聊天聊到很晚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
