INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89656, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有门路、有办法；合乎事理。", "primary_collocate": null, "pronunciation": "yǒu dào", "ipa": "jou˨˩˦ tau˥˩", "syllable_count": 2, "sentences": [{"text": "他生财有道，不上班也能赚到钱。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "君子爱财，取之有道。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱要花得好，也要用之有道。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做人进退有道，从不乱说乱动。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张处世有道，和谁都合得来。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位县长为官有道，百姓都很信他。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她办事有道，大家的难题她都能解决。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赚钱有道，每一分都来得正当。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家人人都守规矩，真是治家有道。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他进货有道，总能拿到便宜的货。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生财有道", "label": "复合"}, {"form": "取之有道", "label": "复合"}], "register": "书面", "sense_fingerprint": "有门路、有办法，做法合乎事理，多见于固定说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20c5325b-005c-476c-b1df-5f348cdc042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89656, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有道", "is_correct": true, "explanation": "有道 yǒu dào 指有门路、有办法，或做法合乎事理。"}, {"text": "游到", "is_correct": false, "explanation": "游到 yóu dào 与 yǒu dào 第一音节声调不同（第二声与第三声），意思是游动到某处。"}, {"text": "诱导", "is_correct": false, "explanation": "诱导 yòu dǎo 两个音节的声调都不同，意思是引导，与“有道”意思不同。"}, {"text": "油道", "is_correct": false, "explanation": "油道 yóu dào 第一音节声调不同（第二声），意思是润滑油的通道，与“有道”不同。"}], "explanations": {"有道": "有道 yǒu dào 指有门路、有办法，或做法合乎事理。", "游到": "游到 yóu dào 与 yǒu dào 第一音节声调不同（第二声与第三声），意思是游动到某处。", "诱导": "诱导 yòu dǎo 两个音节的声调都不同，意思是引导，与“有道”意思不同。", "油道": "油道 yóu dào 第一音节声调不同（第二声），意思是润滑油的通道，与“有道”不同。"}, "sentence_index": null, "correct_answer": "有道"}, "level_3": {"options": [{"text": "有道", "is_correct": true, "explanation": "有道指有门路、有办法，与“能赚到钱”相符。"}, {"text": "无方", "is_correct": false, "explanation": "语义：生财无方与“不上班也能赚到钱”矛盾。"}, {"text": "乏术", "is_correct": false, "explanation": "语义：生财乏术与“不上班也能赚到钱”的结果矛盾。"}, {"text": "吝啬", "is_correct": false, "explanation": "搭配：“吝啬”形容人的性情，不用来修饰“生财”的方式。"}], "explanations": {"有道": "有道指有门路、有办法，与“能赚到钱”相符。", "无方": "语义：生财无方与“不上班也能赚到钱”矛盾。", "乏术": "语义：生财乏术与“不上班也能赚到钱”的结果矛盾。", "吝啬": "搭配：“吝啬”形容人的性情，不用来修饰“生财”的方式。"}, "sentence_index": 0, "correct_answer": "有道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把刀很有道，切菜很快。", "explanation": "这里应该用〈锋利〉。“有道”形容人的做法，不用来形容刀的锋利程度。"}, {"text": "这张桌子很有道，搬家也不怕。", "explanation": "这里应该用〈结实〉。“有道”形容人处事有办法，不用来形容桌子的坚固程度。"}, {"text": "这道菜很有道，大家都夸好吃。", "explanation": "这里应该用〈可口〉。“有道”形容人做事有办法，不用来形容菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有道", "is_correct": true, "explanation": "有道指办事有办法，与“大家的难题她都能解决”相符。"}, {"text": "愚笨", "is_correct": false, "explanation": "语义：办事愚笨与“难题都能解决”矛盾。"}, {"text": "糊涂", "is_correct": false, "explanation": "语义：办事糊涂，与“大家的难题她都能解决”矛盾。"}, {"text": "拙劣", "is_correct": false, "explanation": "语义：办事拙劣，与“大家的难题她都能解决”矛盾。"}], "explanations": {"有道": "有道指办事有办法，与“大家的难题她都能解决”相符。", "愚笨": "语义：办事愚笨与“难题都能解决”矛盾。", "糊涂": "语义：办事糊涂，与“大家的难题她都能解决”矛盾。", "拙劣": "语义：办事拙劣，与“大家的难题她都能解决”矛盾。"}, "sentence_index": 6, "correct_answer": "有道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画很有道，挂在客厅很合适。", "explanation": "这里应该用〈漂亮〉。“有道”形容人做事有办法，不用来形容画的美观。"}, {"text": "这条毯子很有道，冬天盖着很暖和。", "explanation": "这里应该用〈柔软〉。“有道”不用来形容毯子的质地，只能说人做事有办法。"}, {"text": "这个花瓶很有道，摆在桌上很好看。", "explanation": "这里应该用〈精美〉。“有道”形容人的做法，不用来形容花瓶的做工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他办事办很有道，客户都愿意找他。", "corrected_sentence": "他办事办得很有道，客户都愿意找他。", "error_description": "补语错误：“办……得……”结构中的“得”不能省，应说“办事办得很有道”，不能说“办事办很有道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她说话很有道过，大家都愿意听她的意见。", "corrected_sentence": "她说话很有道，大家都愿意听她的意见。", "error_description": "体标错误：“有道”是形容词，后面不能加“过”，应说“很有道”，不带“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
