INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89667, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因为别人和自己不一样，就看不起他、不公平地对他。", "primary_collocate": null, "pronunciation": "qí shì", "ipa": "tɕʰi˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "有些人因为他的口音歧视他。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们不应该因为小明很穷就歧视他。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从不歧视和自己不一样的人。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是外国人，常常有人歧视他。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别因为朋友的肤色不同就歧视他。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈教我，不要歧视穷人。", "target_word": "歧视", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小时候有人歧视过我，因为我说话有口音。", "target_word": "歧视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿不好，但是没有人歧视他。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么歧视新来的同事？", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她穿得很旧，同学们就歧视她，不跟她玩。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "歧视了", "label": "体标（了）"}, {"form": "歧视过", "label": "体标（过）"}, {"form": "歧视着", "label": "体标（着）"}], "register": "书面", "sense_fingerprint": "因为别人不一样而看不起、不公平地对待他", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20c5325b-005c-476c-b1df-5f348cdc042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89667, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "歧视", "is_correct": true, "explanation": "歧视：正确答案，意思是因为别人与自己不一样而看不起他、不公平地对待他。"}, {"text": "其实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“其实”意思是实际上，与“歧视”不同。"}, {"text": "气势", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，“气势”指气派和声势。"}, {"text": "启示", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，“启示”指给人的提示或教导。"}], "explanations": {"歧视": "歧视：正确答案，意思是因为别人与自己不一样而看不起他、不公平地对待他。", "其实": "shí（第二声）与 shì（第四声）声调不同，“其实”意思是实际上，与“歧视”不同。", "气势": "qì（第四声）与 qí（第二声）声调不同，“气势”指气派和声势。", "启示": "qǐ（第三声）与 qí（第二声）声调不同，“启示”指给人的提示或教导。"}, "sentence_index": null, "correct_answer": "歧视"}, "level_3": {"options": [{"text": "歧视", "is_correct": true, "explanation": "歧视：因为口音不同而看不起他，符合句中的因果关系。"}, {"text": "同情", "is_correct": false, "explanation": "语义：因为口音而同情他，与句中的负面对待不符。"}, {"text": "疼爱", "is_correct": false, "explanation": "语义：因为口音而疼爱他，与句中的负面对待不符。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”针对事件或成就，不能用于“因为他的口音”这样的原因。"}], "explanations": {"歧视": "歧视：因为口音不同而看不起他，符合句中的因果关系。", "同情": "语义：因为口音而同情他，与句中的负面对待不符。", "疼爱": "语义：因为口音而疼爱他，与句中的负面对待不符。", "庆祝": "搭配：“庆祝”针对事件或成就，不能用于“因为他的口音”这样的原因。"}, "sentence_index": 0, "correct_answer": "歧视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师歧视这个学生的作文。", "explanation": "〈欣赏〉。歧视的对象必须是人；评价作文应说“欣赏”。"}, {"text": "我每天歧视我的鱼。", "explanation": "〈喂养〉。歧视只用于人，动物不能作宾语；照顾鱼应说“喂养”。"}, {"text": "我们歧视这次活动。", "explanation": "〈评价〉。歧视的对象必须是人，不能是活动；对活动发表看法应说“评价”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89667, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歧视", "is_correct": true, "explanation": "歧视：因为口音不同而不公平地对待我，符合句意。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：因为口音而表扬，与句中“歧视”所表达的因果关系不符。"}, {"text": "赞颂", "is_correct": false, "explanation": "语域：“赞颂”偏书面，与口语化的叙述不协调；同时与“因为我说话有口音”的原因不合。"}, {"text": "疼爱", "is_correct": false, "explanation": "语义：因为口音而疼爱我，与句中的负面对待不符。"}], "explanations": {"歧视": "歧视：因为口音不同而不公平地对待我，符合句意。", "表扬": "语义：因为口音而表扬，与句中“歧视”所表达的因果关系不符。", "赞颂": "语域：“赞颂”偏书面，与口语化的叙述不协调；同时与“因为我说话有口音”的原因不合。", "疼爱": "语义：因为口音而疼爱我，与句中的负面对待不符。"}, "sentence_index": 6, "correct_answer": "歧视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈歧视我快点写作业。", "explanation": "这里应该用〈催促〉。歧视表示不公平地对待，不能带“快点写作业”这种催促内容；催人快点做事应说“催促”。"}, {"text": "他热情地歧视我们。", "explanation": "这里应该用〈欢迎〉。歧视是不公平地对待，与“热情地”的语气矛盾；热情迎接客人应说“欢迎”。"}, {"text": "妈妈因为我难过歧视了我。", "explanation": "〈安慰〉。歧视的对象是因与自己不同而被不公平对待的人，难过时安慰他人应说“安慰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们歧视很厉害。", "corrected_sentence": "同学们歧视得很厉害。", "error_description": "错误：程度补语前漏掉了“得”。正确：“得”应紧跟动词，说“歧视得很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一直歧视我着，我很难过。", "corrected_sentence": "她一直歧视着我，我很难过。", "error_description": "错误：动态助词“着”放错了位置。正确：“着”应紧跟动词，说“一直歧视着我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b1733a-6af4-459d-9c37-d4912c3b0c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
