INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89703, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "不是吗是用问的话说,意思是对啊。", "primary_collocate": null, "pronunciation": "bú shì ma", "ipa": "pu˧˥ ʂɻ̩˥˩ ma", "syllable_count": 3, "sentences": [{"text": "时间就是金钱，不是吗？", "target_word": "不是吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "健康比钱重要，不是吗？", "target_word": "不是吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜很便宜，不是吗？", "target_word": "不是吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你上个月说要学做饭，不是吗？", "target_word": "不是吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想过好日子，不是吗？", "target_word": "不是吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷了，不是吗？", "target_word": "不是吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你刚才还笑着，不是吗？", "target_word": "不是吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是好朋友，不是吗？", "target_word": "不是吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书让人快乐，不是吗？", "target_word": "不是吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人常说，笑一笑十年少，不是吗？", "target_word": "不是吗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不是嗎", "label": "繁体"}, {"form": "难道不是吗", "label": "搭配"}], "register": "口语", "sense_fingerprint": "不是吗|用问句表示肯定|意思是对啊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3b0bebd-d58b-44d0-81e3-335cff6f276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89703, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不是吗", "is_correct": true, "explanation": "“不是吗”在此表示“对啊”，说话人认为对方应当同意，与“时间就是金钱”相符。"}, {"text": "不对吗", "is_correct": false, "explanation": "语义：“不对吗”表示反问“不对”，与“时间就是金钱”的肯定判断相反。"}, {"text": "好吗", "is_correct": false, "explanation": "语义：“好吗”是征求对方同意的提议，不能表示“对啊”的肯定。"}, {"text": "呢", "is_correct": false, "explanation": "搭配：“呢”用于省略问，不能附在完整陈述句后表示肯定和同意。"}], "explanations": {"不是吗": "“不是吗”在此表示“对啊”，说话人认为对方应当同意，与“时间就是金钱”相符。", "不对吗": "语义：“不对吗”表示反问“不对”，与“时间就是金钱”的肯定判断相反。", "好吗": "语义：“好吗”是征求对方同意的提议，不能表示“对啊”的肯定。", "呢": "搭配：“呢”用于省略问，不能附在完整陈述句后表示肯定和同意。"}, "sentence_index": 0, "correct_answer": "不是吗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我也许会来，不是吗？", "explanation": "这里应该用〈对不对〉。“不是吗”预设对方应当同意，说话人只是不确定时要用“对不对”来确认。"}, {"text": "这件事我完全不明白，不是吗？", "explanation": "这里应该用〈是吧〉。“不是吗”预设说话人已知，说话人自己不明白时要用“是吧”来求证。"}, {"text": "我不知道你要学做饭，不是吗？", "explanation": "这里应该用〈是吧〉。“不是吗”预设说话人已经知道、对方应当同意；说自己不知道时，要求证就用“是吧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不是吗", "is_correct": true, "explanation": "“不是吗”在此表示“对啊”，说话人认为对方应当同意，与“笑着”的事实相符。"}, {"text": "不行吗", "is_correct": false, "explanation": "语义：“不行吗”表示反问“不行”，与“你刚才还笑着”的事实相反。"}, {"text": "行吗", "is_correct": false, "explanation": "语义：“行吗”是征求对方是否同意，不能表示“对啊”的肯定。"}, {"text": "没有吗", "is_correct": false, "explanation": "搭配：“没有吗”针对有无提问，不能附在叙述句后表示肯定。"}], "explanations": {"不是吗": "“不是吗”在此表示“对啊”，说话人认为对方应当同意，与“笑着”的事实相符。", "不行吗": "语义：“不行吗”表示反问“不行”，与“你刚才还笑着”的事实相反。", "行吗": "语义：“行吗”是征求对方是否同意，不能表示“对啊”的肯定。", "没有吗": "搭配：“没有吗”针对有无提问，不能附在叙述句后表示肯定。"}, "sentence_index": 6, "correct_answer": "不是吗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我可能记错了，不是吗？", "explanation": "这里应该用〈对吧〉。“不是吗”预设对方应当同意，与“可能记错了”的不确定语气矛盾；征求意见时用“对吧”。"}, {"text": "咱们走吧，不是吗？", "explanation": "这里应该用〈好吗〉。“不是吗”用于说话人认为对方应当同意的事实，提出建议、征求意见要用“好吗”。"}, {"text": "我大概明天会下雨，不是吗？", "explanation": "这里应该用〈是吧〉。“大概”表示不确定，“不是吗”却预设对方应当同意；推测时要用“是吧”来征求意见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个道理大家都明白，是不是吗？", "corrected_sentence": "这个道理大家都明白，不是吗？", "error_description": "错误形式“是不是吗”，应为“不是吗”。“是不是”和“吗”都表示疑问，合用会重复；表示“对啊”的句末只用“不是吗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "咱们说好了周末去，不是吗吗？", "corrected_sentence": "咱们说好了周末去，不是吗？", "error_description": "错误形式“不是吗吗”，应为“不是吗”。句末语气词“吗”只用一个，重复会使句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
