INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你应该做的事。", "primary_collocate": null, "pronunciation": "zhí zé", "ipa": "ʈʂɻ̩˧˥ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "照顾孩子是父母的职责。", "target_word": "职责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都有自己的职责。", "target_word": "职责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护环境也是我们的职责。", "target_word": "职责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做饭不是我的职责，是妈妈的。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的职责是教学生，不只是考试。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得帮助朋友是自己的职责。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为班长，他想好好完成自己的职责。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子小的时候，爱护他们是大人的职责。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，让家人过得好是他的职责。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经尽到了你的职责，可以休息了。", "target_word": "职责", "complexity_tier": "T3", "furigana": "nǐ yǐjīng jìndào le nǐ de zhízé, kěyǐ xiūxi le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项职责", "label": "量词"}, {"form": "工作职责", "label": "复合"}, {"form": "職責", "label": "繁体"}], "register": "中性", "sense_fingerprint": "每个人在家庭或社会中应该做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0dc80df-7f5e-4a9f-9828-c08227afb6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职责", "is_correct": true, "explanation": "正确：“职责”指应尽的责任，照顾孩子正是父母应尽的责任。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是对成绩的回报，不是父母应尽的事，句意不通。"}, {"text": "爱好", "is_correct": false, "explanation": "语义：“爱好”指个人的兴趣，父母照顾孩子不是个人兴趣，句意不通。"}, {"text": "职业", "is_correct": false, "explanation": "搭配：“职业”指谋生的工作，不指所负的责任，与“照顾孩子”不搭配。"}], "explanations": {"职责": "正确：“职责”指应尽的责任，照顾孩子正是父母应尽的责任。", "奖励": "语义：“奖励”是对成绩的回报，不是父母应尽的事，句意不通。", "爱好": "语义：“爱好”指个人的兴趣，父母照顾孩子不是个人兴趣，句意不通。", "职业": "搭配：“职业”指谋生的工作，不指所负的责任，与“照顾孩子”不搭配。"}, "sentence_index": 0, "correct_answer": "职责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有使用公园的职责。", "explanation": "这里应该用〈权利〉。“职责”指应尽的义务，使用公园是可以享有的，要用〈权利〉。"}, {"text": "我的职责是喜欢音乐。", "explanation": "这里应该用〈爱好〉。“职责”指应尽的事，个人喜欢的事不能说成职责。"}, {"text": "他考了第一名，这是他应得的职责。", "explanation": "这里应该用〈奖励〉。“职责”是应尽的事，不是应得的回报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职责", "is_correct": true, "explanation": "正确：“完成职责”是固定搭配，指做好自己应尽的责任。"}, {"text": "规则", "is_correct": false, "explanation": "语义：“规则”是要遵守的条文，不是可以“完成”的任务，句意不通。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“完成”通常不与“礼物”搭配，应说“准备”或“送出”。"}, {"text": "习惯", "is_correct": false, "explanation": "搭配：“习惯”应说“养成”，不说“完成”，与此句不搭配。"}], "explanations": {"职责": "正确：“完成职责”是固定搭配，指做好自己应尽的责任。", "规则": "语义：“规则”是要遵守的条文，不是可以“完成”的任务，句意不通。", "礼物": "搭配：“完成”通常不与“礼物”搭配，应说“准备”或“送出”。", "习惯": "搭配：“习惯”应说“养成”，不说“完成”，与此句不搭配。"}, "sentence_index": 6, "correct_answer": "职责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的职责很强，什么难题都能解决。", "explanation": "这里应该用〈能力〉。“职责”不能用来形容人的能力强弱。"}, {"text": "他的职责很温和，大家都喜欢他。", "explanation": "这里应该用〈性格〉。“职责”不能用来形容人的性格。"}, {"text": "这件衣服的职责很高，我买不起。", "explanation": "这里应该用〈价格〉。“职责”不能用来说东西的价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他肩上有一条重要的职责。", "corrected_sentence": "他肩上有一项重要的职责。", "error_description": "“职责”的量词应用“项”，不能用“条”。“条”多用于规定、消息、意见等，与“职责”不搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直认真履行职责们。", "corrected_sentence": "他一直认真履行职责。", "error_description": "“职责”是抽象名词，不能加复数词尾“们”，应说“履行职责”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
