INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89712, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "职务范围内应尽的责任。", "primary_collocate": null, "pronunciation": "zhí zé", "ipa": "ʈʂɻ̩˧˥ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这件事不在我的工作职责里。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的职责是安排大家的工作。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同事还不清楚自己的岗位职责。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的职责是治病救人。", "target_word": "职责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司给每个人写清楚了职责。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有尽到管理员的职责，丢了东西。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会计的主要职责是管钱和记账。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，经理先说了各部门的职责。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作的职责很多，每天都很忙。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安的职责是看好大门，不让陌生人进来。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项职责", "label": "量词"}, {"form": "岗位职责", "label": "复合"}, {"form": "職責", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工作岗位上规定要负的责任", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0dc80df-7f5e-4a9f-9828-c08227afb6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职责", "is_correct": true, "explanation": "正确：“工作职责”指工作岗位上应负的责任，“不在……里”说的正是这个范围。"}, {"text": "待遇", "is_correct": false, "explanation": "语义：“待遇”指报酬和福利，“不在……里”说的是事务的范围，句意不通。"}, {"text": "薪水", "is_correct": false, "explanation": "语义：“薪水”是工资数额，不能表示事务的范围，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“工作颜色”不成立，“颜色”与“工作……里”不搭配。"}], "explanations": {"职责": "正确：“工作职责”指工作岗位上应负的责任，“不在……里”说的正是这个范围。", "待遇": "语义：“待遇”指报酬和福利，“不在……里”说的是事务的范围，句意不通。", "薪水": "语义：“薪水”是工资数额，不能表示事务的范围，句意不通。", "颜色": "搭配：“工作颜色”不成立，“颜色”与“工作……里”不搭配。"}, "sentence_index": 0, "correct_answer": "职责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的职责是成为一名医生。", "explanation": "这里应该用〈理想〉。“职责”指工作中应尽的责任，个人想成为的目标要用〈理想〉。"}, {"text": "这次考试，我的职责很好。", "explanation": "这里应该用〈成绩〉。“职责”不能用来说考试的好坏。"}, {"text": "妈妈送给我一份职责，我很开心。", "explanation": "这里应该用〈礼物〉。“职责”是抽象的责任，不能作为可以送的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职责", "is_correct": true, "explanation": "正确：“主要职责”指工作中最重要的责任，后面接具体工作内容，正合句意。"}, {"text": "作息", "is_correct": false, "explanation": "语义：“作息”指作息时间，不能说“管钱和记账”是作息，句意不通。"}, {"text": "工具", "is_correct": false, "explanation": "语义：“工具”是用具，不能说“工具是管钱和记账”，句意不通。"}, {"text": "习惯", "is_correct": false, "explanation": "搭配：“习惯”不能与“主要”和“管钱和记账”这样的工作内容搭配。"}], "explanations": {"职责": "正确：“主要职责”指工作中最重要的责任，后面接具体工作内容，正合句意。", "作息": "语义：“作息”指作息时间，不能说“管钱和记账”是作息，句意不通。", "工具": "语义：“工具”是用具，不能说“工具是管钱和记账”，句意不通。", "习惯": "搭配：“习惯”不能与“主要”和“管钱和记账”这样的工作内容搭配。"}, "sentence_index": 6, "correct_answer": "职责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校和我家的职责很远。", "explanation": "这里应该用〈距离〉。“职责”不能用来说两地之间的远近。"}, {"text": "他的职责比我高。", "explanation": "这里应该用〈身高〉。“职责”不能用来比较人的高矮。"}, {"text": "这件衣服的职责很漂亮。", "explanation": "这里应该用〈外观〉。“职责”不能用来形容衣服的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他承担着一把重要的职责。", "corrected_sentence": "他承担着一项重要的职责。", "error_description": "“职责”的量词应为“项”，不能用“把”。“把”用于有柄的器具，与抽象的“职责”搭配不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门卫的职责们是看好大门。", "corrected_sentence": "门卫的职责是看好大门。", "error_description": "“职责”是抽象名词，不能加复数词尾“们”，应说“门卫的职责”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4807fd0d-fb31-4d0f-bfc0-d134ecb28b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
