INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89713, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "官是在国家里管理很多人的人。", "primary_collocate": null, "pronunciation": "guān", "ipa": "kwan˥", "syllable_count": 1, "sentences": [{"text": "在古代，官管着很多人。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县里的官每天都很忙。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想长大以后当官，帮助穷人。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官要为老百姓做事。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷以前是村里的官。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个官管着一个大城市。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官坐在大堂上听人说话。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个官把老百姓放在心上。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是国家的官，不能乱收钱。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个官说，明天大家都要去修路。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "官员", "label": "复合"}, {"form": "当官", "label": "复合"}], "register": "中性", "sense_fingerprint": "官|名词|在国家里管理很多人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3b0bebd-d58b-44d0-81e3-335cff6f276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89713, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "官", "is_correct": true, "explanation": "guān（第一声），意思是在国家里管理很多人的人，即本词。"}, {"text": "管", "is_correct": false, "explanation": "guǎn（第三声）与 guān（第一声）声调不同，意思是管理。"}, {"text": "光", "is_correct": false, "explanation": "guāng 与 guān 韵母不同（-ng 与 -n），意思是光线。"}, {"text": "刚", "is_correct": false, "explanation": "gāng 与 guān 韵母不同（-ang 与 -an），意思是刚刚。"}, {"text": "冠", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是帽子或冠军。"}], "explanations": {"官": "guān（第一声），意思是在国家里管理很多人的人，即本词。", "管": "guǎn（第三声）与 guān（第一声）声调不同，意思是管理。", "光": "guāng 与 guān 韵母不同（-ng 与 -n），意思是光线。", "刚": "gāng 与 guān 韵母不同（-ang 与 -an），意思是刚刚。", "冠": "guàn（第四声）与 guān（第一声）声调不同，意思是帽子或冠军。"}, "sentence_index": null, "correct_answer": "官"}, "level_3": {"options": [{"text": "官", "is_correct": true, "explanation": "正确：“官”能管理很多人，与“管着很多人”的谓语相符。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不能管理人，与“管着很多人”的语境不符。"}, {"text": "书", "is_correct": false, "explanation": "语义：书是物品，不能管理很多人，与句意相矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“管”要求有能动的施事作主语，石头不能充当。"}], "explanations": {"官": "正确：“官”能管理很多人，与“管着很多人”的谓语相符。", "河": "语义：河不能管理人，与“管着很多人”的语境不符。", "书": "语义：书是物品，不能管理很多人，与句意相矛盾。", "石头": "配价：“管”要求有能动的施事作主语，石头不能充当。"}, "sentence_index": 0, "correct_answer": "官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位官要为病人治病。", "explanation": "这里应该用〈医生〉。官指在国家里管理很多人的人，给病人治病的人称为“医生”，不称为“官”。"}, {"text": "饭店的官要为客人服务。", "explanation": "这里应该用〈服务员〉。官指政府中的公职人员，饭店工作人员不称为“官”。"}, {"text": "超市的官要为顾客服务。", "explanation": "这里应该用〈售货员〉。官指政府中有职权的人，超市里的营业员不称为“官”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89713, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "官", "is_correct": true, "explanation": "guān（第一声），意思是在国家里管理很多人的人，即本词。"}, {"text": "钢", "is_correct": false, "explanation": "gāng 与 guān 韵母不同（-ang 与 -an），意思是钢铁。"}, {"text": "灌", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是灌溉。"}, {"text": "贯", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是贯穿。"}, {"text": "惯", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是习惯。"}], "explanations": {"官": "guān（第一声），意思是在国家里管理很多人的人，即本词。", "钢": "gāng 与 guān 韵母不同（-ang 与 -an），意思是钢铁。", "灌": "guàn（第四声）与 guān（第一声）声调不同，意思是灌溉。", "贯": "guàn（第四声）与 guān（第一声）声调不同，意思是贯穿。", "惯": "guàn（第四声）与 guān（第一声）声调不同，意思是习惯。"}, "sentence_index": null, "correct_answer": "官"}, "level_3": {"options": [{"text": "官", "is_correct": true, "explanation": "正确：“官”是有人身份的公职人员，能坐在大堂上听人说话。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不能在大堂上听讼，与句中的听人说话情节不符。"}, {"text": "石狮", "is_correct": false, "explanation": "语义：石狮是雕像，不能听人说话，与句意相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“坐”要求有生命的施事，桌子不能充当主语。"}], "explanations": {"官": "正确：“官”是有人身份的公职人员，能坐在大堂上听人说话。", "狗": "语义：狗不能在大堂上听讼，与句中的听人说话情节不符。", "石狮": "语义：石狮是雕像，不能听人说话，与句意相矛盾。", "桌子": "配价：“坐”要求有生命的施事，桌子不能充当主语。"}, "sentence_index": 6, "correct_answer": "官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的官长得很好看，大家都夸她。", "explanation": "这里的“官”指五官，但单用时不表示这个意思，与“政府中的公职”无关。"}, {"text": "他被人起诉了，正在打官呢。", "explanation": "这里的“官”指官司，单用时不表示诉讼，与“政府中的公职”无关。"}, {"text": "肝是人体很重要的官，要好好保养。", "explanation": "这里的“官”单用时不指器官，应说“器官”，与“在国家里管理很多人的人”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直想官当，为百姓做事。", "corrected_sentence": "他一直想当官，为百姓做事。", "error_description": "语序错误：“当官”是动宾结构，不能说成“官当”，应说“想当官”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只官昨天来过我们村。", "corrected_sentence": "那位官昨天来过我们村。", "error_description": "量词错误：“官”指人，应说“那位官”，不说“那只官”。“只”一般用于动物或小物件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
