INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89714, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "政府中担任公职、有职权的人。", "primary_collocate": null, "pronunciation": "guān", "ipa": "kwan˥", "syllable_count": 1, "sentences": [{"text": "他爸爸在县里做官。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个官很大，大家都怕他。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的叔叔是个小官。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当大官。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个清官，常常帮老百姓解决麻烦。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的官出门要坐轿子。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓都说这个官很好。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了官以后，很少回家。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想做官，只想教书。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个官带着人到村里看路。", "target_word": "官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "官员", "label": "复合"}, {"form": "当官", "label": "复合"}], "register": "中性", "sense_fingerprint": "官|名词|政府中有职权的公职人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3b0bebd-d58b-44d0-81e3-335cff6f276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89714, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "官", "is_correct": true, "explanation": "guān（第一声），意思是政府中有职权的公职人员，即本词。"}, {"text": "管", "is_correct": false, "explanation": "guǎn（第三声）与 guān（第一声）声调不同，意思是管理。"}, {"text": "光", "is_correct": false, "explanation": "guāng 与 guān 韵母不同（-ng 与 -n），意思是光线。"}, {"text": "刚", "is_correct": false, "explanation": "gāng 与 guān 韵母不同（-ang 与 -an），意思是刚刚。"}, {"text": "冠", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是帽子或冠军。"}], "explanations": {"官": "guān（第一声），意思是政府中有职权的公职人员，即本词。", "管": "guǎn（第三声）与 guān（第一声）声调不同，意思是管理。", "光": "guāng 与 guān 韵母不同（-ng 与 -n），意思是光线。", "刚": "gāng 与 guān 韵母不同（-ang 与 -an），意思是刚刚。", "冠": "guàn（第四声）与 guān（第一声）声调不同，意思是帽子或冠军。"}, "sentence_index": null, "correct_answer": "官"}, "level_3": {"options": [{"text": "官", "is_correct": true, "explanation": "正确：“做官”指在政府中担任公职，与“在县里”的语境一致。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "语义：蝴蝶是昆虫，不能在县里担任职务或身份，与句意不符。"}, {"text": "妃子", "is_correct": false, "explanation": "体貌：妃子是女性，与“他爸爸”的性别不符。"}, {"text": "蘑菇", "is_correct": false, "explanation": "语义：蘑菇是植物，不能在县里担任职务或身份，与句意不符。"}], "explanations": {"官": "正确：“做官”指在政府中担任公职，与“在县里”的语境一致。", "蝴蝶": "语义：蝴蝶是昆虫，不能在县里担任职务或身份，与句意不符。", "妃子": "体貌：妃子是女性，与“他爸爸”的性别不符。", "蘑菇": "语义：蘑菇是植物，不能在县里担任职务或身份，与句意不符。"}, "sentence_index": 0, "correct_answer": "官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位官每天给病人看病，很认真。", "explanation": "这里应该用〈医生〉。官指政府中有职权的人，给病人看病的人称为“医生”，不称为“官”。"}, {"text": "他在这家工厂当官，每天负责搬运货物。", "explanation": "这里应该用〈工人〉。官指政府中有职权的人，搬运货物的工人不称为“官”。"}, {"text": "他在这家饭店当官，每天负责做菜。", "explanation": "这里应该用〈厨师〉。官指政府中的公职，负责做菜的人不称为“官”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89714, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "官", "is_correct": true, "explanation": "guān（第一声），意思是政府中有职权的公职人员，即本词。"}, {"text": "钢", "is_correct": false, "explanation": "gāng 与 guān 韵母不同（-ang 与 -an），意思是钢铁。"}, {"text": "灌", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是灌溉。"}, {"text": "贯", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是贯穿。"}, {"text": "惯", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是习惯。"}], "explanations": {"官": "guān（第一声），意思是政府中有职权的公职人员，即本词。", "钢": "gāng 与 guān 韵母不同（-ang 与 -an），意思是钢铁。", "灌": "guàn（第四声）与 guān（第一声）声调不同，意思是灌溉。", "贯": "guàn（第四声）与 guān（第一声）声调不同，意思是贯穿。", "惯": "guàn（第四声）与 guān（第一声）声调不同，意思是习惯。"}, "sentence_index": null, "correct_answer": "官"}, "level_3": {"options": [{"text": "官", "is_correct": true, "explanation": "正确：“这个官”指有职权的公职人员，与“老百姓都说很好”的评价相符。"}, {"text": "恶霸", "is_correct": false, "explanation": "语义：恶霸欺压百姓，百姓不会称赞他，与“老百姓都说很好”的评价相矛盾。"}, {"text": "醉鬼", "is_correct": false, "explanation": "语义：醉鬼不是公职人员，与“老百姓都说很好”的评价不符，句意不通。"}, {"text": "鬼", "is_correct": false, "explanation": "搭配：“这个鬼”多用于指怪物或捣蛋的人，不能与“老百姓都说很好”搭配。"}], "explanations": {"官": "正确：“这个官”指有职权的公职人员，与“老百姓都说很好”的评价相符。", "恶霸": "语义：恶霸欺压百姓，百姓不会称赞他，与“老百姓都说很好”的评价相矛盾。", "醉鬼": "语义：醉鬼不是公职人员，与“老百姓都说很好”的评价不符，句意不通。", "鬼": "搭配：“这个鬼”多用于指怪物或捣蛋的人，不能与“老百姓都说很好”搭配。"}, "sentence_index": 6, "correct_answer": "官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的官很端正，大家都说他长得好。", "explanation": "这里的“官”指五官，但单用时不表示这个意思，与“政府中的公职”无关。"}, {"text": "他被人告了，现在还在打官。", "explanation": "这里的“官”指官司，单用时不表示诉讼，与“政府中的公职”无关。"}, {"text": "心脏是人体最重要的官，一定要好好保护。", "explanation": "这里的“官”单用时不指器官，应说“器官”，与“政府中的公职”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "县里新来了一只官，大家都很关心。", "corrected_sentence": "县里新来了一位官，大家都很关心。", "error_description": "量词错误：“官”指人，应说“一位官”，不说“一只官”。“只”多用于动物或小物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时做官过，后来回家种地。", "corrected_sentence": "他年轻时做过官，后来回家种地。", "error_description": "“过”的位置错误：离合词“做官”的“过”应插在“做”和“官”之间，说“做过官”，不能说“做官过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
