INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89721, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个人、家庭或小店里和钱怎么收、怎么花有关的事。", "primary_collocate": null, "pronunciation": "cái wù", "ipa": "tsʰai̯˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "我家的财务由妈妈来管。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王刚开了店，不懂财务。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的财务一直很清楚。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮朋友管财务，很认真。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的财务有点紧张。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请人教我怎么管家里的财务。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很会管理家里的财务。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚后，我们一起管财务。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的财务出了问题，没钱交房租。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板自己管着店里的财务。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "財務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人或家庭、小店里和钱怎么收、怎么花有关的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de9c1b0-5d2b-4ce9-8be1-a5bea4e21f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89721, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "搭配：天气不能由人来管理，“我家的天气由妈妈来管”说不通。"}, {"text": "财务", "is_correct": true, "explanation": "正确：“财务”指家里钱的收支和管理，可以由家人来管。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：月亮不能由人来管理，“我家的月亮由妈妈来管”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高是身体的特征，不能由人来管理。"}], "explanations": {"天气": "搭配：天气不能由人来管理，“我家的天气由妈妈来管”说不通。", "财务": "正确：“财务”指家里钱的收支和管理，可以由家人来管。", "月亮": "搭配：月亮不能由人来管理，“我家的月亮由妈妈来管”说不通。", "身高": "搭配：身高是身体的特征，不能由人来管理。"}, "sentence_index": 0, "correct_answer": "财务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有很多财务，都存在银行。", "explanation": "〈财产〉。财务指钱的收支和管理，说拥有的钱物要用“财产”，这里不能说“有很多财务”。"}, {"text": "他把财务捐给了孤儿院。", "explanation": "〈钱〉。财务是管理收支的事务，不是能捐出去的东西；这里捐的是钱，应该说“把钱捐给了孤儿院”。"}, {"text": "他去年的财务有五十万。", "explanation": "〈收入〉。财务指钱的收支管理，不是一年得到的钱数；说一年得到多少钱要用“收入”，应说“收入有五十万”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89721, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "搭配：太阳不能由人来管理，“管理家里的太阳”说不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：天空不能被人管理在家里，“管理家里的天空”说不通。"}, {"text": "财务", "is_correct": true, "explanation": "正确：“财务”指家里钱的收支管理，“很会管理家里的财务”符合语境。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：海洋是自然地理事物，不能被人管理在家里。"}], "explanations": {"太阳": "搭配：太阳不能由人来管理，“管理家里的太阳”说不通。", "天空": "搭配：天空不能被人管理在家里，“管理家里的天空”说不通。", "财务": "正确：“财务”指家里钱的收支管理，“很会管理家里的财务”符合语境。", "海洋": "搭配：海洋是自然地理事物，不能被人管理在家里。"}, "sentence_index": 6, "correct_answer": "财务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他前年买了很多财务，赚了不少钱。", "explanation": "〈股票〉。财务是管理收支的事务，不是可以买的东西；这里应该用“股票”。"}, {"text": "他把财务丢在了公交车上。", "explanation": "〈钱包〉。财务是抽象的收支管理，不能像钱包那样丢在车上；这里应该用“钱包”。"}, {"text": "他每个月都领财务。", "explanation": "〈工资〉。财务不是可以领取的东西；每月领取的是工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一个人管家里的财务们，从不出错。", "corrected_sentence": "她一个人管家里的财务，从不出错。", "error_description": "错误：“财务”后面加了“们”。“财务”是不可数的名词，不能加“们”表示复数；正确说法是“她一个人管家里的财务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸财务，妈妈都清楚。", "corrected_sentence": "爸爸的财务，妈妈都清楚。", "error_description": "错误：“爸爸”和“财务”之间漏了“的”。表示领属关系时要说“爸爸的财务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
