INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89722, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89722, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机构（如公司、学校）有关钱财收支、管理等的事务。", "primary_collocate": null, "pronunciation": "cái wù", "ipa": "tsʰai̯˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "公司的财务制度很严格。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的财务很透明。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每年公布一次财务情况。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财务出了问题，公司只好停工。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司负责财务工作。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的财务由专人管理。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机构的财务公开给大家看。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司也要把财务管清楚。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你检查一下这个月的财务。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的财务很健康，不缺钱。", "target_word": "财务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "財務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公司、学校等机构对钱财收支的管理事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de9c1b0-5d2b-4ce9-8be1-a5bea4e21f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "星星", "is_correct": false, "explanation": "语义：星星是天体，不属于公司的管理范围，“公司的星星制度”说不通。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵是天上的水汽，不能作为公司制度的修饰对象，“公司的云朵制度”说不通。"}, {"text": "财务", "is_correct": true, "explanation": "正确：“财务”指公司钱财收支的管理事务，“财务制度”是常用搭配。"}, {"text": "考古", "is_correct": false, "explanation": "搭配：“考古”是一个研究领域，不能用来修饰“制度”。"}], "explanations": {"星星": "语义：星星是天体，不属于公司的管理范围，“公司的星星制度”说不通。", "云朵": "语义：云朵是天上的水汽，不能作为公司制度的修饰对象，“公司的云朵制度”说不通。", "财务": "正确：“财务”指公司钱财收支的管理事务，“财务制度”是常用搭配。", "考古": "搭配：“考古”是一个研究领域，不能用来修饰“制度”。"}, "sentence_index": 0, "correct_answer": "财务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老板很有财务，做事很稳当。", "explanation": "〈能力〉。财务是事务，不能说“有财务”；这里应该说“很有能力”。"}, {"text": "这家工厂新买了一批财务。", "explanation": "〈设备〉。财务不是能买的物品；这里买的是机器，应该用“设备”。"}, {"text": "这家企业每月生产大量财务。", "explanation": "〈产品〉。财务是管理收支的事务，不是能生产的东西；企业生产的应该是“产品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：心情是个人的感受，不能像财务一样公开给大家看。"}, {"text": "月光", "is_correct": false, "explanation": "搭配：月光不是机构可以公开的事物，“这个机构的月光公开给大家看”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重是个人的身体数据，与“机构的……公开”不搭配。"}, {"text": "财务", "is_correct": true, "explanation": "正确：机构的财务公开给大家看，是常见的说法。"}], "explanations": {"心情": "语义：心情是个人的感受，不能像财务一样公开给大家看。", "月光": "搭配：月光不是机构可以公开的事物，“这个机构的月光公开给大家看”说不通。", "体重": "搭配：体重是个人的身体数据，与“机构的……公开”不搭配。", "财务": "正确：机构的财务公开给大家看，是常见的说法。"}, "sentence_index": 6, "correct_answer": "财务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的财务很健康，身体也好。", "explanation": "〈身体〉。财务不能用来形容人的健康；这里应该用“身体”。"}, {"text": "他的财务很广，朋友很多。", "explanation": "〈人脉〉。财务不能用“广”来形容；这里应该用“人脉”。"}, {"text": "这次年会的财务定在了大礼堂。", "explanation": "〈场地〉。财务是收支管理，不是地点；年会定在哪里要说“场地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天在公司里财务。", "corrected_sentence": "他每天在公司里管财务。", "error_description": "错误：漏了动词“管”。“财务”是名词，不能直接作谓语；应说“他每天在公司里管财务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个月，公司的会议上都要讨论财务们。", "corrected_sentence": "每个月，公司的会议上都要讨论财务。", "error_description": "错误：“财务”是抽象的事务名词，不能加“们”表示复数。应说“讨论财务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
