INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89723, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "救是帮人逃出危险。", "primary_collocate": null, "pronunciation": "jiù", "ipa": "tɕjoʊ˥˩", "syllable_count": 1, "sentences": [{"text": "他跳进河里，把小孩救了上来。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员冲进火里救人。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用了三个小时才救回病人。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人掉进水里，大家快去救他！", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把困在车里的老人救了出来。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候救过一条落水的狗。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救生员看见有人游不动，马上游过去救他。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，工人们挖了一夜想救人。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机很勇敢，救了车里所有的人。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在河边大声叫，请人来救孩子。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "救了", "label": "体标"}, {"form": "救过", "label": "体标"}, {"form": "救救", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把处在危险中的人从危险里救出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3b0bebd-d58b-44d0-81e3-335cff6f276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89723, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "救", "is_correct": true, "explanation": "jiù（第四声），意思是把处在危险中的人从危险里救出来，即本词。"}, {"text": "久", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是时间长。"}, {"text": "酒", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是酒水。"}, {"text": "九", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是数字九。"}, {"text": "纠", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是纠正。"}], "explanations": {"救": "jiù（第四声），意思是把处在危险中的人从危险里救出来，即本词。", "久": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是时间长。", "酒": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是酒水。", "九": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是数字九。", "纠": "jiū（第一声）与 jiù（第四声）声调不同，意思是纠正。"}, "sentence_index": null, "correct_answer": "救"}, "level_3": {"options": [{"text": "救", "is_correct": true, "explanation": "正确：“救了上来”表示把小孩从水里救出来，与跳进河里的情节一致。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛掷，与跳进河里救人的情节相反，不能说把小孩扔上来。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是食用，不能用于人，与救人的情节完全不符。"}, {"text": "忘", "is_correct": false, "explanation": "搭配：“忘”不能与“了上来”构成趋向补语结构，“忘了上来”不成立。"}], "explanations": {"救": "正确：“救了上来”表示把小孩从水里救出来，与跳进河里的情节一致。", "扔": "语义：扔是抛掷，与跳进河里救人的情节相反，不能说把小孩扔上来。", "吃": "语义：吃是食用，不能用于人，与救人的情节完全不符。", "忘": "搭配：“忘”不能与“了上来”构成趋向补语结构，“忘了上来”不成立。"}, "sentence_index": 0, "correct_answer": "救"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我救妈妈去买菜。", "explanation": "这里应该用〈陪〉。救是把处于危险中的人救出来，不用于一般的陪同。"}, {"text": "我们救他搬家。", "explanation": "这里应该用〈帮〉。救特指把人从危险中救出，搬家这类一般帮忙不能用“救”。"}, {"text": "他救住我的手，不让我走。", "explanation": "这里应该用〈拉〉。救用于脱离危险，一般的拉住动作不用“救”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89723, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "救", "is_correct": true, "explanation": "jiù（第四声），意思是把处在危险中的人从危险里救出来，即本词。"}, {"text": "揪", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是揪住、拉拽。"}, {"text": "究", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是探究、追问。"}, {"text": "韭", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是韭菜。"}], "explanations": {"救": "jiù（第四声），意思是把处在危险中的人从危险里救出来，即本词。", "揪": "jiū（第一声）与 jiù（第四声）声调不同，意思是揪住、拉拽。", "究": "jiū（第一声）与 jiù（第四声）声调不同，意思是探究、追问。", "韭": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是韭菜。"}, "sentence_index": null, "correct_answer": "救"}, "level_3": {"options": [{"text": "救", "is_correct": true, "explanation": "正确：“游过去救他”表示救生员去救溺水的人，与游不动的情节一致。"}, {"text": "打", "is_correct": false, "explanation": "语义：打是殴打，与救生员游过去帮助溺水者的情节矛盾。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿咬人，与救生员的救助行为完全相反。"}, {"text": "淹", "is_correct": false, "explanation": "搭配：“淹”表示淹没，不能用于救生员游过去救人的语境中。"}], "explanations": {"救": "正确：“游过去救他”表示救生员去救溺水的人，与游不动的情节一致。", "打": "语义：打是殴打，与救生员游过去帮助溺水者的情节矛盾。", "咬": "语义：咬是用牙齿咬人，与救生员的救助行为完全相反。", "淹": "搭配：“淹”表示淹没，不能用于救生员游过去救人的语境中。"}, "sentence_index": 6, "correct_answer": "救"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师救了我一杯果汁，我很感谢他。", "explanation": "这里应该用〈给〉。救表示使人脱离危险，不表示给予。"}, {"text": "他救起一块石头扔进河里。", "explanation": "这里应该用〈捡〉。救指使人或物脱离危险，不能用于捡起东西。"}, {"text": "他一口气救完了一碗饭。", "explanation": "这里应该用〈吃〉。救表示使人脱离危险，不表示吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员昨天冲进火里救了了一个老人。", "corrected_sentence": "消防员昨天冲进火里救了一个老人。", "error_description": "“了”重复：“救”后只用一个“了”，应说“救了一个老人”，不能说“救了了一个老人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她曾经救过过三个人。", "corrected_sentence": "她曾经救过三个人。", "error_description": "“过”重复：“救”后只用一个“过”，应说“救过三个人”，不能说“救过过三个人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
