INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89724, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使脱离危险或灾难；帮助。", "primary_collocate": null, "pronunciation": "jiù", "ipa": "tɕjoʊ˥˩", "syllable_count": 1, "sentences": [{"text": "这笔钱能救公司，也能救工人的饭碗。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想办法救这家快要倒闭的小店。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，再晚送来就救不了了。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们提水来救那间着火的房子。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪太大，没人能救那些牛羊。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在我最难的时候救了我。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱捐给医院，想救更多的病人。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场及时雨救了今年的庄稼。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的几句话救了这个想放弃的学生。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生，请你一定要救救我的孩子！", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "救了", "label": "体标"}, {"form": "救过", "label": "体标"}, {"form": "救救", "label": "重叠"}], "register": "中性", "sense_fingerprint": "使人或事物摆脱危险、灾难或困境，给予帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3b0bebd-d58b-44d0-81e3-335cff6f276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89724, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "救", "is_correct": true, "explanation": "jiù（第四声），意思是使人或事物摆脱危险、给予帮助，即本词。"}, {"text": "久", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是时间长。"}, {"text": "酒", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是酒水。"}, {"text": "九", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是数字九。"}, {"text": "纠", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是纠正。"}], "explanations": {"救": "jiù（第四声），意思是使人或事物摆脱危险、给予帮助，即本词。", "久": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是时间长。", "酒": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是酒水。", "九": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是数字九。", "纠": "jiū（第一声）与 jiù（第四声）声调不同，意思是纠正。"}, "sentence_index": null, "correct_answer": "救"}, "level_3": {"options": [{"text": "救", "is_correct": true, "explanation": "正确：“救公司”与“救工人的饭碗”构成对照，表示用钱帮助摆脱困境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃不能用于公司，与“救工人的饭碗”的对照语义不成立。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”指拆解，钱不能拆公司，与“能……也能”的正面对照不协调。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”后通常接接收者，“送公司”不成立。"}], "explanations": {"救": "正确：“救公司”与“救工人的饭碗”构成对照，表示用钱帮助摆脱困境。", "吃": "语义：吃不能用于公司，与“救工人的饭碗”的对照语义不成立。", "拆": "搭配：“拆”指拆解，钱不能拆公司，与“能……也能”的正面对照不协调。", "送": "搭配：“送”后通常接接收者，“送公司”不成立。"}, "sentence_index": 0, "correct_answer": "救"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上救着水桶去浇花。", "explanation": "这里应该用〈提〉。救表示使脱离危险或灾难，不表示提拿东西。"}, {"text": "服务员把菜救给客人。", "explanation": "这里应该用〈端〉。救表示使脱离危险或灾难，不表示端送食物。"}, {"text": "他每天认真地救地板。", "explanation": "这里应该用〈擦〉。救表示使脱离危险或灾难，不表示擦洗地板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89724, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "救", "is_correct": true, "explanation": "jiù（第四声），意思是使人或事物摆脱危险、给予帮助，即本词。"}, {"text": "揪", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是揪住、拉拽。"}, {"text": "究", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是探究、追问。"}, {"text": "韭", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是韭菜。"}], "explanations": {"救": "jiù（第四声），意思是使人或事物摆脱危险、给予帮助，即本词。", "揪": "jiū（第一声）与 jiù（第四声）声调不同，意思是揪住、拉拽。", "究": "jiū（第一声）与 jiù（第四声）声调不同，意思是探究、追问。", "韭": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是韭菜。"}, "sentence_index": null, "correct_answer": "救"}, "level_3": {"options": [{"text": "救", "is_correct": true, "explanation": "正确：“想救更多的病人”表示希望帮助更多病人摆脱病痛，与捐钱的善意语境一致。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃病人与捐钱给医院的善意语境完全矛盾。"}, {"text": "打", "is_correct": false, "explanation": "语义：打病人与捐款的善意语境矛盾，不能表示帮助。"}, {"text": "骗", "is_correct": false, "explanation": "搭配：“骗”通常接受骗对象，与“想……更多的病人”的善意目的不协调。"}], "explanations": {"救": "正确：“想救更多的病人”表示希望帮助更多病人摆脱病痛，与捐钱的善意语境一致。", "吃": "语义：吃病人与捐钱给医院的善意语境完全矛盾。", "打": "语义：打病人与捐款的善意语境矛盾，不能表示帮助。", "骗": "搭配：“骗”通常接受骗对象，与“想……更多的病人”的善意目的不协调。"}, "sentence_index": 6, "correct_answer": "救"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店员救了我一杯咖啡，我很感谢他。", "explanation": "这里应该用〈给〉。救表示使脱离危险或灾难，不表示给予。"}, {"text": "他把屋子救得很整齐。", "explanation": "这里应该用〈收拾〉。救表示使脱离危险或灾难，不表示整理屋子。"}, {"text": "他一口气救完了一碗饭。", "explanation": "这里应该用〈吃〉。救表示使脱离危险或灾难，不表示吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生救活得这个孩子。", "corrected_sentence": "医生救得活这个孩子。", "error_description": "补语位置错误：“救活”是结果补语，可能式应说“救得活”，“得”插在“救”和“活”之间，不能说“救活得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位护士救了活一只小鸟。", "corrected_sentence": "这位护士救活了一只小鸟。", "error_description": "补语位置错误：“救活”是结果补语，“了”应放在“活”之后，说“救活了”，不能说“救了活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进", "is_correct": true, "explanation": "进与退为反义：进指向前，退指向后。"}, {"text": "停", "is_correct": false, "explanation": "停是停止，与退的“向后走”义没有反义关系。"}, {"text": "坐", "is_correct": false, "explanation": "坐是落座，与“向后走”义无反义关系。"}, {"text": "来", "is_correct": false, "explanation": "来指到来，与“向后走”义无反义关系。"}], "correct_answer": "进", "explanations": {"进": "进与退为反义：进指向前，退指向后。", "停": "停是停止，与退的“向后走”义没有反义关系。", "坐": "坐是落座，与“向后走”义无反义关系。", "来": "来指到来，与“向后走”义无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前进", "is_correct": true, "explanation": "前进与后退为反义，退的“向后走”义与之正相反。"}, {"text": "跑", "is_correct": false, "explanation": "跑是奔跑，不与“向后走”构成反义。"}, {"text": "站", "is_correct": false, "explanation": "站是站立，不与“向后走”构成反义。"}, {"text": "放", "is_correct": false, "explanation": "放是放置，不与“向后走”构成反义。"}], "correct_answer": "前进", "explanations": {"前进": "前进与后退为反义，退的“向后走”义与之正相反。", "跑": "跑是奔跑，不与“向后走”构成反义。", "站": "站是站立，不与“向后走”构成反义。", "放": "放是放置，不与“向后走”构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向后走，离开前面。", "primary_collocate": null, "pronunciation": "tuì", "ipa": "tʰuei˥˩", "syllable_count": 1, "sentences": [{"text": "前面有水，请大家往后退。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吓得退了两步。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车太近了，你再退一点。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请往后退一步。”", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到大狗，小女孩马上往后退。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边说话，一边向后退。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的路不通，我们往后退吧。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机把车往后退了一点。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火太大了，大家都退到门外。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们怕得退到妈妈身后。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "退了", "label": "体标"}, {"form": "退过", "label": "体标"}, {"form": "退着", "label": "体标"}, {"form": "退后", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或车向后走几步，离开前面的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf08968a-b4cb-4d8f-9f5e-355294b2811a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "退", "is_correct": true, "explanation": "退（tuì）意思是向后移动，即本词条。"}, {"text": "推", "is_correct": false, "explanation": "推（tuī，第一声）与退（tuì，第四声）声调不同，意思是用力使物体移动。"}, {"text": "腿", "is_correct": false, "explanation": "腿（tuǐ，第三声）与退（tuì，第四声）声调不同，意思是身体的下肢。"}, {"text": "对", "is_correct": false, "explanation": "对（duì）与退的声母不同（d 与 t），意思是正确、对待。"}, {"text": "脆", "is_correct": false, "explanation": "脆（cuì）与退的声母不同（c 与 t），意思是易碎、松脆。"}], "explanations": {"退": "退（tuì）意思是向后移动，即本词条。", "推": "推（tuī，第一声）与退（tuì，第四声）声调不同，意思是用力使物体移动。", "腿": "腿（tuǐ，第三声）与退（tuì，第四声）声调不同，意思是身体的下肢。", "对": "对（duì）与退的声母不同（d 与 t），意思是正确、对待。", "脆": "脆（cuì）与退的声母不同（c 与 t），意思是易碎、松脆。"}, "sentence_index": null, "correct_answer": "退"}, "level_3": {"options": [{"text": "退", "is_correct": true, "explanation": "正确。退指向后移动，与“往后”相合。"}, {"text": "倒", "is_correct": false, "explanation": "语义：倒指身体倒下，不是有秩序地向后移动。"}, {"text": "躺", "is_correct": false, "explanation": "语义：躺指身体平卧，是姿势而非有秩序地向后移动，不符合“请大家往后”的指令。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔指跌落，不是有意地向后移动。"}], "explanations": {"退": "正确。退指向后移动，与“往后”相合。", "倒": "语义：倒指身体倒下，不是有秩序地向后移动。", "躺": "语义：躺指身体平卧，是姿势而非有秩序地向后移动，不符合“请大家往后”的指令。", "摔": "语义：摔指跌落，不是有意地向后移动。"}, "sentence_index": 0, "correct_answer": "退"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一进门就把外套退了下来。", "explanation": "这里应该用〈脱〉。退指向后移动，脱衣服要用脱。"}, {"text": "他一步一步退上了山。", "explanation": "这里应该用〈爬〉。退表示向后移动或离开，不能表示向上行进；往上攀登要用爬。"}, {"text": "他看见蛇，马上退了草地。", "explanation": "这里应该用〈离开〉。退表示向后走或离开前面，不能以“草地”这类场所作宾语表示离去；离开草地要用离开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "退", "is_correct": true, "explanation": "退（tuì）意思是向后移动，即本词条。"}, {"text": "队", "is_correct": false, "explanation": "队（duì）与退的声母不同（d 与 t），意思是队伍。"}, {"text": "最", "is_correct": false, "explanation": "最（zuì）与退的声母不同（z 与 t），意思是程度最高。"}, {"text": "碎", "is_correct": false, "explanation": "碎（suì）与退的声母不同（s 与 t），意思是破碎。"}, {"text": "翠", "is_correct": false, "explanation": "翠（cuì）与退的声母不同（c 与 t），意思是翠绿色。"}], "explanations": {"退": "退（tuì）意思是向后移动，即本词条。", "队": "队（duì）与退的声母不同（d 与 t），意思是队伍。", "最": "最（zuì）与退的声母不同（z 与 t），意思是程度最高。", "碎": "碎（suì）与退的声母不同（s 与 t），意思是破碎。", "翠": "翠（cuì）与退的声母不同（c 与 t），意思是翠绿色。"}, "sentence_index": null, "correct_answer": "退"}, "level_3": {"options": [{"text": "退", "is_correct": true, "explanation": "正确。退指向后移动，与“前面的路不通”的结论相合。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：踢需要宾语，“往后踢”表示用脚击打，不是移动路线。"}, {"text": "扑", "is_correct": false, "explanation": "语义：扑指身体猛然向前或向某处扑去，与“我们往后退吧”的有秩序后退不符。"}, {"text": "吐", "is_correct": false, "explanation": "语义：吐指从口中排出，与移动无关。"}], "explanations": {"退": "正确。退指向后移动，与“前面的路不通”的结论相合。", "踢": "搭配：踢需要宾语，“往后踢”表示用脚击打，不是移动路线。", "扑": "语义：扑指身体猛然向前或向某处扑去，与“我们往后退吧”的有秩序后退不符。", "吐": "语义：吐指从口中排出，与移动无关。"}, "sentence_index": 6, "correct_answer": "退"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力把柜门退开了。", "explanation": "这里应该用〈推〉。推指用力使物体移动，退指人或车自己向后移动。"}, {"text": "他用布把桌子退干净了。", "explanation": "这里应该用〈擦〉。退表示向后走或离开，不能用来表示擦去污渍；擦桌子要用擦。"}, {"text": "他往前退了一步，走到了桌子边。", "explanation": "这里应该用〈前进〉。退是向后移动，往前走要用前进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他往后了退两步，让出了路。", "corrected_sentence": "他往后退了两步，让出了路。", "error_description": "错误形式：“了”放在“退”前；正确形式：“退了两步”；原因：体标“了”须紧跟动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车子往后了退一步，大家松了口气。", "corrected_sentence": "车子往后退了一步，大家松了口气。", "error_description": "错误形式：“往后了退一步”；正确形式：“往后退了一步”；原因：体标“了”须紧跟动词“退”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进", "is_correct": true, "explanation": "进与退为反义：退指向后离开，进指向前进入。"}, {"text": "停", "is_correct": false, "explanation": "停是停止，与退的“离开”义没有反义关系。"}, {"text": "坐", "is_correct": false, "explanation": "坐是落座，与退的任何义项都不构成反义。"}, {"text": "来", "is_correct": false, "explanation": "来指到来，与退不构成反义，其反义是去。"}], "correct_answer": "进", "explanations": {"进": "进与退为反义：退指向后离开，进指向前进入。", "停": "停是停止，与退的“离开”义没有反义关系。", "坐": "坐是落座，与退的任何义项都不构成反义。", "来": "来指到来，与退不构成反义，其反义是去。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "涨", "is_correct": true, "explanation": "涨与退为反义，水涨与水退相对，如“潮涨潮退”。"}, {"text": "跑", "is_correct": false, "explanation": "跑是奔跑，与退的水退义没有反义关系。"}, {"text": "站", "is_correct": false, "explanation": "站是站立，与水退义无反义关系。"}, {"text": "放", "is_correct": false, "explanation": "放是放置，与退的任何义项都不构成反义。"}], "correct_answer": "涨", "explanations": {"涨": "涨与退为反义，水涨与水退相对，如“潮涨潮退”。", "跑": "跑是奔跑，与退的水退义没有反义关系。", "站": "站是站立，与水退义无反义关系。", "放": "放是放置，与退的任何义项都不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向后移动；离开。", "primary_collocate": null, "pronunciation": "tuì", "ipa": "tʰuei˥˩", "syllable_count": 1, "sentences": [{"text": "大水慢慢退了，路又能走了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上海边的潮水已经退了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人打不过我们，只好退了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤了，比赛中途就退了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮以后，大雾慢慢退了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水退了以后，地上都是泥。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累了，想从队伍里退下来休息。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队打了败仗，一直退到河边。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组他不喜欢，上个月就退了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水退了，村民们回家打扫房子。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "退了", "label": "体标"}, {"form": "退过", "label": "体标"}, {"form": "退着", "label": "体标"}, {"form": "退后", "label": "复合"}], "register": "中性", "sense_fingerprint": "水、军队、人从原处向后移动或离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf08968a-b4cb-4d8f-9f5e-355294b2811a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "退", "is_correct": true, "explanation": "退（tuì）意思是向后移动或离开，即本词条。"}, {"text": "推", "is_correct": false, "explanation": "推（tuī，第一声）与退（tuì，第四声）声调不同，意思是用力使物体移动。"}, {"text": "腿", "is_correct": false, "explanation": "腿（tuǐ，第三声）与退（tuì，第四声）声调不同，意思是身体的下肢。"}, {"text": "对", "is_correct": false, "explanation": "对（duì）与退的声母不同（d 与 t），意思是正确、对待。"}, {"text": "脆", "is_correct": false, "explanation": "脆（cuì）与退的声母不同（c 与 t），意思是易碎、松脆。"}], "explanations": {"退": "退（tuì）意思是向后移动或离开，即本词条。", "推": "推（tuī，第一声）与退（tuì，第四声）声调不同，意思是用力使物体移动。", "腿": "腿（tuǐ，第三声）与退（tuì，第四声）声调不同，意思是身体的下肢。", "对": "对（duì）与退的声母不同（d 与 t），意思是正确、对待。", "脆": "脆（cuì）与退的声母不同（c 与 t），意思是易碎、松脆。"}, "sentence_index": null, "correct_answer": "退"}, "level_3": {"options": [{"text": "退", "is_correct": true, "explanation": "正确。退指水位下降、离开原处，所以路又能走了。"}, {"text": "涨", "is_correct": false, "explanation": "语义：涨指水位上升，与“路又能走了”的结果相矛盾。"}, {"text": "进", "is_correct": false, "explanation": "语义：进指水流入，水流进来不会让路变得能走，与语境不符。"}, {"text": "冲", "is_correct": false, "explanation": "语义：冲指水流猛烈地冲击、奔涌，与“慢慢”的缓慢态势不合，也不会让路变得能走。"}], "explanations": {"退": "正确。退指水位下降、离开原处，所以路又能走了。", "涨": "语义：涨指水位上升，与“路又能走了”的结果相矛盾。", "进": "语义：进指水流入，水流进来不会让路变得能走，与语境不符。", "冲": "语义：冲指水流猛烈地冲击、奔涌，与“慢慢”的缓慢态势不合，也不会让路变得能走。"}, "sentence_index": 0, "correct_answer": "退"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天的气温退了不少。", "explanation": "这里应该用〈降低〉。退用于水、军队、人等向后移动或离开，气温下降要用降低。"}, {"text": "工厂的产量退了不少。", "explanation": "这里应该用〈减少〉。退不用来指数量下降，产量减少要用减少。"}, {"text": "他一下班就退了办公室。", "explanation": "这里应该用〈离开〉。退表示向后移动或退出，不能直接以“办公室”这类场所作宾语表示离去；下班离开办公室要用离开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "退", "is_correct": true, "explanation": "退（tuì）意思是向后移动或离开，即本词条。"}, {"text": "队", "is_correct": false, "explanation": "队（duì）与退的声母不同（d 与 t），意思是队伍。"}, {"text": "最", "is_correct": false, "explanation": "最（zuì）与退的声母不同（z 与 t），意思是程度最高。"}, {"text": "碎", "is_correct": false, "explanation": "碎（suì）与退的声母不同（s 与 t），意思是破碎。"}, {"text": "翠", "is_correct": false, "explanation": "翠（cuì）与退的声母不同（c 与 t），意思是翠绿色。"}], "explanations": {"退": "退（tuì）意思是向后移动或离开，即本词条。", "队": "队（duì）与退的声母不同（d 与 t），意思是队伍。", "最": "最（zuì）与退的声母不同（z 与 t），意思是程度最高。", "碎": "碎（suì）与退的声母不同（s 与 t），意思是破碎。", "翠": "翠（cuì）与退的声母不同（c 与 t），意思是翠绿色。"}, "sentence_index": null, "correct_answer": "退"}, "level_3": {"options": [{"text": "退", "is_correct": true, "explanation": "正确。退下来指主动离开队伍，与“想休息”相合。"}, {"text": "掉", "is_correct": false, "explanation": "语义：掉指失足或意外坠落，不是主动离开队伍。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：扔是抛出，人不能用“扔”的方式从队伍里下来。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔指跌倒受伤，与“想休息”的主动意愿相反。"}], "explanations": {"退": "正确。退下来指主动离开队伍，与“想休息”相合。", "掉": "语义：掉指失足或意外坠落，不是主动离开队伍。", "扔": "搭配：扔是抛出，人不能用“扔”的方式从队伍里下来。", "摔": "语义：摔指跌倒受伤，与“想休息”的主动意愿相反。"}, "sentence_index": 6, "correct_answer": "退"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他进门后退下了外套。", "explanation": "这里应该用〈脱〉。退指向后移动或离开，脱掉衣服要用脱。"}, {"text": "他把垃圾退了。", "explanation": "这里应该用〈扔〉。退表示向后移动或离开，丢掉垃圾要用扔。"}, {"text": "他用力把门退开了。", "explanation": "这里应该用〈推〉。推指用力使物体移动，退指人或车自己向后移动，不能用来推门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洪水慢慢了退，屋子里的泥也干了。", "corrected_sentence": "洪水慢慢退了，屋子里的泥也干了。", "error_description": "错误形式：“了”放在“退”前；正确形式：“退了”；原因：体标“了”须紧跟动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "军队打了败仗，一路了退三里路。", "corrected_sentence": "军队打了败仗，一路退了三里路。", "error_description": "错误形式：“了”放在“退”前，写作“一路了退三里路”；正确形式：“一路退了三里路”；原因：体标“了”须紧跟动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
