INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89753, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "福利是单位或国家给大家的好处。", "primary_collocate": null, "pronunciation": "fú lì", "ipa": "fu˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的福利很好,每年都体检。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们的福利包括饭补和住房。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换工作是因为新公司福利更好。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家给老人很多福利,比如免费坐公交。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给每位工人发了过节福利。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们单位的福利不多,但是工作很轻松。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的福利能让员工留下来。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市给孩子的福利越来越多。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说,明年会把大家的福利提高一点。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时,公司发的福利是一箱水果。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "福利待遇", "label": "复合"}, {"form": "社会福利", "label": "复合"}, {"form": "福利院", "label": "复合"}], "register": "中性", "sense_fingerprint": "单位或国家发给大家的好处和待遇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3b0bebd-d58b-44d0-81e3-335cff6f276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89753, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "福利", "is_correct": true, "explanation": "正确。“福利”指单位给员工的好处，与“很好”“每年都体检”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是公司提供的东西，“公司的天气很好”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌特征，不能用来形容一家公司。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”一般说多少，不用“很好”来形容。"}], "explanations": {"福利": "正确。“福利”指单位给员工的好处，与“很好”“每年都体检”相合。", "天气": "语义：天气是自然现象，不是公司提供的东西，“公司的天气很好”说不通。", "身高": "体貌：身高是人的体貌特征，不能用来形容一家公司。", "数量": "搭配：“数量”一般说多少，不用“很好”来形容。"}, "sentence_index": 0, "correct_answer": "福利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他读书的福利是能认识很多朋友。", "explanation": "这里应该用〈好处〉。福利指单位或国家给成员的待遇，个人读书的收获不能叫福利。"}, {"text": "公司给每个人发了一块福利。", "explanation": "这里应该用〈项〉。福利的量词是“项”或“份”，“块”用于成块的东西，不能用于福利。"}, {"text": "这笔存款每年的福利是三厘。", "explanation": "这里应该用〈利息〉。存款的收益叫利息，福利指单位或国家给成员的待遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89753, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "福利", "is_correct": true, "explanation": "正确。“福利”是员工能得到的好处，能让员工留下来。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道与“让员工留下来”无关，句子说不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的身体特征，不能作为留住员工的好处。"}, {"text": "进度", "is_correct": false, "explanation": "语义：进度指工作推进的程度，与“留住员工”无关。"}], "explanations": {"福利": "正确。“福利”是员工能得到的好处，能让员工留下来。", "味道": "语义：味道与“让员工留下来”无关，句子说不通。", "体重": "体貌：体重是人的身体特征，不能作为留住员工的好处。", "进度": "语义：进度指工作推进的程度，与“留住员工”无关。"}, "sentence_index": 6, "correct_answer": "福利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他考了第一名，学校给他的福利是一本字典。", "explanation": "这里应该用〈奖励〉。奖励是对表现好的人给予的，福利是单位或国家给全体成员的待遇。"}, {"text": "这只股票今年的福利比去年多了一倍。", "explanation": "这里应该用〈收益〉。股票的回报叫收益，福利指单位或国家给成员的待遇。"}, {"text": "这张车票的福利很便宜。", "explanation": "这里应该用〈票价〉。车票的价格叫票价，福利指单位或国家给成员的待遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司今年新增了一只带薪休假的福利。", "corrected_sentence": "公司今年新增了一项带薪休假的福利。", "error_description": "量词错误：“福利”应用“项”，不能用“只”（“只”用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家小公司得福利很好，员工都很开心。", "corrected_sentence": "这家小公司的福利很好，员工都很开心。", "error_description": "助词错误：“小公司”与“福利”之间应用“的”，不能用“得”，应说“这家小公司的福利很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
