INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家、单位给予成员的生活上的待遇和好处。", "primary_collocate": null, "pronunciation": "fú lì", "ipa": "fu˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "工作满五年,员工可以享受带薪休假的福利。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的福利很好,看病几乎不用花钱。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司取消了员工的交通福利。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为老师们提供了住房福利。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗和教育都是国家给人民的重要福利。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的福利和别的工人一样。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后,他仍然享受着公司的福利。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了留住人才,公司增加了员工福利。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "福利好的工作,很多年轻人都想去。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想改善农民的福利。", "target_word": "福利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "福利待遇", "label": "复合"}, {"form": "社会福利", "label": "复合"}, {"form": "福利院", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家或单位给成员在生活上的待遇和好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3b0bebd-d58b-44d0-81e3-335cff6f276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "福利", "is_correct": true, "explanation": "正确。“福利”是国家或单位给成员的待遇，可以被员工享受。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的课业，不是员工能享受的待遇。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“享受”后接待遇、假期等，不说“享受脾气”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌特征，不能作为员工享受的对象。"}], "explanations": {"福利": "正确。“福利”是国家或单位给成员的待遇，可以被员工享受。", "作业": "语义：作业是学生的课业，不是员工能享受的待遇。", "脾气": "搭配：“享受”后接待遇、假期等，不说“享受脾气”。", "身高": "体貌：身高是人的体貌特征，不能作为员工享受的对象。"}, "sentence_index": 0, "correct_answer": "福利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他参加培训的福利是学到了技术。", "explanation": "这里应该用〈好处〉。福利是单位或国家给成员的待遇，学到技术的收获不叫福利。"}, {"text": "学校为老师们提供了一条住房福利。", "explanation": "这里应该用〈项〉。福利的量词是“项”或“份”，“条”用于细长的东西，不能用于福利。"}, {"text": "这块地今年的福利很好，产量高。", "explanation": "这里应该用〈收成〉。庄稼的收获叫收成，福利指单位或国家给成员的待遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "福利", "is_correct": true, "explanation": "正确。“福利”是单位给成员的待遇，可以被享受。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不是待遇，“享受着公司的味道”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是公司给成员的待遇，“享受着公司的颜色”说不通。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“享受”后接待遇、福利等，不接“数量”。"}], "explanations": {"福利": "正确。“福利”是单位给成员的待遇，可以被享受。", "味道": "语义：味道不是待遇，“享受着公司的味道”说不通。", "颜色": "语义：颜色不是公司给成员的待遇，“享受着公司的颜色”说不通。", "数量": "搭配：“享受”后接待遇、福利等，不接“数量”。"}, "sentence_index": 6, "correct_answer": "福利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学生画得好，老师给他的福利是一本书。", "explanation": "这里应该用〈奖励〉。奖励是对表现好的人给予的，福利是单位或国家给全体成员的待遇。"}, {"text": "这笔存款的福利每年是三厘。", "explanation": "这里应该用〈利息〉。存款的收益叫利息，福利指单位或国家给成员的待遇。"}, {"text": "政府想改善农民的一台福利。", "explanation": "这里应该用〈项〉。福利的量词是“项”或“份”，“台”用于机器等，不能用于福利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新公司为员工提供了一把医疗福利。", "corrected_sentence": "新公司为员工提供了一项医疗福利。", "error_description": "量词错误：“福利”应用“项”，不能用“把”（“把”用于有柄的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家得福利很完善，老人生活有保障。", "corrected_sentence": "这个国家的福利很完善，老人生活有保障。", "error_description": "助词错误：“国家”与“福利”之间应用“的”，不能用“得”，应说“这个国家的福利很完善”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
