INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89755, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在最上面管事的那些人。", "primary_collocate": null, "pronunciation": "gāo céng", "ipa": "kɑʊ˥ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "公司高层今天开会。", "target_word": "高层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事要问高层。", "target_word": "高层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "高层已经决定明年开新店。", "target_word": "高层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是公司的高层，工作很忙。", "target_word": "高层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高层的意见和员工不太一样。", "target_word": "高层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司高层换了几个人，员工都很担心。", "target_word": "高层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新规定是由高层来定的。", "target_word": "高层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高层要听一听普通员工的想法。", "target_word": "高层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理把员工的问题告诉了高层。", "target_word": "高层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司工作了十年，才进入高层。", "target_word": "高层", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高层领导", "label": "复合"}, {"form": "高层管理", "label": "复合"}, {"form": "高層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "组织里最上面管事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e9126ca-4af1-43ae-8d7f-a545c9374384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89755, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老师", "is_correct": false, "explanation": "搭配：“公司老师”不是常用说法，句中指的是公司里管事的人，应说“高层”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不能开会。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，不能开会。"}, {"text": "高层", "is_correct": true, "explanation": "“高层”指公司最上面管事的人，是能够开会的人，与句意相符。"}], "explanations": {"老师": "搭配：“公司老师”不是常用说法，句中指的是公司里管事的人，应说“高层”。", "厨房": "语义：厨房是做饭的地方，不能开会。", "鸡蛋": "语义：鸡蛋是食物，不能开会。", "高层": "“高层”指公司最上面管事的人，是能够开会的人，与句意相符。"}, "sentence_index": 0, "correct_answer": "高层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的高层每周组织大家打扫教室。", "explanation": "这里应该用〈班干部〉。“高层”指公司、机关里管事的上层人员，班级里不这样说。"}, {"text": "飞机在高层飞行。", "explanation": "这里应该用〈高空〉。此处的“高层”只指管事的上层人员，不指飞行的高度。"}, {"text": "这条路的交通高层在早上七点。", "explanation": "这里应该用〈高峰〉。“高层”不能指一段时间，交通最忙的时段要说高峰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能制定规定，句中“由……来定”需要有决定权的人或机构。"}, {"text": "黄瓜", "is_correct": false, "explanation": "语义：黄瓜是蔬菜，不能制定规定。"}, {"text": "小孩", "is_correct": false, "explanation": "搭配：“由……来定”的主体要有决定权，一般不说“小孩”制定规定。"}, {"text": "高层", "is_correct": true, "explanation": "“高层”指有决定权的上层管理者，与“定规定”相符。"}], "explanations": {"天气": "语义：天气不能制定规定，句中“由……来定”需要有决定权的人或机构。", "黄瓜": "语义：黄瓜是蔬菜，不能制定规定。", "小孩": "搭配：“由……来定”的主体要有决定权，一般不说“小孩”制定规定。", "高层": "“高层”指有决定权的上层管理者，与“定规定”相符。"}, "sentence_index": 6, "correct_answer": "高层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座塔的高层是一百米。", "explanation": "这里应该用〈高度〉。“高层”指管事的上层人员，说高矮要用高度。"}, {"text": "这次比赛的一件高层很认真。", "explanation": "这里应该用〈位〉。“高层”指人，量词用“位”；“件”用于衣物、事情等，不能用来数人。"}, {"text": "我们公司的一只高层很严格。", "explanation": "这里应该用〈位〉。“高层”指人，量词用“位”或“名”，“只”用于动物，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她工作了五年，终于进入了的高层。", "corrected_sentence": "她工作了五年，终于进入了高层。", "error_description": "错误：“进入了”后面多加了“的”。正确：“进入了高层”，“高层”直接作“进入”的宾语，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89755, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块高层很关心员工的生活。", "corrected_sentence": "这位高层很关心员工的生活。", "error_description": "错误：量词用了“块”。正确：“这位高层”，“高层”指人，量词应用“位”，“块”用于成块的东西，不能修饰人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89761, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
