INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89761, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国手是全国最厉害的棋手或运动员。", "primary_collocate": null, "pronunciation": "guó shǒu", "ipa": "kuo˧˥ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "这位围棋国手昨天赢了一场重要的比赛。", "target_word": "国手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟的梦想是当羽毛球国手。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国手的水平比我们高得多。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他才二十岁，就成了全国有名的国手。", "target_word": "国手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在介绍那位象棋国手。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国手每天要练八个小时的球。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，国手也是一步一步练出来的。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他和一位国手下了一盘棋，结果输了。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位国手把冠军的奖杯送给了学校。", "target_word": "国手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说他年轻时也想当国手。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位国手", "label": "量词"}, {"form": "國手", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国手：全国最厉害的棋手或运动员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede64bf9-61fe-41ae-8fa2-9847150bb0ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89761, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国手", "is_correct": true, "explanation": "正确。国手指全国最厉害的棋手或运动员，与“围棋”搭配后表示全国水平，符合“赢了一场重要的比赛”。"}, {"text": "画家", "is_correct": false, "explanation": "语义：“画家”是画画的人，与“围棋比赛”无关。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“围棋厨师”不成立，“厨师”与“围棋”不搭配。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：裁判负责判罚，不参加比赛，不能说“赢了一场比赛”。"}], "explanations": {"国手": "正确。国手指全国最厉害的棋手或运动员，与“围棋”搭配后表示全国水平，符合“赢了一场重要的比赛”。", "画家": "语义：“画家”是画画的人，与“围棋比赛”无关。", "厨师": "搭配：“围棋厨师”不成立，“厨师”与“围棋”不搭配。", "裁判": "语义：裁判负责判罚，不参加比赛，不能说“赢了一场比赛”。"}, "sentence_index": 0, "correct_answer": "国手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把国手很锋利，切起菜来很快。", "explanation": "这里应该用〈菜刀〉。国手指人，不能用来指刀具，应说“菜刀”。"}, {"text": "这个国手很重，抬不动。", "explanation": "这里应该用〈雕像〉。国手指人，不能用来指石像之类的物件，应说“雕像”。"}, {"text": "他是个国手，刚学会下棋，还不懂规则。", "explanation": "这里应该用〈新手〉。国手指全国水平最高的人，“刚学会下棋”的人应说“新手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89761, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国手", "is_correct": true, "explanation": "正确。国手要靠长期练习才能达到全国水平，“练出来”说得通。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：“大楼”是建筑，不是人，不能“练”出来。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是物体，不是人，不能说“练出来”。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：“练”用于人的技能，不用于树木，“练出来”不搭配。"}], "explanations": {"国手": "正确。国手要靠长期练习才能达到全国水平，“练出来”说得通。", "大楼": "语义：“大楼”是建筑，不是人，不能“练”出来。", "石头": "语义：“石头”是物体，不是人，不能说“练出来”。", "树木": "搭配：“练”用于人的技能，不用于树木，“练出来”不搭配。"}, "sentence_index": 6, "correct_answer": "国手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是电视台的国手，每天采访运动员。", "explanation": "这里应该用〈记者〉。国手指全国水平最高的运动员，每天采访运动员的人应说“记者”。"}, {"text": "他才三岁，已经是国手了。", "explanation": "这里应该用〈神童〉。国手指全国水平最高的人，三岁的孩子只能说“神童”。"}, {"text": "他是个国手，每次比赛都第一个投降。", "explanation": "这里应该用〈懦夫〉。国手指全国水平最高的人，“每次比赛都第一个投降”说的是品性怯懦，应说“懦夫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只国手昨天还在棋馆里下棋。", "corrected_sentence": "那位国手昨天还在棋馆里下棋。", "error_description": "错误：量词“只”。“国手”指人，应用量词“位”，说“那位国手”；“只”不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张国手昨天输给了一位新手。", "corrected_sentence": "那位国手昨天输给了一位新手。", "error_description": "错误：量词“张”。“国手”指人，应用量词“位”，说“那位国手”；“张”用于平面的东西，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
