INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在物质或精神上得到满足和快乐。", "primary_collocate": null, "pronunciation": "xiǎng shòu", "ipa": "ɕjɑŋ˨˩˦ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "周末我喜欢在家享受安静的时光。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭上眼睛，享受着海风的凉爽。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们正在享受假期的快乐。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作了一年，她想好好享受生活。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着音乐，他享受这难得的轻松。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们享受着公园里的好天气。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她享受过很多地方的美丽风景。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在草地上，享受阳光和微风。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会享受，每天都给自己做好吃的。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他更享受比赛的过程，而不是结果。", "target_word": "享受", "complexity_tier": "T3", "furigana": "tā gèng xiǎngshòu bǐsài de guòchéng, ér bú shì jiéguǒ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "享受着", "label": "体标"}, {"form": "享受了", "label": "体标"}, {"form": "享受过", "label": "体标"}], "register": "中性", "sense_fingerprint": "享受|动词|在物质或精神上得到满足和快乐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cbaa39-5606-4121-8f90-fd77df64622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打扰", "is_correct": false, "explanation": "搭配：“打扰”的对象是人或某种活动，不能说“打扰安静的时光”。"}, {"text": "享受", "is_correct": true, "explanation": "正确：“享受”表示得到满足和快乐，与“安静的时光”搭配自然。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”是厌恶，与“喜欢”的积极情感相反，“喜欢在家讨厌安静的时光”语义不通。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”是毁坏，与“安静”和“喜欢”的语境相冲突。"}], "explanations": {"打扰": "搭配：“打扰”的对象是人或某种活动，不能说“打扰安静的时光”。", "享受": "正确：“享受”表示得到满足和快乐，与“安静的时光”搭配自然。", "讨厌": "语义：“讨厌”是厌恶，与“喜欢”的积极情感相反，“喜欢在家讨厌安静的时光”语义不通。", "破坏": "语义：“破坏”是毁坏，与“安静”和“喜欢”的语境相冲突。"}, "sentence_index": 0, "correct_answer": "享受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他第一次走进雪山，享受到一种说不出的震撼。", "explanation": "这里应该用〈感受〉。享受指得到满足和快乐，“震撼”是心里的感触，要说“感受到”。"}, {"text": "他虚心享受了大家的建议。", "explanation": "这里应该用〈接受〉。享受指得到满足和快乐，“建议”不是可以享受的东西，要用“接受”。"}, {"text": "他一直享受着朋友的责备，一句话也不说。", "explanation": "这里应该用〈忍受〉。享受指得到满足和快乐，“责备”不是可以享受的东西，要用“忍受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "污染", "is_correct": false, "explanation": "搭配：“污染”多用于水、空气、环境，不说“污染风景”。"}, {"text": "享受", "is_correct": true, "explanation": "正确：“享受过”表示曾经得到过美丽风景带来的快乐，与“美丽风景”搭配。"}, {"text": "玷污", "is_correct": false, "explanation": "语义：“玷污”是弄脏、败坏，与“美丽风景”的褒义相冲突。"}, {"text": "毁坏", "is_correct": false, "explanation": "语义：“毁坏”是损坏，与“美丽风景”的语境相冲突。"}], "explanations": {"污染": "搭配：“污染”多用于水、空气、环境，不说“污染风景”。", "享受": "正确：“享受过”表示曾经得到过美丽风景带来的快乐，与“美丽风景”搭配。", "玷污": "语义：“玷污”是弄脏、败坏，与“美丽风景”的褒义相冲突。", "毁坏": "语义：“毁坏”是损坏，与“美丽风景”的语境相冲突。"}, "sentence_index": 6, "correct_answer": "享受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市刚刚享受了严重的洪水。", "explanation": "这里应该用〈遭受〉。享受表示得到快乐，洪水是灾害，不能说享受。"}, {"text": "这几天楼上很吵，我一直享受着这些噪音。", "explanation": "这里应该用〈忍受〉。享受表示得到快乐，噪音让人难受，不能说享受。"}, {"text": "他在考试中享受了失败，很难过。", "explanation": "这里应该用〈遭遇〉。享受表示得到快乐，失败不是可以享受的事，要用“遭遇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她坐在窗边，享受了着微风的凉爽。", "corrected_sentence": "她坐在窗边，享受着微风的凉爽。", "error_description": "“享受”后面的动态助词“着”表示动作正在进行，不能再加“了”。应说“享受着”，不说“享受了着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶在院子里享受的很开心。", "corrected_sentence": "奶奶在院子里享受得很开心。", "error_description": "错误：补语标志应用“得”，不能用“的”。“的”连接定语，不能引出补语。应改为“奶奶在院子里享受得很开心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
