INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89781, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不聪明，做事让人觉得好笑。", "primary_collocate": null, "pronunciation": "shǎ", "ipa": "ʂa˨˩˦", "syllable_count": 1, "sentences": [{"text": "他穿着拖鞋去爬山，样子真傻。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做了一件很傻的事，大家都笑我。", "target_word": "傻", "complexity_tier": "T3", "furigana": "wǒ zuò le yí jiàn hěn shǎ de shì, dà jiā dōu xiào wǒ", "sentence_source": "generated"}, {"text": "别问这么傻的问题，大家会笑你的。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那张照片拍得很傻，我看了笑个不停。", "target_word": "傻", "complexity_tier": "T3", "furigana": "nà zhāng zhào piàn pāi de hěn shǎ, wǒ kàn le xiào gè bù tíng", "sentence_source": "generated"}, {"text": "他给小狗穿西装，样子又傻又可爱。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我当时说了一句很傻的话，现在想起来还脸红。", "target_word": "傻", "complexity_tier": "T3", "furigana": "wǒ dāng shí shuō le yí jù hěn shǎ de huà, xiàn zài xiǎng qǐ lái hái liǎn hóng", "sentence_source": "generated"}, {"text": "弟弟把鞋穿反了还不知道，样子很傻。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把帽子戴反了，看起来很傻。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我笑自己傻，竟然把手机放进了冰箱。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的动作很傻，孩子们看了都哈哈大笑。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傻傻", "label": "重叠"}, {"form": "傻话", "label": "复合"}, {"form": "傻事", "label": "复合"}], "register": "口语", "sense_fingerprint": "言行滑稽可笑、让人觉得傻气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7424e-dd54-40b2-af10-b5c6420f3f6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89781, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确答案。傻指言行滑稽、让人觉得好笑。"}, {"text": "沙", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是沙子。"}, {"text": "啥", "is_correct": false, "explanation": "shǎ（第三声）与 shá（第二声）声调不同，意思是什么。"}, {"text": "少", "is_correct": false, "explanation": "shǎ 与 shǎo 韵母不同，shǎo 意思是少。"}, {"text": "洒", "is_correct": false, "explanation": "shuǎ 比 shǎ 多介音 u，shuǎ 意思是玩耍。"}, {"text": "厦", "is_correct": false, "explanation": "shà（第四声）与 shǎ（第三声）声调不同，意思是大厦。"}], "explanations": {"傻": "正确答案。傻指言行滑稽、让人觉得好笑。", "沙": "shǎ（第三声）与 shā（第一声）声调不同，意思是沙子。", "啥": "shǎ（第三声）与 shá（第二声）声调不同，意思是什么。", "少": "shǎ 与 shǎo 韵母不同，shǎo 意思是少。", "洒": "shuǎ 比 shǎ 多介音 u，shuǎ 意思是玩耍。", "厦": "shà（第四声）与 shǎ（第三声）声调不同，意思是大厦。"}, "sentence_index": null, "correct_answer": "傻"}, "level_3": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确。傻表示言行滑稽可笑，穿拖鞋爬山正合此意。"}, {"text": "得体", "is_correct": false, "explanation": "语义：穿拖鞋爬山谈不上得体，与句中的滑稽形象矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”多形容心情或负担，与穿拖鞋爬山的滑稽样子不搭。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：穿拖鞋爬山的样子很难显得严肃，与句意的滑稽相矛盾。"}], "explanations": {"傻": "正确。傻表示言行滑稽可笑，穿拖鞋爬山正合此意。", "得体": "语义：穿拖鞋爬山谈不上得体，与句中的滑稽形象矛盾。", "沉重": "搭配：“沉重”多形容心情或负担，与穿拖鞋爬山的滑稽样子不搭。", "严肃": "语义：穿拖鞋爬山的样子很难显得严肃，与句意的滑稽相矛盾。"}, "sentence_index": 0, "correct_answer": "傻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很傻，怎么也敲不碎。", "explanation": "这里应该用〈坚硬〉。坚硬指质地硬，傻指头脑不灵或做事可笑，不能用来形容石头。"}, {"text": "这间屋子很傻，墙角都长了霉。", "explanation": "这里应该用〈潮湿〉。潮湿指含水分多，傻不能用来形容屋子的湿度。"}, {"text": "这块布的颜色很傻，看着很刺眼。", "explanation": "这里应该用〈鲜艳〉。鲜艳形容颜色明亮，傻不能用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89781, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确答案。傻指言行滑稽、让人觉得好笑。"}, {"text": "纱", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是纱布。"}, {"text": "煞", "is_correct": false, "explanation": "shà（第四声）与 shǎ（第三声）声调不同，shà 意思是止住、勒住，如“煞住”。"}, {"text": "闪", "is_correct": false, "explanation": "shǎn 比 shǎ 多了韵尾 n，意思是闪电。"}, {"text": "耍", "is_correct": false, "explanation": "shuǎ 比 shǎ 多介音 u，shuǎ 意思是玩耍。"}, {"text": "赏", "is_correct": false, "explanation": "shǎng 比 shǎ 多了韵尾 ng，意思是欣赏。"}], "explanations": {"傻": "正确答案。傻指言行滑稽、让人觉得好笑。", "纱": "shǎ（第三声）与 shā（第一声）声调不同，意思是纱布。", "煞": "shà（第四声）与 shǎ（第三声）声调不同，shà 意思是止住、勒住，如“煞住”。", "闪": "shǎn 比 shǎ 多了韵尾 n，意思是闪电。", "耍": "shuǎ 比 shǎ 多介音 u，shuǎ 意思是玩耍。", "赏": "shǎng 比 shǎ 多了韵尾 ng，意思是欣赏。"}, "sentence_index": null, "correct_answer": "傻"}, "level_3": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确。傻表示头脑不灵、显得可笑，把鞋穿反了还不知道正合此意。"}, {"text": "威风", "is_correct": false, "explanation": "语义：把鞋穿反了还不知道，样子谈不上威风，句意是可笑的。"}, {"text": "威严", "is_correct": false, "explanation": "语义：威严的样子与把鞋穿反、还不知道的糊涂形象矛盾。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”说物体的厚薄，不用来形容人的样子。"}], "explanations": {"傻": "正确。傻表示头脑不灵、显得可笑，把鞋穿反了还不知道正合此意。", "威风": "语义：把鞋穿反了还不知道，样子谈不上威风，句意是可笑的。", "威严": "语义：威严的样子与把鞋穿反、还不知道的糊涂形象矛盾。", "厚": "搭配：“厚”说物体的厚薄，不用来形容人的样子。"}, "sentence_index": 6, "correct_answer": "傻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木板的表面很傻，摸上去很光滑。", "explanation": "这里应该用〈光滑〉。光滑形容表面平整，傻不能用来形容木板的表面。"}, {"text": "今年的天气很傻，一连几个月都没下雨。", "explanation": "这里应该用〈干燥〉。干燥指缺少水分，傻不能用来形容天气。"}, {"text": "今年的雨水很傻，河水涨了好几次。", "explanation": "这里应该用〈充足〉。充足指数量多、够用，傻不能用来形容雨水的多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他唱歌的样子傻很，大家都笑了。", "corrected_sentence": "他唱歌的样子很傻，大家都笑了。", "error_description": "错误：“傻很”，程度副词“很”应放在“傻”前面。正确：“很傻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做了一件很傻事，后来一直后悔。", "corrected_sentence": "他做了一件很傻的事，后来一直后悔。", "error_description": "错误：“很傻事”漏了定语后的“的”。正确：“很傻的事”，形容词修饰名词时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聪明", "is_correct": true, "explanation": "正确。“聪明”与“傻”在“头脑不灵活”的意思上构成反义。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”描写心情，与“傻”（头脑不灵）没有反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”描写做事态度，与“傻”的头脑义没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”构成反义，与“傻”没有反义关系。"}], "correct_answer": "聪明", "explanations": {"聪明": "正确。“聪明”与“傻”在“头脑不灵活”的意思上构成反义。", "高兴": "“高兴”描写心情，与“傻”（头脑不灵）没有反义关系。", "认真": "“认真”描写做事态度，与“傻”的头脑义没有反义关系。", "安静": "“安静”与“吵闹”构成反义，与“傻”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
