INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "头脑不灵活；糊涂。", "primary_collocate": null, "pronunciation": "shǎ", "ipa": "ʂa˨˩˦", "syllable_count": 1, "sentences": [{"text": "这孩子太傻，别人说什么他都信。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是傻，只是反应有点慢。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你真傻，他明明在骗你，你还信。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我傻得连这么简单的题都不会。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来傻，其实心里很明白。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太傻了，被骗了五次还不知道。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有点傻，听不懂别人的玩笑。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是不傻，就不会把钱借给陌生人。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前很聪明，现在老了，脑子有点傻了。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么这么傻，连钱都数不清？", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傻傻", "label": "重叠"}, {"form": "傻瓜", "label": "复合"}, {"form": "傻子", "label": "复合"}], "register": "口语", "sense_fingerprint": "头脑不灵、不明事理，容易被骗或反应迟钝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7424e-dd54-40b2-af10-b5c6420f3f6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确答案。傻指头脑不灵活、糊涂。"}, {"text": "沙", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是沙子。"}, {"text": "啥", "is_correct": false, "explanation": "shǎ（第三声）与 shá（第二声）声调不同，意思是什么。"}, {"text": "少", "is_correct": false, "explanation": "shǎ 与 shǎo 韵母不同，shǎo 意思是少。"}, {"text": "耍", "is_correct": false, "explanation": "shuǎ 比 shǎ 多介音 u，shuǎ 意思是玩耍。"}, {"text": "洒", "is_correct": false, "explanation": "sǎ 与 shǎ 声母不同（s 与 sh），sǎ 意思是洒（水）。"}], "explanations": {"傻": "正确答案。傻指头脑不灵活、糊涂。", "沙": "shǎ（第三声）与 shā（第一声）声调不同，意思是沙子。", "啥": "shǎ（第三声）与 shá（第二声）声调不同，意思是什么。", "少": "shǎ 与 shǎo 韵母不同，shǎo 意思是少。", "耍": "shuǎ 比 shǎ 多介音 u，shuǎ 意思是玩耍。", "洒": "sǎ 与 shǎ 声母不同（s 与 sh），sǎ 意思是洒（水）。"}, "sentence_index": null, "correct_answer": "傻"}, "level_3": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确。傻表示头脑不灵活，句中“别人说什么他都信”正说明这一点。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”与后句“别人说什么他都信”相矛盾，聪明的孩子不会什么都信。"}, {"text": "精明", "is_correct": false, "explanation": "语义：“精明”与“什么都信”相矛盾，精明的人不会轻易相信别人。"}, {"text": "沧桑", "is_correct": false, "explanation": "搭配：“沧桑”形容阅历，多用于人，不用来形容孩子，“太沧桑”说不通。"}], "explanations": {"傻": "正确。傻表示头脑不灵活，句中“别人说什么他都信”正说明这一点。", "聪明": "语义：“聪明”与后句“别人说什么他都信”相矛盾，聪明的孩子不会什么都信。", "精明": "语义：“精明”与“什么都信”相矛盾，精明的人不会轻易相信别人。", "沧桑": "搭配：“沧桑”形容阅历，多用于人，不用来形容孩子，“太沧桑”说不通。"}, "sentence_index": 0, "correct_answer": "傻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤的味道很傻，大家都抢着喝。", "explanation": "这里应该用〈鲜美〉。鲜美形容味道好，傻不能用来形容汤的味道。"}, {"text": "这幅画的构图太傻，缺少变化。", "explanation": "这里应该用〈呆板〉。呆板形容死板、缺少变化，傻指头脑不灵，不能用来评价构图。"}, {"text": "这份数据的统计很傻，每个数字都对不上。", "explanation": "这里应该用〈精确〉。精确指准确无误，傻指头脑不灵，不能用来形容统计的准确程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确答案。傻指头脑不灵活、糊涂。"}, {"text": "纱", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是纱布。"}, {"text": "煞", "is_correct": false, "explanation": "shà（第四声）与 shǎ（第三声）声调不同，shà 意思是止住、勒住，如“煞住”。"}, {"text": "闪", "is_correct": false, "explanation": "shǎn 比 shǎ 多了韵尾 n，意思是闪电。"}, {"text": "赏", "is_correct": false, "explanation": "shǎng 比 shǎ 多了韵尾 ng，意思是欣赏。"}], "explanations": {"傻": "正确答案。傻指头脑不灵活、糊涂。", "纱": "shǎ（第三声）与 shā（第一声）声调不同，意思是纱布。", "煞": "shà（第四声）与 shǎ（第三声）声调不同，shà 意思是止住、勒住，如“煞住”。", "闪": "shǎn 比 shǎ 多了韵尾 n，意思是闪电。", "赏": "shǎng 比 shǎ 多了韵尾 ng，意思是欣赏。"}, "sentence_index": null, "correct_answer": "傻"}, "level_3": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确。傻表示头脑不灵，听不懂玩笑正是这种表现。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”的人通常听得懂玩笑，与“听不懂别人的玩笑”相矛盾。"}, {"text": "机灵", "is_correct": false, "explanation": "语义：“机灵”的人反应快，不会听不懂玩笑，与句意矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”形容光线，人不说“有点亮”，句中不能这样用。"}], "explanations": {"傻": "正确。傻表示头脑不灵，听不懂玩笑正是这种表现。", "幽默": "语义：“幽默”的人通常听得懂玩笑，与“听不懂别人的玩笑”相矛盾。", "机灵": "语义：“机灵”的人反应快，不会听不懂玩笑，与句意矛盾。", "亮": "搭配：“亮”形容光线，人不说“有点亮”，句中不能这样用。"}, "sentence_index": 6, "correct_answer": "傻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路的坡度很傻，车子开上去总是熄火。", "explanation": "这里应该用〈陡〉。陡形容坡度大，傻不能用来形容坡度。"}, {"text": "他的观察力很傻，一眼就看出了破绽。", "explanation": "这里应该用〈敏锐〉。敏锐形容观察、感觉灵敏，傻指头脑不灵，不能用来形容观察力。"}, {"text": "这份报告的格式很傻，看着让人头疼。", "explanation": "这里应该用〈规范〉。规范指符合标准，傻指头脑不灵，不能用来形容报告的格式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他傻太了，连这个都看不出来。", "corrected_sentence": "他太傻了，连这个都看不出来。", "error_description": "错误：“傻太了”语序颠倒。正确：“太傻了”，程度副词“太”要放在形容词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他得傻连门都找不到。", "corrected_sentence": "他傻得连门都找不到。", "error_description": "错误：“得”位置颠倒，补语标记应放在形容词“傻”之后。正确：“傻得连门都找不到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
