INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89785, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在政府里为大家做事的人。", "primary_collocate": null, "pronunciation": "gōng wù yuán", "ipa": "kʊŋ˥ u˥˩ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "我爸爸是公务员。", "target_word": "公务员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她想当一名公务员。", "target_word": "公务员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公务员在政府里工作。", "target_word": "公务员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我哥哥去年成了公务员。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公务员每天早上八点上班。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人想考公务员，因为工作稳定。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公务员要为大家服务，不能只想自己。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以前是老师，现在是公务员。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位公务员帮我们解决了问题。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在市政府当公务员，已经五年了。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名公务员", "label": "量词"}, {"form": "一位公务员", "label": "量词"}, {"form": "公务员们", "label": "复数"}, {"form": "公務員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在政府工作为大家服务的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e9126ca-4af1-43ae-8d7f-a545c9374384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89785, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能用来说明人的职业身份。"}, {"text": "公务员", "is_correct": true, "explanation": "正确。「我爸爸是公务员」说明他的职业。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是自然景物，不能指人。"}, {"text": "家父", "is_correct": false, "explanation": "语域：「家父」是对外的谦称，不用于「我爸爸是……」这种直陈的说明句。"}], "explanations": {"桌子": "语义：桌子是家具，不能用来说明人的职业身份。", "公务员": "正确。「我爸爸是公务员」说明他的职业。", "大海": "语义：大海是自然景物，不能指人。", "家父": "语域：「家父」是对外的谦称，不用于「我爸爸是……」这种直陈的说明句。"}, "sentence_index": 0, "correct_answer": "公务员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在银行当公务员，已经五年了。", "explanation": "这里应该用〈职员〉。公务员指在政府机关依法办事的人，银行里的工作人员称职员。"}, {"text": "他在工厂当公务员，每天都要加班。", "explanation": "这里应该用〈工人〉。公务员在政府机关工作，工厂里的生产人员称工人。"}, {"text": "我在街上看见一只公务员。", "explanation": "这里量词用错。「只」用于动物，指人应用「位」或「名」，应说「一位公务员」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不是能主动为大家服务的主体。"}, {"text": "公务员", "is_correct": true, "explanation": "正确。公务员的职责就是为大家服务，与句子的语境相合。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷的行为与「为大家服务、不能只想自己」正好相反。"}, {"text": "臣子", "is_correct": false, "explanation": "语域：「臣子」是古代用语，与现代的表述不协调。"}], "explanations": {"石头": "语义：石头不是能主动为大家服务的主体。", "公务员": "正确。公务员的职责就是为大家服务，与句子的语境相合。", "小偷": "语义：小偷的行为与「为大家服务、不能只想自己」正好相反。", "臣子": "语域：「臣子」是古代用语，与现代的表述不协调。"}, "sentence_index": 6, "correct_answer": "公务员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大学毕业后进了一家大公司，现在是公务员，负责招聘工作。", "explanation": "这里应该用〈管理人员〉。公务员属于国家行政机关，企业里的管理人员不称公务员。"}, {"text": "她在市医院当公务员，已经五年了。", "explanation": "这里应该用〈医生〉。公务员在政府机关工作，医院里看病的人员称医生。"}, {"text": "她在一家饭店当公务员，已经五年了。", "explanation": "这里应该用〈服务员〉。饭店里做接待工作的人称服务员，公务员指政府机关的人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表弟打算当一只公务员。", "corrected_sentence": "我表弟打算当一名公务员。", "error_description": "量词错误：指人的公务员应用「名」或「位」，不用「只」（「只」用于动物）。正确形式是「一名公务员」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈是一位退休地公务员。", "corrected_sentence": "我妈妈是一位退休的公务员。", "error_description": "错误：修饰名词“公务员”的成分应用“的”，这里误用了“地”。“地”用于修饰动词、形容词。正确：“退休的公务员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
