INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89786, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家行政机关中依法执行公务的工作人员。", "primary_collocate": null, "pronunciation": "gōng wù yuán", "ipa": "kʊŋ˥ u˥˩ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "国家公务员要依法办事。", "target_word": "公务员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公务员必须遵守国家的法律。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公务员不能收别人的礼物。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他通过考试，成为一名国家公务员。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公务员在工作中要保持公平。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律规定，公务员要依法执行公务。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位公务员因为违反规定受到了处分。", "target_word": "公务员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公务员的工资由国家统一发放。", "target_word": "公务员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的公务员要先学习相关的法律知识。", "target_word": "公务员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些公务员去农村工作过两年。", "target_word": "公务员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名公务员", "label": "量词"}, {"form": "公务员考试", "label": "复合"}, {"form": "公務員", "label": "繁体"}], "register": "正式", "sense_fingerprint": "国家行政机关中依法执行公务的人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e9126ca-4af1-43ae-8d7f-a545c9374384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能依法办事，句子的主语必须是能履行法律义务的人。"}, {"text": "公务员", "is_correct": true, "explanation": "正确。「国家公务员」指依法执行公务的国家行政人员。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是行政主体，不能依法办事。"}, {"text": "臣子", "is_correct": false, "explanation": "语域：「臣子」是古代用语，不适用于现代国家的行政人员。"}], "explanations": {"桌子": "语义：桌子不能依法办事，句子的主语必须是能履行法律义务的人。", "公务员": "正确。「国家公务员」指依法执行公务的国家行政人员。", "大海": "语义：大海不是行政主体，不能依法办事。", "臣子": "语域：「臣子」是古代用语，不适用于现代国家的行政人员。"}, "sentence_index": 0, "correct_answer": "公务员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在一家私营公司当国家公务员。", "explanation": "这里应该用〈职员〉。国家公务员指国家行政机关的人员，私营公司的员工称职员。"}, {"text": "他在工厂当国家公务员，每天生产零件。", "explanation": "这里应该用〈工人〉。国家公务员在行政机关工作，工厂里的生产人员称工人。"}, {"text": "我昨天在街上遇到一只国家公务员。", "explanation": "这里量词用错。「只」用于动物，指人应用「位」或「名」，应说「一位国家公务员」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会违反规定，也不会受到处分。"}, {"text": "公务员", "is_correct": true, "explanation": "正确。「这位公务员」指违反规定、受到处分的公务人员。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不是行政处分的对象，句子说不通。"}, {"text": "奴仆", "is_correct": false, "explanation": "语域：「奴仆」是旧时用语，不适用于现代的行政处分语境。"}], "explanations": {"石头": "语义：石头不会违反规定，也不会受到处分。", "公务员": "正确。「这位公务员」指违反规定、受到处分的公务人员。", "猫": "语义：猫不是行政处分的对象，句子说不通。", "奴仆": "语域：「奴仆」是旧时用语，不适用于现代的行政处分语境。"}, "sentence_index": 6, "correct_answer": "公务员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在医院当国家公务员，每天看病。", "explanation": "这里应该用〈医生〉。国家公务员在行政机关工作，看病的人员称医生。"}, {"text": "他在饭店当国家公务员，每天做菜。", "explanation": "这里应该用〈厨师〉。做菜的人称厨师，国家公务员指行政机关的人员。"}, {"text": "他在工厂当国家公务员，负责管理生产。", "explanation": "这里应该用〈厂长〉。管理工厂生产的负责人称厂长，国家公务员在行政机关工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大学毕业后报考了一只国家公务员。", "corrected_sentence": "他大学毕业后报考了国家公务员。", "error_description": "量词错误：「国家公务员」指人，前面不应加「只」（「只」用于动物）；直接说「报考了国家公务员」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只国家公务员昨天开会迟到了。", "corrected_sentence": "这位国家公务员昨天开会迟到了。", "error_description": "量词错误：指人的「国家公务员」应用「位」，不用「只」（「只」用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
