INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情之前和之后；也指前面和后面。", "primary_collocate": null, "pronunciation": "qián hòu", "ipa": "tɕʰjɛn˧˥ xou˥˩", "syllable_count": 2, "sentences": [{"text": "春节前后，火车票很难买。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动前后都要喝水。", "target_word": "前后", "complexity_tier": "T3", "furigana": "qián hòu", "sentence_source": "generated"}, {"text": "国庆前后，这里有很多游客。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子前后都有小花园。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校前后各有一个大门。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前后，他都很紧张。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日前后，朋友给我寄了礼物。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家前后都有树。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业前后，大家常常一起吃饭。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车前后都坐满了人。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某个时间点或事情的前后，或位置的前面和后面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf08968a-b4cb-4d8f-9f5e-355294b2811a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正面", "is_correct": false, "explanation": "语义：“正面”指事物的前面一侧，是方位词，不能表示“春节”前后的时间段。"}, {"text": "前后", "is_correct": true, "explanation": "前后：某个时间点的前后一段时间，与节日“春节”搭配，符合句意。"}, {"text": "南北", "is_correct": false, "explanation": "语义：“南北”指方位，不能与“春节”组成表示时间范围的说法。"}, {"text": "远近", "is_correct": false, "explanation": "搭配：“远近”指距离，不能说“春节远近”，与时间无关。"}], "explanations": {"正面": "语义：“正面”指事物的前面一侧，是方位词，不能表示“春节”前后的时间段。", "前后": "前后：某个时间点的前后一段时间，与节日“春节”搭配，符合句意。", "南北": "语义：“南北”指方位，不能与“春节”组成表示时间范围的说法。", "远近": "搭配：“远近”指距离，不能说“春节远近”，与时间无关。"}, "sentence_index": 0, "correct_answer": "前后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他前后学了三年中文。", "explanation": "这里的“前后”表示一件事从头到尾的时长，属于另一个义项，不表示“事情之前和之后”。"}, {"text": "这件事前后拖了半年。", "explanation": "这里的“前后”表示一件事从头到尾的时长，属于另一个义项，不表示“事情之前和之后”或位置的前后。"}, {"text": "这本书他前后写了三年。", "explanation": "这里的“前后”同样表示一件事从头到尾的时长，属于另一个义项，与本词条的时间点和方位义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "东西", "is_correct": false, "explanation": "语义：“东西”指物品，不表示时间段，“生日东西”说不通。"}, {"text": "前后", "is_correct": true, "explanation": "前后：生日前后的一段时间，与“生日”搭配，符合句意。"}, {"text": "高低", "is_correct": false, "explanation": "搭配：“高低”指高矮或起伏，不用于时间，不能说“生日高低”。"}, {"text": "黑白", "is_correct": false, "explanation": "语义：“黑白”指颜色，与时间无关，句子不成立。"}], "explanations": {"东西": "语义：“东西”指物品，不表示时间段，“生日东西”说不通。", "前后": "前后：生日前后的一段时间，与“生日”搭配，符合句意。", "高低": "搭配：“高低”指高矮或起伏，不用于时间，不能说“生日高低”。", "黑白": "语义：“黑白”指颜色，与时间无关，句子不成立。"}, "sentence_index": 6, "correct_answer": "前后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我前后看了两场电影。", "explanation": "这里的“前后”表示一件事的总次数或总时长，属于另一个义项，与“事情之前和之后”不同。"}, {"text": "这个病前后治了一个月。", "explanation": "这里的“前后”表示一件事从头到尾的时长，属于另一个义项，不表示“事情之前和之后”或位置的前后。"}, {"text": "公司前后换了三个经理。", "explanation": "这里的“前后”表示一件事从头到尾的次数或时长，属于另一个义项，不表示“事情之前和之后”或位置的前后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放假了前后，车站都很挤。", "corrected_sentence": "放假前后，车站都很挤。", "error_description": "体标记错误：“了”插在“放假”与“前后”之间，拆散了时间短语；正确说法是“放假前后，车站都很挤。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校前后种了着很多树。", "corrected_sentence": "学校前后种着很多树。", "error_description": "体标记错误：“了”和“着”不能同时用在同一个动词后。应说“种着”，正确说法是“学校前后种着很多树”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
