INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89791, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "克是称东西轻重用的一个小单位。", "primary_collocate": null, "pronunciation": "kè", "ipa": "kʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "请给我二百克糖。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块蛋糕大概有三百克。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了五百克牛肉。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做面包要放十克盐。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个鸡蛋差不多有五十克重。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果只有一百五十克。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药店的秤很准,连一克也称得出来。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一百克茶叶。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这包糖一共四百克,够做两个蛋糕。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗刚出生时只有三百克。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "千克", "label": "复合"}, {"form": "毫克", "label": "复合"}], "register": "中性", "sense_fingerprint": "称食物、物品轻重时用的小重量单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3b0bebd-d58b-44d0-81e3-335cff6f276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89791, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "克", "is_correct": true, "explanation": "正确答案：克，称东西轻重用的小单位。"}, {"text": "渴", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，意思是口渴。"}, {"text": "颗", "is_correct": false, "explanation": "kē（第一声）与 kè（第四声）声调不同，意思是颗粒，量词。"}, {"text": "个", "is_correct": false, "explanation": "gè 与 kè 声母不同（g 与 k），意思是个，量词。"}, {"text": "咳", "is_correct": false, "explanation": "ké（第二声）与 kè（第四声）声调不同，意思是咳嗽。"}], "explanations": {"克": "正确答案：克，称东西轻重用的小单位。", "渴": "kě（第三声）与 kè（第四声）声调不同，意思是口渴。", "颗": "kē（第一声）与 kè（第四声）声调不同，意思是颗粒，量词。", "个": "gè 与 kè 声母不同（g 与 k），意思是个，量词。", "咳": "ké（第二声）与 kè（第四声）声调不同，意思是咳嗽。"}, "sentence_index": null, "correct_answer": "克"}, "level_3": {"options": [{"text": "克", "is_correct": true, "explanation": "正确。“克”是称糖用的重量单位，“二百克糖”自然。"}, {"text": "秒", "is_correct": false, "explanation": "语义：秒是时间单位，“二百秒糖”说不通。"}, {"text": "升", "is_correct": false, "explanation": "语义：升是容积单位，糖按重量计算，“二百升糖”不通。"}, {"text": "米", "is_correct": false, "explanation": "语义：米是长度单位，“二百米糖”不通。"}], "explanations": {"克": "正确。“克”是称糖用的重量单位，“二百克糖”自然。", "秒": "语义：秒是时间单位，“二百秒糖”说不通。", "升": "语义：升是容积单位，糖按重量计算，“二百升糖”不通。", "米": "语义：米是长度单位，“二百米糖”不通。"}, "sentence_index": 0, "correct_answer": "克"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班有三十克学生。", "explanation": "这里应该用〈名〉。克只用于称重，人数要用“名”或“个”计数。"}, {"text": "院子里种了五克树。", "explanation": "这里应该用〈棵〉。克只用于称重，树要用“棵”计量。"}, {"text": "农场里养了十克猪。", "explanation": "这里应该用〈头〉。克只用于称重，猪要用“头”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89791, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "克", "is_correct": true, "explanation": "正确答案：克，称东西轻重用的小单位。"}, {"text": "科", "is_correct": false, "explanation": "kē（第一声）与 kè（第四声）声调不同，意思是科目、科室。"}, {"text": "各", "is_correct": false, "explanation": "gè 与 kè 声母不同（g 与 k），意思是各自、每个。"}, {"text": "可", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，意思是可以。"}], "explanations": {"克": "正确答案：克，称东西轻重用的小单位。", "科": "kē（第一声）与 kè（第四声）声调不同，意思是科目、科室。", "各": "gè 与 kè 声母不同（g 与 k），意思是各自、每个。", "可": "kě（第三声）与 kè（第四声）声调不同，意思是可以。"}, "sentence_index": null, "correct_answer": "克"}, "level_3": {"options": [{"text": "克", "is_correct": true, "explanation": "正确。“连一克也称得出来”，“克”表示很小的重量。"}, {"text": "吨", "is_correct": false, "explanation": "语义：吨太大，与“连一…也”表示极小量的语义相反。"}, {"text": "秒", "is_correct": false, "explanation": "语义：秒是时间单位，不能用来计量重量，“连一秒也称得出来”说不通。"}, {"text": "斤", "is_correct": false, "explanation": "语义：斤是较大的重量单位，与“连一…也”的极小量语义冲突。"}], "explanations": {"克": "正确。“连一克也称得出来”，“克”表示很小的重量。", "吨": "语义：吨太大，与“连一…也”表示极小量的语义相反。", "秒": "语义：秒是时间单位，不能用来计量重量，“连一秒也称得出来”说不通。", "斤": "语义：斤是较大的重量单位，与“连一…也”的极小量语义冲突。"}, "sentence_index": 6, "correct_answer": "克"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校新建了三克大楼。", "explanation": "这里应该用〈座〉。克只用于称重，大楼要用“座”或“栋”。"}, {"text": "我们昨天看了一克电影。", "explanation": "这里应该用〈场〉。克只用于称重，电影要用“场”计量。"}, {"text": "他买了一克自行车。", "explanation": "这里应该用〈辆〉。克是重量单位，自行车要用“辆”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈称了三百个克面粉。", "corrected_sentence": "妈妈称了三百克面粉。", "error_description": "量词错误：“克”本身已是量词，“三百个克”多加了“个”，应说“三百克”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈想买两百克克牛肉，做晚饭。", "corrected_sentence": "妈妈想买两百克牛肉，做晚饭。", "error_description": "“克”重复：称重只用一个“克”，应说“两百克牛肉”，不能说“两百克克牛肉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba4a197-deb2-4229-955f-99daf38ca115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
