INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89797, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "去年，也就是今年的前一年。", "primary_collocate": null, "pronunciation": "qù suì", "ipa": "tɕʰy˥˩ suei˥˩", "syllable_count": 2, "sentences": [{"text": "去岁今日，我们一起去了西湖。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去岁考上了大学，今年读大二。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁的今天，这里还是一片空地。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起去岁，今年的物价高了不少。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁秋天，奶奶搬到了我们家。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁我去过一次海边，今年想再去。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树去岁刚种，今年就开花了。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁夏天雨水少，今年河水涨了很多。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去岁学会了游泳，今年准备参加比赛。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁年底，公司搬到了新楼里。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "今年的前一年，多用于书面表达", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7424e-dd54-40b2-af10-b5c6420f3f6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去岁", "is_correct": true, "explanation": "正确。“去岁今日”指去年的今天，与后句“去了西湖”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是时间词，不能作“今日”前的时间状语。"}, {"text": "身体", "is_correct": false, "explanation": "搭配：“身体”不能作时间状语，句中说不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能作时间状语，“心情今日”说不通。"}], "explanations": {"去岁": "正确。“去岁今日”指去年的今天，与后句“去了西湖”相符。", "石头": "语义：“石头”不是时间词，不能作“今日”前的时间状语。", "身体": "搭配：“身体”不能作时间状语，句中说不通。", "心情": "搭配：“心情”不能作时间状语，“心情今日”说不通。"}, "sentence_index": 0, "correct_answer": "去岁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去岁，我们马上就出发。", "explanation": "这里应该用〈待会儿〉。去岁指整整一年，不能与“马上”这种即刻的时间搭配。"}, {"text": "去岁刚一开门，你就打来了电话。", "explanation": "这里应该用〈现在〉。去岁指整整一年，不能修饰“刚一开门”这种瞬间的时间。"}, {"text": "去岁的会议我们马上就开。", "explanation": "这里应该用〈今天〉。去岁指整整一年，与“马上就开”这种近在眼前的安排矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去岁", "is_correct": true, "explanation": "正确。“去岁刚种”指去年刚种下，与后句“今年就开花了”相符。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年刚种，今年就开花”前后矛盾，树不可能先在明年种、今年开花。"}, {"text": "每天", "is_correct": false, "explanation": "语义：“每天”表示反复，不能和“刚种”这一次性的动作搭配。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“月亮”不能被种，“月亮刚种”说不通。"}], "explanations": {"去岁": "正确。“去岁刚种”指去年刚种下，与后句“今年就开花了”相符。", "明年": "语义：“明年刚种，今年就开花”前后矛盾，树不可能先在明年种、今年开花。", "每天": "语义：“每天”表示反复，不能和“刚种”这一次性的动作搭配。", "月亮": "搭配：“月亮”不能被种，“月亮刚种”说不通。"}, "sentence_index": 6, "correct_answer": "去岁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去岁片刻之间，雨就停了。", "explanation": "这里应该用〈刚才〉。去岁指整整一年，不能和“片刻之间”这种瞬间的时间搭配。"}, {"text": "去岁几秒钟，他就把饭吃完了。", "explanation": "这里应该用〈方才〉。去岁指整整一年，不能和“几秒钟”这种时间段搭配。"}, {"text": "去岁一个钟头，我们就拍完了照片。", "explanation": "这里应该用〈当时〉。去岁指整整一年，不能修饰“一个钟头”这种时间段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
