INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "（书面）去年。", "primary_collocate": null, "pronunciation": "qù suì", "ipa": "tɕʰy˥˩ suei˥˩", "syllable_count": 2, "sentences": [{"text": "去岁此时，我还在北京工作。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年雨水多，去岁却是大旱。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去岁毕业，如今已在银行上班。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁冬天很冷，今年却暖和多了。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁一别，我们至今未见。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是去岁修好的。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁他买了房子，今年又换了工作。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与去岁相比，今年的收成好得多。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲去岁生了一场病，现已痊愈。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁春天，我们在江边种了几棵树。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面语中指今年的前一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7424e-dd54-40b2-af10-b5c6420f3f6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去岁", "is_correct": true, "explanation": "正确。“去岁此时”指去年的这个时候，与后句的“还在北京工作”相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不是时间词，不能作“此时”的时间状语。"}, {"text": "身体", "is_correct": false, "explanation": "搭配：“身体”不能充当时间状语，“身体此时”说不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”不是时间词，句子不能说“海洋此时”。"}], "explanations": {"去岁": "正确。“去岁此时”指去年的这个时候，与后句的“还在北京工作”相符。", "月亮": "语义：“月亮”不是时间词，不能作“此时”的时间状语。", "身体": "搭配：“身体”不能充当时间状语，“身体此时”说不通。", "海洋": "语义：“海洋”不是时间词，句子不能说“海洋此时”。"}, "sentence_index": 0, "correct_answer": "去岁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去岁转眼间，他已经离开了办公室。", "explanation": "这里应该用〈刚才〉。去岁指整整一年，不能和“转眼间”这种瞬间的时间搭配。"}, {"text": "去岁一眨眼的工夫，我们就到了山顶。", "explanation": "这里应该用〈刚才〉。去岁指整整一年，不能和“一眨眼的工夫”这样的瞬间搭配。"}, {"text": "去岁，我们半小时后就到了机场。", "explanation": "这里应该用〈当时〉。去岁指整整一年，不能与“半小时后”这种短时间搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去岁", "is_correct": true, "explanation": "正确。“去岁”表示去年，与后句“今年又换了工作”形成对照。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”与后句的“今年”冲突，明年买房、今年换工作的顺序说不通。"}, {"text": "每天", "is_correct": false, "explanation": "语义：“每天”表示反复，不能和一次性的买房事件搭配。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能作时间状语，也不能充当“买房”的主语。"}], "explanations": {"去岁": "正确。“去岁”表示去年，与后句“今年又换了工作”形成对照。", "明年": "语义：“明年”与后句的“今年”冲突，明年买房、今年换工作的顺序说不通。", "每天": "语义：“每天”表示反复，不能和一次性的买房事件搭配。", "心情": "搭配：“心情”不能作时间状语，也不能充当“买房”的主语。"}, "sentence_index": 6, "correct_answer": "去岁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去岁十分钟，我们就吃完了饭。", "explanation": "这里应该用〈几天〉。去岁指整整一年，不能修饰“十分钟”这种时间段。"}, {"text": "去岁前几分钟，我还在家里吃饭。", "explanation": "这里应该用〈方才〉。去岁指整整一年，不能和“前几分钟”这种短时间搭配。"}, {"text": "去岁，我们一天就在江边种完了树。", "explanation": "这里应该用〈昨天〉。去岁指整整一年，不能与“一天就”这种短时间搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
