INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去岁的买了一辆车，现在还很新。", "corrected_sentence": "他去岁买了一辆车，现在还很新。", "error_description": "错误：“去岁”后多加了“的”，“去岁的买了一辆车”没有中心语，不成句。正确：“他去岁买了一辆车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
