INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89807, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "命令是大人物说的话,别人必须照着做。", "primary_collocate": null, "pronunciation": "mìng lìng", "ipa": "miŋ⁵¹ liŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "将军下了一道命令，大家都要马上出发。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵必须听从队长的命令。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的命令很清楚，今天一定要做完。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不敢不听国王的命令。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个命令让大家都很吃惊。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在军队里，命令比什么都重要。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令发出命令，船队立刻回港。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他接到命令后，马上离开了家。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有队长的命令，谁也不能开枪。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王的命令传遍了整个小城。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道命令", "label": "量词"}, {"form": "一条命令", "label": "量词"}], "register": "中性", "sense_fingerprint": "上级或权威人物发出的、必须服从的指示(名词)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede64bf9-61fe-41ae-8fa2-9847150bb0ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89807, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "命令", "is_correct": true, "explanation": "正确：命令指上级发出的、必须服从的指示，与“下了一道”和“马上出发”的语境相符。"}, {"text": "难题", "is_correct": false, "explanation": "语义：难题是需要解答的问题，不是必须服从的指示，与“马上出发”不符。"}, {"text": "谜语", "is_correct": false, "explanation": "语义：谜语是供人猜的题目，不能要求大家立刻行动。"}, {"text": "建议", "is_correct": false, "explanation": "搭配：“下”和“一道”不搭配“建议”，建议一般说“提出建议”。"}], "explanations": {"命令": "正确：命令指上级发出的、必须服从的指示，与“下了一道”和“马上出发”的语境相符。", "难题": "语义：难题是需要解答的问题，不是必须服从的指示，与“马上出发”不符。", "谜语": "语义：谜语是供人猜的题目，不能要求大家立刻行动。", "建议": "搭配：“下”和“一道”不搭配“建议”，建议一般说“提出建议”。"}, "sentence_index": 0, "correct_answer": "命令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们不敢不听国王的一只命令。", "explanation": "量词错误：〈一只〉用于动物等，“命令”应该用〈一道〉或〈一条〉。"}, {"text": "他们不敢不听邻居的命令。", "explanation": "〈命令〉要求发令者对听令者有上级权力，邻居没有这种身份，这里应该用〈请求〉。"}, {"text": "他们没有采纳国王的命令。", "explanation": "〈采纳〉多用于建议、意见，命令必须执行，这里应该用〈执行〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "命令", "is_correct": true, "explanation": "正确：司令发出的必须服从的指示，才能让船队立刻回港。"}, {"text": "请柬", "is_correct": false, "explanation": "语义：请柬是邀请函，不能让船队立刻回港。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是赠送的物品，不能让船队立刻回港。"}, {"text": "玩笑", "is_correct": false, "explanation": "搭配：“发出”后面不接“玩笑”，玩笑一般说“开玩笑”。"}], "explanations": {"命令": "正确：司令发出的必须服从的指示，才能让船队立刻回港。", "请柬": "语义：请柬是邀请函，不能让船队立刻回港。", "礼物": "语义：礼物是赠送的物品，不能让船队立刻回港。", "玩笑": "搭配：“发出”后面不接“玩笑”，玩笑一般说“开玩笑”。"}, "sentence_index": 6, "correct_answer": "命令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的命令很苦，一直没有好运气。", "explanation": "词义错误：〈命令〉指上级的指示，不表示命运，这里表达“命运”应该说〈命运〉。"}, {"text": "国王的命令很甜，大家都爱听。", "explanation": "搭配错误：〈甜〉形容味道或让人愉快的话语，不能用来形容〈命令〉这种要求别人服从的指示；描述它的态度应说〈严厉〉。"}, {"text": "救援人员在废墟里寻找命令的迹象。", "explanation": "词义错误：这里应该用〈生命〉，指人的生存状态；〈命令〉指上级的指示，与“寻找迹象”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上级发出了一只命令，所有人都要回营。", "corrected_sentence": "上级发出了一道命令，所有人都要回营。", "error_description": "量词错误：“命令”不能用“只”（“只”多用于动物等），应该用“道”（或“条”）。“一只命令”是错误形式，正确为“一道命令”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国王作了一道命令，全城的人都要关门。", "corrected_sentence": "国王下了一道命令，全城的人都要关门。", "error_description": "动词搭配错误：发出命令应说“下命令”，“作”不与“命令”搭配。正确为“国王下了一道命令”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
