INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89811, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "哪个是问是几个东西里面的哪一个。", "primary_collocate": null, "pronunciation": "nǎ ge", "ipa": "na˨˩ kɤ", "syllable_count": 2, "sentences": [{"text": "你想去哪个城市工作？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个人是你的老师？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道哪个才是对的。", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个盒子里，哪个有糖？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个电影你看过了？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多鞋，你穿哪个？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们谁知道哪个是我的包？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个季节你最喜欢？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个字你不会写？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她问我哪个更好看。", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哪個", "label": "繁体"}], "register": "口语", "sense_fingerprint": "哪个：问几个东西里面是哪一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cbaa39-5606-4121-8f90-fd77df64622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89811, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪个", "is_correct": true, "explanation": "正确：哪个在几个城市中指定一个，用于疑问，与“城市”搭配。"}, {"text": "每个", "is_correct": false, "explanation": "语义：“每个”指所有城市，与选择哪一个的疑问冲突，句子变成去所有城市工作。"}, {"text": "哪位", "is_correct": false, "explanation": "搭配：“哪位”用于问人，“城市”不是人，不能搭配。"}, {"text": "哪只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对的物件，不能修饰“城市”。"}], "explanations": {"哪个": "正确：哪个在几个城市中指定一个，用于疑问，与“城市”搭配。", "每个": "语义：“每个”指所有城市，与选择哪一个的疑问冲突，句子变成去所有城市工作。", "哪位": "搭配：“哪位”用于问人，“城市”不是人，不能搭配。", "哪只": "搭配：“只”多用于动物或成对的物件，不能修饰“城市”。"}, "sentence_index": 0, "correct_answer": "哪个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班哪个三位老师来了？", "explanation": "这里应该用〈哪几位〉。“哪个”后不能直接接数词，问不定数量要用“哪几位”。"}, {"text": "他是哪个年出生的？", "explanation": "这里应该用〈哪年〉。问年份要用“哪年”，“哪个”不能与“年”搭配。"}, {"text": "你最喜欢哪个水？", "explanation": "这里应该用〈哪杯〉或〈哪种〉。水不能用“个”计量，问选择要用“哪杯”或“哪种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪个", "is_correct": true, "explanation": "正确：哪个在几个包中指定一个，用于疑问，符合语境。"}, {"text": "哪位", "is_correct": false, "explanation": "搭配：“哪位”礼貌地用于问人，“包”不是人，不能搭配。"}, {"text": "谁", "is_correct": false, "explanation": "搭配：“谁”指人，句中问的是物品“包”，不能用来指物。"}, {"text": "哪种", "is_correct": false, "explanation": "语义：“哪种”问类别，句子问的是哪一个具体的包，语义不符。"}], "explanations": {"哪个": "正确：哪个在几个包中指定一个，用于疑问，符合语境。", "哪位": "搭配：“哪位”礼貌地用于问人，“包”不是人，不能搭配。", "谁": "搭配：“谁”指人，句中问的是物品“包”，不能用来指物。", "哪种": "语义：“哪种”问类别，句子问的是哪一个具体的包，语义不符。"}, "sentence_index": 6, "correct_answer": "哪个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你家住哪个？", "explanation": "这里应该用〈哪儿〉。问住址要用“哪儿”或“哪里”，哪个指具体事物中的一个。"}, {"text": "我的书包哪个三个坏了？", "explanation": "这里应该用〈哪几个〉。“哪个”后不能直接接数词，问不定数量要用“哪几个”。"}, {"text": "你想喝哪个牛奶？", "explanation": "这里应该用〈杯〉或〈瓶〉。牛奶是液体，要用“杯”“瓶”等计量，“哪个”不能与“牛奶”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几个房间里，哪个最大吗？", "corrected_sentence": "这几个房间里，哪个最大？", "error_description": "错误：疑问代词“哪个”已经表示疑问，句末又加了“吗”，构成重复设问。正确：“哪个最大？”，句末不加“吗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些字里，哪个了你不认识？", "corrected_sentence": "这些字里，哪个你不认识？", "error_description": "错误：“哪个”后多了“了”。正确：“哪个你不认识”。“哪个”作话题，中间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
