INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89812, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词,询问在几个中指的是哪一个。", "primary_collocate": null, "pronunciation": "nǎ ge", "ipa": "na˨˩ kɤ", "syllable_count": 2, "sentences": [{"text": "这两件衣服，你喜欢哪个？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个是你的杯子？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想坐哪个座位？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有三本书，哪个是新的？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些苹果里，哪个最大？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们班哪个同学会说日语？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个孩子在哭？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，哪个门可以进去？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红的和白的，你要哪个？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几条路，哪个最近？", "target_word": "哪个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哪個", "label": "繁体"}], "register": "口语", "sense_fingerprint": "哪个：疑问代词，在几个当中问是哪一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cbaa39-5606-4121-8f90-fd77df64622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89812, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪个", "is_correct": true, "explanation": "正确：哪个在“这两件衣服”中指定一件，符合疑问语境。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”用于问人，句中问的是衣服，句子不通。"}, {"text": "哪位", "is_correct": false, "explanation": "搭配：“哪位”礼貌地用于问人，不能用来指衣服。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问处所，衣服不是地点，句子不通。"}], "explanations": {"哪个": "正确：哪个在“这两件衣服”中指定一件，符合疑问语境。", "谁": "语义：“谁”用于问人，句中问的是衣服，句子不通。", "哪位": "搭配：“哪位”礼貌地用于问人，不能用来指衣服。", "哪儿": "语义：“哪儿”问处所，衣服不是地点，句子不通。"}, "sentence_index": 0, "correct_answer": "哪个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你是哪个天出生的？", "explanation": "这里应该用〈哪天〉。问日期要用“哪天”或“几号”，“哪个”用于在几个具体事物中指定一个，不能与“天”搭配。"}, {"text": "你想吃哪个米饭？", "explanation": "这里应该用〈哪碗〉。米饭用“碗”计量，“哪个”不能与“米饭”搭配。"}, {"text": "中国哪个河最长？", "explanation": "这里应该用〈哪条〉。河的量词是“条”，“个”不用于河。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪个", "is_correct": true, "explanation": "正确：哪个在几个孩子中指定一个，用于疑问，符合语境。"}, {"text": "哪只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对的物件，不能修饰“孩子”。"}, {"text": "每个", "is_correct": false, "explanation": "语义：“每个”指全体中的每一个，与“哪个”的选择性疑问冲突，句子不成问句。"}, {"text": "某个", "is_correct": false, "explanation": "语义：“某个”指不确定的某一个，不是在几个中提问，与句意不符。"}], "explanations": {"哪个": "正确：哪个在几个孩子中指定一个，用于疑问，符合语境。", "哪只": "搭配：“只”多用于动物或成对的物件，不能修饰“孩子”。", "每个": "语义：“每个”指全体中的每一个，与“哪个”的选择性疑问冲突，句子不成问句。", "某个": "语义：“某个”指不确定的某一个，不是在几个中提问，与句意不符。"}, "sentence_index": 6, "correct_answer": "哪个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你们班哪个三位学生会说日语？", "explanation": "这里应该用〈哪几位〉。“哪个”后不能直接接数词，问不定数量要用“哪几位”。"}, {"text": "我想喝哪个水？", "explanation": "这里应该用〈哪杯〉。水是液体，要用“杯”“瓶”等计量，“哪个”不能与“水”搭配。"}, {"text": "学校在哪个？", "explanation": "这里应该用〈哪儿〉。问处所要用“哪儿”或“哪里”，哪个指具体事物中的一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些盒子里，哪个本是空的？", "corrected_sentence": "这些盒子里，哪个是空的？", "error_description": "错误：“哪个”后多加了量词“本”。“个”已是量词，不能与“本”叠用；“本”也只用于书籍。应改为“哪个是空的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这三个答案里，哪个了是对的？", "corrected_sentence": "这三个答案里，哪个是对的？", "error_description": "错误：“哪个”后多了“了”。正确：“哪个是对的”。“哪个”在此作主语，中间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
