INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89813, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提高声音大声叫。", "primary_collocate": null, "pronunciation": "hǎn", "ipa": "xan˨˩˦", "syllable_count": 1, "sentences": [{"text": "球赛的时候，大家都大声地喊。", "target_word": "喊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他着急得对着山喊了起来。", "target_word": "喊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喊着口号往前走。", "target_word": "喊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看到起火了，马上喊“救命”。", "target_word": "喊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请小声说话，不要在教室里喊。", "target_word": "喊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对着大海喊了一声。", "target_word": "喊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众站起来，为球员喊加油。", "target_word": "喊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我嗓子疼，因为昨天喊得太久了。", "target_word": "喊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太生气了，对着他喊了起来。", "target_word": "喊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喊得太大声，宝宝都醒了。", "target_word": "喊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喊了", "label": "体标"}, {"form": "喊着", "label": "体标"}, {"form": "喊过", "label": "体标"}, {"form": "喊叫", "label": "复合"}], "register": "口语", "sense_fingerprint": "提高嗓门大声叫出话语或口号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf08968a-b4cb-4d8f-9f5e-355294b2811a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89813, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喊", "is_correct": true, "explanation": "喊（hǎn）意思是大声叫出话语，即本词条。"}, {"text": "含", "is_correct": false, "explanation": "含（hán，第二声）与喊（hǎn，第三声）声调不同，意思是包含、含着。"}, {"text": "感", "is_correct": false, "explanation": "感（gǎn）与喊的声母不同（g 与 h），意思是感觉。"}, {"text": "汗", "is_correct": false, "explanation": "汗（hàn，第四声）与喊（hǎn）声调不同，意思是汗水。"}], "explanations": {"喊": "喊（hǎn）意思是大声叫出话语，即本词条。", "含": "含（hán，第二声）与喊（hǎn，第三声）声调不同，意思是包含、含着。", "感": "感（gǎn）与喊的声母不同（g 与 h），意思是感觉。", "汗": "汗（hàn，第四声）与喊（hǎn）声调不同，意思是汗水。"}, "sentence_index": null, "correct_answer": "喊"}, "level_3": {"options": [{"text": "喊", "is_correct": true, "explanation": "正确。喊表示提高嗓门大声叫，与球赛时大声助威相合。"}, {"text": "写", "is_correct": false, "explanation": "语义：写不发声，不能与“大声地”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：吃不能用“大声地”修饰。"}, {"text": "切", "is_correct": false, "explanation": "语义：切是用刀分割，与“大声地”无关。"}], "explanations": {"喊": "正确。喊表示提高嗓门大声叫，与球赛时大声助威相合。", "写": "语义：写不发声，不能与“大声地”搭配。", "吃": "搭配：吃不能用“大声地”修饰。", "切": "语义：切是用刀分割，与“大声地”无关。"}, "sentence_index": 0, "correct_answer": "喊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把作业喊完了。", "explanation": "这里应该用〈写〉。喊只表示大声叫，不能用来表示完成作业；写作业要用写。"}, {"text": "他在台上喊了一首歌。", "explanation": "这里应该用〈唱〉。唱歌要用唱，喊只表示大声叫出话语。"}, {"text": "他一口气喊完了一碗饭。", "explanation": "这里应该用〈吃〉。喊只表示大声叫，不能与“一碗饭”搭配；吃饭要用吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89813, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "喊", "is_correct": true, "explanation": "喊（hǎn）意思是大声叫出话语，即本词条。"}, {"text": "汉", "is_correct": false, "explanation": "汉（hàn，第四声）与喊（hǎn，第三声）声调不同，意思是汉族。"}, {"text": "赶", "is_correct": false, "explanation": "赶（gǎn）与喊的声母不同（g 与 h），意思是追赶。"}, {"text": "海", "is_correct": false, "explanation": "海（hǎi）与喊的韵母不同（ai 与 an），意思是海洋。"}], "explanations": {"喊": "喊（hǎn）意思是大声叫出话语，即本词条。", "汉": "汉（hàn，第四声）与喊（hǎn，第三声）声调不同，意思是汉族。", "赶": "赶（gǎn）与喊的声母不同（g 与 h），意思是追赶。", "海": "海（hǎi）与喊的韵母不同（ai 与 an），意思是海洋。"}, "sentence_index": null, "correct_answer": "喊"}, "level_3": {"options": [{"text": "喊", "is_correct": true, "explanation": "正确。喊表示大声叫出口号，与为球员加油相合。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：拍是击打，“为球员拍加油”不能这样说。"}, {"text": "倒", "is_correct": false, "explanation": "语义：倒指倾倒，与为球员助威的语境不符。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是用脚击打，不表示助威。"}], "explanations": {"喊": "正确。喊表示大声叫出口号，与为球员加油相合。", "拍": "搭配：拍是击打，“为球员拍加油”不能这样说。", "倒": "语义：倒指倾倒，与为球员助威的语境不符。", "踢": "语义：踢是用脚击打，不表示助威。"}, "sentence_index": 6, "correct_answer": "喊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给妈妈喊了个电话。", "explanation": "这里应该用〈打〉。打电话要用打，喊不能与电话搭配。"}, {"text": "这种花喊月季。", "explanation": "这里应该用〈叫〉。叫可表示“名叫”，喊只表示大声呼唤，不能用来称呼事物。"}, {"text": "这首歌喊起了我的童年回忆。", "explanation": "这里应该用〈唤起〉。唤起指引发记忆、感情，喊不能与“回忆”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
