INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对着山谷得喊很响，大家才回头。", "corrected_sentence": "他对着山谷喊得很响，大家才回头。", "error_description": "错误形式：“得喊很响”；正确形式：“喊得很响”；原因：程度补语的“得”须紧接动词“喊”，“很响”放在“得”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
