dation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89814, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喊", "is_correct": true, "explanation": "喊（hǎn）意思是大声叫，即本词条。"}, {"text": "含", "is_correct": false, "explanation": "含（hán，第二声）与喊（hǎn，第三声）声调不同，意思是包含、含着。"}, {"text": "感", "is_correct": false, "explanation": "感（gǎn）与喊的声母不同（g 与 h），意思是感觉。"}, {"text": "汗", "is_correct": false, "explanation": "汗（hàn，第四声）与喊（hǎn）声调不同，意思是汗水。"}], "explanations": {"喊": "喊（hǎn）意思是大声叫，即本词条。", "含": "含（hán，第二声）与喊（hǎn，第三声）声调不同，意思是包含、含着。", "感": "感（gǎn）与喊的声母不同（g 与 h），意思是感觉。", "汗": "汗（hàn，第四声）与喊（hǎn）声调不同，意思是汗水。"}, "sentence_index": null, "correct_answer": "喊"}, "level_3": {"options": [{"text": "喊", "is_correct": true, "explanation": "正确。喊表示大声叫，妈妈在门口大声叫我回家吃饭。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹拭，不能用来叫人回家吃饭。"}, {"text": "削", "is_correct": false, "explanation": "语义：削是用刀去皮，与叫人回家吃饭无关。"}, {"text": "瞪", "is_correct": false, "explanation": "语义：瞪是怒视，与“叫我回家吃饭”不符。"}], "explanations": {"喊": "正确。喊表示大声叫，妈妈在门口大声叫我回家吃饭。", "擦": "语义：擦是抹拭，不能用来叫人回家吃饭。", "削": "语义：削是用刀去皮，与叫人回家吃饭无关。", "瞪": "语义：瞪是怒视，与“叫我回家吃饭”不符。"}, "sentence_index": 0, "correct_answer": "喊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种花喊月季。", "explanation": "这里应该用〈叫〉。叫可表示“名叫”，喊只表示大声呼唤，不能用来称呼事物。"}, {"text": "他一口气喊完了一碗面。", "explanation": "这里应该用〈吃〉。喊只表示大声叫，不能与“一碗面”搭配；吃面要用吃。"}, {"text": "这首歌喊起了我的童年回忆。", "explanation": "这里应该用〈唤起〉。唤起指引发记忆、感情，喊不能与“回忆”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89814, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "喊", "is_correct": true, "explanation": "喊（hǎn）意思是大声叫，即本词条。"}, {"text": "汉", "is_correct": false, "explanation": "汉（hàn，第四声）与喊（hǎn，第三声）声调不同，意思是汉族。"}, {"text": "赶", "is_correct": false, "explanation": "赶（gǎn）与喊的声母不同（g 与 h），意思是追赶。"}, {"text": "海", "is_correct": false, "explanation": "海（hǎi）与喊的韵母不同（ai 与 an），意思是海洋。"}], "explanations": {"喊": "喊（hǎn）意思是大声叫，即本词条。", "汉": "汉（hàn，第四声）与喊（hǎn，第三声）声调不同，意思是汉族。", "赶": "赶（gǎn）与喊的声母不同（g 与 h），意思是追赶。", "海": "海（hǎi）与喊的韵母不同（ai 与 an），意思是海洋。"}, "sentence_index": null, "correct_answer": "喊"}, "level_3": {"options": [{"text": "喊", "is_correct": true, "explanation": "正确。喊表示大声叫，让大家过来吃水果。"}, {"text": "推", "is_correct": false, "explanation": "搭配：推需要移动具体物体，不能带“大家来吃水果”作指令。"}, {"text": "拉", "is_correct": false, "explanation": "语义：拉是拽，不是叫人过来。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是用脚击打，与叫人来吃水果无关。"}], "explanations": {"喊": "正确。喊表示大声叫，让大家过来吃水果。", "推": "搭配：推需要移动具体物体，不能带“大家来吃水果”作指令。", "拉": "语义：拉是拽，不是叫人过来。", "踢": "语义：踢是用脚击打，与叫人来吃水果无关。"}, "sentence_index": 6, "correct_answer": "喊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在舞台上喊了一首新歌。", "explanation": "这里应该用〈唱〉。唱歌要用唱，喊只表示大声叫，不能用于歌曲。"}, {"text": "他把房间喊干净了。", "explanation": "这里应该用〈打扫〉。喊只表示大声叫，不能用来表示清理；打扫房间要用打扫。"}, {"text": "他给妈妈喊了个电话。", "explanation": "这里应该用〈打〉。打电话要用打，喊不能与电话搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子在院子里了喊小狗三声。", "corrected_sentence": "孩子在院子里喊了小狗三声。", "error_description": "错误形式：“了”放在“喊”前；正确形式：“喊了小狗三声”；原因：体标“了”须紧跟动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶在门口了喊我三次。", "corrected_sentence": "奶奶在门口喊了我三次。", "error_description": "错误形式：“了喊我三次”；正确形式：“喊了我三次”；原因：体标“了”须紧跟动词“喊”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
