INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89817, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国民是一个国家里的人。", "primary_collocate": null, "pronunciation": "guó mín", "ipa": "kwo˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "国民都应该遵守法律。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的国民很热情。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要照顾好每一位国民。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国民的生活越来越好了。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位国王很爱他的国民。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要教育国民爱护环境。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国民需要更多的公园。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全体国民都在看这场比赛。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的国民都说两种语言。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国民的健康是国家最重要的事。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國民", "label": "繁体"}, {"form": "国民经济", "label": "复合"}], "register": "书面", "sense_fingerprint": "国民：一个国家里的人民", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cbaa39-5606-4121-8f90-fd77df64622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89817, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国民", "is_correct": true, "explanation": "正确：国民指一国的人民，与“都应该遵守法律”搭配，句子通顺。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不能遵守法律，句子不通。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不能被要求遵守法律，句子不通。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”是数量概念，不能与“遵守法律”这类对人的要求搭配。"}], "explanations": {"国民": "正确：国民指一国的人民，与“都应该遵守法律”搭配，句子通顺。", "植物": "语义：植物不能遵守法律，句子不通。", "动物": "语义：动物不能被要求遵守法律，句子不通。", "人口": "搭配：“人口”是数量概念，不能与“遵守法律”这类对人的要求搭配。"}, "sentence_index": 0, "correct_answer": "国民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国民很大。", "explanation": "这里应该用〈国家〉。国民指国家里的人，不指国土，说国家的大小要用“国家”。"}, {"text": "我看见一只国民走过来。", "explanation": "这里应该用〈名〉。国民指人，人的量词是“名”或“个”，“只”用于动物。"}, {"text": "这个城市的国民很多。", "explanation": "这里应该用〈居民〉。居民指住在某地的人，城市里的人要说“居民”，国民指一国的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89817, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国民", "is_correct": true, "explanation": "正确：国民指一国的人，与“需要更多的公园”所指的人群相符，句子通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有“需要”，句子不通。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“汽车”不能作“需要”的主体，且“公园”是供人游玩的地方，与汽车不搭。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不是国民所指的人群，句子语义荒谬。"}], "explanations": {"国民": "正确：国民指一国的人，与“需要更多的公园”所指的人群相符，句子通顺。", "石头": "语义：石头没有“需要”，句子不通。", "汽车": "搭配：“汽车”不能作“需要”的主体，且“公园”是供人游玩的地方，与汽车不搭。", "老鼠": "语义：老鼠不是国民所指的人群，句子语义荒谬。"}, "sentence_index": 6, "correct_answer": "国民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班有三十个国民。", "explanation": "这里应该用〈同学〉。国民指一国的人，班里的人要说“同学”。"}, {"text": "我在超市买了一个国民。", "explanation": "这里应该用〈商品〉。国民指一国的人，不能指超市里买的东西。"}, {"text": "公司的国民都很努力。", "explanation": "这里应该用〈员工〉。国民指一国的人，公司里的人要说“员工”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家有两千万只国民。", "corrected_sentence": "这个国家有两千万国民。", "error_description": "错误：多了量词“只”。正确：不加量词，即“两千万国民”。“只”用于动物或单个物件，不能修饰表示人的国民。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家的国民了都很友好。", "corrected_sentence": "这个国家的国民都很友好。", "error_description": "错误：“国民”后多了“了”。正确：“这个国家的国民都很友好”。“了”不能插在名词“国民”和“都”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
