INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89818, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "具有某国国籍的人。", "primary_collocate": null, "pronunciation": "guó mín", "ipa": "kwo˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "领事馆会先核实伤者是否为本国国民。", "target_word": "国民", "complexity_tier": "T3", "furigana": "lǐng shì guǎn huì xiān hé shí shāng zhě shì fǒu wéi běn guó guó mín.", "sentence_source": "generated"}, {"text": "撤离时，本国国民可以凭护照出境。", "target_word": "国民", "complexity_tier": "T3", "furigana": "chè lí shí, běn guó guó mín kě yǐ píng hù zhào chū jìng.", "sentence_source": "generated"}, {"text": "出国前，本国国民应随身携带护照。", "target_word": "国民", "complexity_tier": "T3", "furigana": "chū guó qián, běn guó guó mín yīng suí shēn xié dài hù zhào.", "sentence_source": "generated"}, {"text": "凡持有本国国籍的人，都是本国国民。", "target_word": "国民", "complexity_tier": "T3", "furigana": "fán chí yǒu běn guó guó jí de rén, dōu shì běn guó guó mín.", "sentence_source": "generated"}, {"text": "这个国家的国民可以投票选总统。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外出生，却依然享有本国国民的各项权利。", "target_word": "国民", "complexity_tier": "T3", "furigana": "tā zài guó wài chū shēng, què yī rán xiǎng yǒu běn guó guó mín de gè xiàng quán lì.", "sentence_source": "generated"}, {"text": "大使馆会保护本国国民的安全。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他入籍后，与当地国民享有同等的权利。", "target_word": "国民", "complexity_tier": "T3", "furigana": "tā rù jí hòu, yǔ dāng dì guó mín xiǎng yǒu tóng děng de quán lì.", "sentence_source": "generated"}, {"text": "这个国家的国民不用办签证。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "撤离名单上的日本国民已全部离境。", "target_word": "国民", "complexity_tier": "T3", "furigana": "chè lí míng dān shàng de rì běn guó mín yǐ quán bù lí jìng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "國民", "label": "繁体"}, {"form": "国民经济", "label": "复合"}], "register": "书面", "sense_fingerprint": "国民：具有某国国籍的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cbaa39-5606-4121-8f90-fd77df64622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国民", "is_correct": true, "explanation": "正确：国民指具有本国国籍的人，领事馆核实伤者的国籍，符合语境。"}, {"text": "国王", "is_correct": false, "explanation": "语义：领事馆核实的是国籍，不是身份是否为君主，句子不合语境。"}, {"text": "护照", "is_correct": false, "explanation": "语义：护照是证件，不是人，“是否为本国护照”不通，句子不合语境。"}, {"text": "外国人", "is_correct": false, "explanation": "语义：“本国外国人”自相矛盾，句子不通。"}], "explanations": {"国民": "正确：国民指具有本国国籍的人，领事馆核实伤者的国籍，符合语境。", "国王": "语义：领事馆核实的是国籍，不是身份是否为君主，句子不合语境。", "护照": "语义：护照是证件，不是人，“是否为本国护照”不通，句子不合语境。", "外国人": "语义：“本国外国人”自相矛盾，句子不通。"}, "sentence_index": 0, "correct_answer": "国民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的国民很大。", "explanation": "这里应该用〈国家〉。国民指国家里的人，说国家的大小要用“国家”。"}, {"text": "他是学校的国民。", "explanation": "这里应该用〈老师〉。国民指具有某国国籍的人，学校里的教职员要说“老师”。"}, {"text": "他是一颗国民。", "explanation": "这里应该用〈名〉。“颗”用于小而圆的东西，国民指人，应该用“名”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国民", "is_correct": true, "explanation": "正确：国民指具有本国国籍的人，大使馆保护的是这些人的安全，符合语境。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不需要大使馆保护安全，句子不通。"}, {"text": "国籍", "is_correct": false, "explanation": "搭配：“国籍”不是人，不能有“安全”，且“保护国籍的安全”不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不需要大使馆保护，句子不通。"}], "explanations": {"国民": "正确：国民指具有本国国籍的人，大使馆保护的是这些人的安全，符合语境。", "树木": "语义：树木不需要大使馆保护安全，句子不通。", "国籍": "搭配：“国籍”不是人，不能有“安全”，且“保护国籍的安全”不成立。", "桌子": "语义：桌子不需要大使馆保护，句子不通。"}, "sentence_index": 6, "correct_answer": "国民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的国民都很喜欢吃饺子。", "explanation": "这里应该用〈家人〉。国民指具有某国国籍的人，家里的人要说“家人”。"}, {"text": "公司的国民都很努力。", "explanation": "这里应该用〈员工〉。国民指具有某国国籍的人，公司里的人要说“员工”。"}, {"text": "那辆国民开得很快。", "explanation": "这里应该用〈名〉。“辆”用于车辆，国民指人，应该用“名”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在本国出生，是本国个国民。", "corrected_sentence": "他在本国出生，是本国的国民。", "error_description": "错误：“个”放错了位置。正确：“本国的国民”。“个”不能插在定语“本国”和名词“国民”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一名本国国民了已经离境。", "corrected_sentence": "一名本国国民已经离境。", "error_description": "错误：“国民”后多了“了”。正确：“一名本国国民已经离境”。“了”不能插在“国民”和“已经”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "“大部分”指超过一半，“少数”指不足一半，二者是反义词。"}, {"text": "老师", "is_correct": false, "explanation": "与“大部分”没有反义关系，“老师”指职业人员，不是数量的相对词。"}, {"text": "窗户", "is_correct": false, "explanation": "与“大部分”没有反义关系，“窗户”是建筑部件，与数量无关。"}, {"text": "天空", "is_correct": false, "explanation": "与“大部分”没有反义关系，“天空”是自然景物，不表示数量。"}], "correct_answer": "少数", "explanations": {"少数": "“大部分”指超过一半，“少数”指不足一半，二者是反义词。", "老师": "与“大部分”没有反义关系，“老师”指职业人员，不是数量的相对词。", "窗户": "与“大部分”没有反义关系，“窗户”是建筑部件，与数量无关。", "天空": "与“大部分”没有反义关系，“天空”是自然景物，不表示数量。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "“大部分”指超过一半，“少数”指不足一半，二者是反义词。"}, {"text": "书包", "is_correct": false, "explanation": "与“大部分”没有反义关系，“书包”是背东西的用具，与数量无关。"}, {"text": "河流", "is_correct": false, "explanation": "与“大部分”没有反义关系，“河流”是自然景物，不表示数量。"}, {"text": "桌子", "is_correct": false, "explanation": "与“大部分”没有反义关系，“桌子”是家具，与数量无关。"}], "correct_answer": "少数", "explanations": {"少数": "“大部分”指超过一半，“少数”指不足一半，二者是反义词。", "书包": "与“大部分”没有反义关系，“书包”是背东西的用具，与数量无关。", "河流": "与“大部分”没有反义关系，“河流”是自然景物，不表示数量。", "桌子": "与“大部分”没有反义关系，“桌子”是家具，与数量无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大部分是一大半,多的那一些。", "primary_collocate": null, "pronunciation": "dà bù fen", "ipa": "ta˥˩ pu˥˩ fən", "syllable_count": 3, "sentences": [{"text": "班里大部分同学都喜欢踢足球。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大部分人早上坐地铁去上班。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些苹果大部分已经坏了。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大部分学生通过了这次考试。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里大部分东西都在打折。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司大部分员工住在附近。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大部分时候他都在家看书。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子里的书，大部分是我买的。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业大部分我已经做完了。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来参加会议的大部分是老师。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "一群人或事物中超过一半的多数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1fc457-8ada-4586-9ab8-800b096dd014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大部分", "is_correct": true, "explanation": "“大部分”指一大半，修饰“同学”，与“都喜欢踢足球”相符，是唯一符合句意的词。"}, {"text": "一半", "is_correct": false, "explanation": "语义：“一半”只有二分之一，与后面的“都”（表示全体）矛盾。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教具，不能修饰“同学”表示数量，“班里黑板同学”不成立。"}, {"text": "对象", "is_correct": false, "explanation": "搭配：“对象”不能用来修饰“同学”表示数量，“班里对象同学”不成立。"}], "explanations": {"大部分": "“大部分”指一大半，修饰“同学”，与“都喜欢踢足球”相符，是唯一符合句意的词。", "一半": "语义：“一半”只有二分之一，与后面的“都”（表示全体）矛盾。", "黑板": "语义：“黑板”是教具，不能修饰“同学”表示数量，“班里黑板同学”不成立。", "对象": "搭配：“对象”不能用来修饰“同学”表示数量，“班里对象同学”不成立。"}, "sentence_index": 0, "correct_answer": "大部分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里大部分同学一个也没有通过考试。", "explanation": "此句中的“大部分”表示超过一半，与“一个也没有”（零）矛盾。改为“班里没有同学通过考试”或“班里大部分同学没有通过考试”即可成立。"}, {"text": "班里大部分同学正好一半通过了考试。", "explanation": "此句中的“大部分”表示超过一半，与“正好一半”（恰好二分之一）矛盾。本义项指多数，不能用来表示恰好一半，应该用〈半数〉。"}, {"text": "班里大部分同学每个人都通过了考试。", "explanation": "此句中的“大部分”表示超过一半，而“每个人都”表示全体，二者矛盾。本义项指多数而非全体，应该用〈全体〉来表示全部人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大部分", "is_correct": true, "explanation": "“大部分时候”指多数时间，与“他都在家看书”的习惯相符，是唯一符合句意的词。"}, {"text": "片刻", "is_correct": false, "explanation": "语义：“片刻”指很短的时间，与“都在家看书”这种长时段的习惯矛盾。"}, {"text": "瞬间", "is_correct": false, "explanation": "语义：“瞬间”指极短的时刻，无法与“都在家看书”这种常态搭配。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“名字”不表示时间段，与“时候”无法搭配，“名字时候”不成立。"}], "explanations": {"大部分": "“大部分时候”指多数时间，与“他都在家看书”的习惯相符，是唯一符合句意的词。", "片刻": "语义：“片刻”指很短的时间，与“都在家看书”这种长时段的习惯矛盾。", "瞬间": "语义：“瞬间”指极短的时刻，无法与“都在家看书”这种常态搭配。", "名字": "搭配：“名字”不表示时间段，与“时候”无法搭配，“名字时候”不成立。"}, "sentence_index": 6, "correct_answer": "大部分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些饼干大部分被我吃光了。", "explanation": "这里应该用〈全部〉。“吃光”表示全部吃完，“大部分”只表示超过一半，与“吃光”矛盾。"}, {"text": "这些苹果大部分只有一个是坏的。", "explanation": "此句中的“大部分”表示超过一半，而“只有一个”表示数量极少，二者矛盾。这里应该用〈个别〉，表示少数几个。"}, {"text": "班里大部分同学迟到的人数正好为零。", "explanation": "此句中的“大部分”表示超过一半，而“正好为零”表示没有人迟到，二者矛盾。改为“班里没有人迟到”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班大部分个同学都爱打篮球。", "corrected_sentence": "我们班大部分同学都爱打篮球。", "error_description": "“大部分”后面直接接名词，不能再加量词“个”。错误形式是“大部分个同学”，正确形式是“大部分同学”，因为“大部分”本身不需要量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛大部分选手的都来自外地。", "corrected_sentence": "这次比赛大部分选手都来自外地。", "error_description": "错误：“的”放在了“选手”后面（“选手的都”），句子不通。“大部分”后面可以接“的”（大部分的选手都来自外地），但这里应去掉“选手”后的“的”，即“大部分选手都来自外地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
