INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89832, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词,表示结果或进一步行动。", "primary_collocate": null, "pronunciation": "cóng ér", "ipa": "tsʰʊŋ˧˥ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "工人们加快了速度，从而提前完成了任务。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不断努力学习，从而掌握了一门新技术。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究了这种病毒，从而找到了治疗方法。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家互相帮助，从而使班级更团结。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她了解了对方的想法，从而做出了正确的决定。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民改用新种子，从而提高了粮食产量。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们认真分析问题，从而发现了其中的原因。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行让他看到了世界，从而改变了看法。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校增加了活动，从而丰富了学生的生活。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经常运动能增强体质，从而减少生病的机会。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "连词，承接前一动作，引出结果或进一步的行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1fc457-8ada-4586-9ab8-800b096dd014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从而", "is_correct": true, "explanation": "从而：表示前面的做法带来后面的结果，符合句意。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”需要与“却、也”呼应，这里不能单独用来连接结果。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，与“加快速度→提前完成”的因果关系相反。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”引出补充理由，不能表示“加快速度”之后的结果。"}], "explanations": {"从而": "从而：表示前面的做法带来后面的结果，符合句意。", "虽然": "搭配：“虽然”需要与“却、也”呼应，这里不能单独用来连接结果。", "然而": "语义：“然而”表示转折，与“加快速度→提前完成”的因果关系相反。", "况且": "语义：“况且”引出补充理由，不能表示“加快速度”之后的结果。"}, "sentence_index": 0, "correct_answer": "从而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他小心走路，从而摔倒了。", "explanation": "这里应该用〈以免〉。“以免”表示避免不希望发生的事；“从而”只引出实际发生的结果或进一步行动，不表示避免。"}, {"text": "他会游泳，从而还会滑雪。", "explanation": "这里应该用〈此外〉。“此外”表示补充；“从而”表示由前一行为得出的结果，不能用来补充。"}, {"text": "他很努力，从而没考上。", "explanation": "这里应该用〈但是〉。“但是”表示转折；“从而”只承接顺向的结果，不能表示与前文相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从而", "is_correct": true, "explanation": "从而：表示前面的做法带来后面的结果，符合句意。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”要与“却、也”呼应，这里后面没有这类词，句子不成立。"}, {"text": "可是", "is_correct": false, "explanation": "语义：“可是”表示转折，与“分析问题→发现原因”的顺承关系不符。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示转折，句子读起来像分析失败，与原意不符。"}], "explanations": {"从而": "从而：表示前面的做法带来后面的结果，符合句意。", "尽管": "搭配：“尽管”要与“却、也”呼应，这里后面没有这类词，句子不成立。", "可是": "语义：“可是”表示转折，与“分析问题→发现原因”的顺承关系不符。", "不过": "语义：“不过”表示转折，句子读起来像分析失败，与原意不符。"}, "sentence_index": 6, "correct_answer": "从而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一边跑步，从而听了几首歌。", "explanation": "这里应该用〈同时〉。“同时”表示两件事一起进行；“从而”要求前一行为带来后一结果，跑步并不导致听歌，所以不能用“从而”。"}, {"text": "他先洗了澡，从而看了一会儿书。", "explanation": "这里应该用〈然后〉。“然后”只表示先后顺序；“从而”要求前一行为带来后一结果，洗澡和看书之间没有这种关系。"}, {"text": "她很聪明，从而很勤奋。", "explanation": "这里应该用〈并且〉。“并且”连接并列的两项性质；“从而”不表示并列，不能用来连接两个并列的性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们加强沟通，就从而减少了误会。", "corrected_sentence": "我们加强沟通，从而减少了误会。", "error_description": "“就”与“从而”都引出由前文带来的结果，二者叠用重复、不通顺；应去掉“就”，说“我们加强沟通，从而减少了误会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坚持训练，因此从而提高了体能。", "corrected_sentence": "我们坚持训练，从而提高了体能。", "error_description": "错误：“因此”与“从而”都引出由前文带来的结果，二者叠用重复、不通顺。正确：应去掉“因此”，说“我们坚持训练，从而提高了体能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
