INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89835, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "怕是心里不敢,想躲开。", "primary_collocate": null, "pronunciation": "pà", "ipa": "pʰa˥˩", "syllable_count": 1, "sentences": [{"text": "我怕狗,看到大狗就走开。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕黑,晚上睡觉要开灯。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩怕打针,一看到医生就哭。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很怕蛇,不敢去那座山。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟怕老师,不敢大声说话。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不怕冷,冬天也穿得很少。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他最怕考试,所以每次都很紧张。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别怕,我在这儿,没有人会打你。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就怕高,不敢坐过山车。", "target_word": "怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都怕那个爱发脾气的经理。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不怕", "label": "否定"}, {"form": "怕了", "label": "体标"}, {"form": "害怕", "label": "复合"}, {"form": "可怕", "label": "复合"}], "register": "中性", "sense_fingerprint": "怕:对人或事物心里不敢,想躲开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36c33a4a-e234-4e15-897c-30965f67ead3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89835, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "怕", "is_correct": true, "explanation": "pà（第四声）是“怕”，指心里不敢、想躲开。"}, {"text": "爬", "is_correct": false, "explanation": "pá（第二声）与 pà（第四声）声调不同，意思是攀爬。"}, {"text": "把", "is_correct": false, "explanation": "bǎ（第三声）与 pà 声母、声调都不同，意思是把握、把手。"}, {"text": "霸", "is_correct": false, "explanation": "bà（第四声）与 pà 声母不同，意思是称霸、霸占。"}, {"text": "趴", "is_correct": false, "explanation": "pā（第一声）与 pà 声调不同，意思是伏在某处。"}, {"text": "八", "is_correct": false, "explanation": "bā（第一声）与 pà 声母、声调都不同，意思是数字八。"}], "explanations": {"怕": "pà（第四声）是“怕”，指心里不敢、想躲开。", "爬": "pá（第二声）与 pà（第四声）声调不同，意思是攀爬。", "把": "bǎ（第三声）与 pà 声母、声调都不同，意思是把握、把手。", "霸": "bà（第四声）与 pà 声母不同，意思是称霸、霸占。", "趴": "pā（第一声）与 pà 声调不同，意思是伏在某处。", "八": "bā（第一声）与 pà 声母、声调都不同，意思是数字八。"}, "sentence_index": null, "correct_answer": "怕"}, "level_3": {"options": [{"text": "怕", "is_correct": true, "explanation": "正确：“怕”表示心里不敢，与后句“看到大狗就走开”的回避相合。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”表示喜爱，与后句“看到大狗就走开”的回避矛盾。"}, {"text": "亲近", "is_correct": false, "explanation": "语义：“亲近”表示接近，与后句的“走开”正好相反。"}, {"text": "仰慕", "is_correct": false, "explanation": "语域：“仰慕”语体庄重，多用于敬佩他人，不符合这里的日常口语。"}], "explanations": {"怕": "正确：“怕”表示心里不敢，与后句“看到大狗就走开”的回避相合。", "喜欢": "语义：“喜欢”表示喜爱，与后句“看到大狗就走开”的回避矛盾。", "亲近": "语义：“亲近”表示接近，与后句的“走开”正好相反。", "仰慕": "语域：“仰慕”语体庄重，多用于敬佩他人，不符合这里的日常口语。"}, "sentence_index": 0, "correct_answer": "怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我怕来不及了，你们先走吧。", "explanation": "这里“怕”表示担心赶不上，属于〈担心〉义，不是心里不敢、想躲开。"}, {"text": "妈妈很怕我的身体，每天都让我多穿衣服。", "explanation": "这里应该用〈担心〉。怕指心里不敢、想躲开，对身体健康的牵挂要用担心。"}, {"text": "他怕是病了，今天没来上课。", "explanation": "这里“怕”表示推测，相当于“恐怕”，不表示心里不敢、想躲开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89835, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "怕", "is_correct": true, "explanation": "pà（第四声）是“怕”，指心里不敢、想躲开。"}, {"text": "爸", "is_correct": false, "explanation": "bà（第四声）与 pà 声母不同，意思是爸爸。"}, {"text": "罢", "is_correct": false, "explanation": "bà（第四声）与 pà 声母不同，意思是停止、罢了。"}, {"text": "扒", "is_correct": false, "explanation": "pá（第二声）与 pà 声调不同，意思是用手拨开或抓取。"}, {"text": "巴", "is_correct": false, "explanation": "bā（第一声）与 pà 声母、声调都不同，意思是期望、紧贴。"}], "explanations": {"怕": "pà（第四声）是“怕”，指心里不敢、想躲开。", "爸": "bà（第四声）与 pà 声母不同，意思是爸爸。", "罢": "bà（第四声）与 pà 声母不同，意思是停止、罢了。", "扒": "pá（第二声）与 pà 声调不同，意思是用手拨开或抓取。", "巴": "bā（第一声）与 pà 声母、声调都不同，意思是期望、紧贴。"}, "sentence_index": null, "correct_answer": "怕"}, "level_3": {"options": [{"text": "怕", "is_correct": true, "explanation": "正确：“怕”表示心里不敢，与后句“每次都很紧张”的心理相合。"}, {"text": "爱", "is_correct": false, "explanation": "语义：“爱”表示喜欢，与后句“每次都很紧张”矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”后面多接乐趣、生活等，一般不说享受考试。"}, {"text": "热爱", "is_correct": false, "explanation": "语域：“热爱”语体庄重，多用于事业、理想，不用于日常说考试。"}], "explanations": {"怕": "正确：“怕”表示心里不敢，与后句“每次都很紧张”的心理相合。", "爱": "语义：“爱”表示喜欢，与后句“每次都很紧张”矛盾。", "享受": "搭配：“享受”后面多接乐趣、生活等，一般不说享受考试。", "热爱": "语域：“热爱”语体庄重，多用于事业、理想，不用于日常说考试。"}, "sentence_index": 6, "correct_answer": "怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很怕你，你帮我解决了那么大的问题。", "explanation": "这里应该用〈感激〉。怕表示心里不敢、想躲开，对帮助过自己的人表示谢意要用感激。"}, {"text": "我很怕他的勇气，他真让人佩服。", "explanation": "这里应该用〈敬佩〉。怕表示心里不敢、想躲开，对别人的勇气表示赞叹要用敬佩。"}, {"text": "他怕这份工作做不完，所以每天都主动加班。", "explanation": "这里“怕”表示担心工作做不完，应为〈担心〉义，不是心里不敢、想躲开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子怕地不敢一个人睡觉。", "corrected_sentence": "孩子怕得不敢一个人睡觉。", "error_description": "错误：程度补语的标记“得”写成了“地”。“地”用在动词前作状语，“怕得不敢”表示怕到什么程度，应用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子怕很打雷，一打雷就钻进被子里。", "corrected_sentence": "孩子怕打雷，一打雷就钻进被子里。", "error_description": "错误：“很”插在“怕”和“打雷”之间，修饰“打雷”，不通。正确应为“怕打雷”，不加“很”，“很”不能修饰动宾短语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
