INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89851, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "常常在一起玩，互相喜欢的人。", "primary_collocate": null, "pronunciation": "hǎo péng you", "ipa": "xaʊ˨˩˦ pʰɤŋ˧˥ joʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "小明是我的好朋友，我们天天一起玩。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和好朋友在公园里玩球。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的好朋友今天来她家做客。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，我和好朋友一起跳绳。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有三个好朋友，都住在我家旁边。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新玩具借给了好朋友。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友来了，弟弟高兴得又跳又笑。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是好朋友，所以常常分享零食。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和好朋友坐在同一张桌子旁。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我跟好朋友玩了一下午积木。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个好朋友", "label": "量词"}, {"form": "好朋友们", "label": "复数"}], "register": "口语", "sense_fingerprint": "常一起玩、互相喜欢的玩伴式朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e9126ca-4af1-43ae-8d7f-a545c9374384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89851, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好朋友", "is_correct": true, "explanation": "好朋友：常常在一起玩、互相喜欢的人，与“我们天天一起玩”相合。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“我的陌生人”与“天天一起玩”的亲近关系矛盾，句意不合。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师与学生一般不会像玩伴一样天天一起玩，语境不合。"}, {"text": "客人", "is_correct": false, "explanation": "搭配：“客人”不能和“天天一起玩”搭配，客人一般不会天天来玩。"}], "explanations": {"好朋友": "好朋友：常常在一起玩、互相喜欢的人，与“我们天天一起玩”相合。", "陌生人": "语义：“我的陌生人”与“天天一起玩”的亲近关系矛盾，句意不合。", "老师": "语义：老师与学生一般不会像玩伴一样天天一起玩，语境不合。", "客人": "搭配：“客人”不能和“天天一起玩”搭配，客人一般不会天天来玩。"}, "sentence_index": 0, "correct_answer": "好朋友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有一只好朋友，他住在隔壁。", "explanation": "这里应该用量词〈个〉。好朋友指人，“只”多用于动物。"}, {"text": "公交车上有一个好朋友一直盯着我看。", "explanation": "“好朋友”指常在一起、互相喜欢的人，不能用来指陌生人。"}, {"text": "我在火车上认识了一个好朋友，只聊了一分钟。", "explanation": "这里误把〈好朋友〉当作〈相识不久的人〉。“好朋友”需要长期相处、互相喜欢，只聊一分钟不能用这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89851, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好朋友", "is_correct": true, "explanation": "好朋友：互相喜欢、常常在一起的人，与“来了，弟弟高兴得又跳又笑”相合。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷来了不会让人高兴，与“高兴得又跳又笑”意思相反。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人是对立的人，不会让人高兴得又跳又笑。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：陌生人来了，孩子一般不会高兴得又跳又笑，与句意不合。"}], "explanations": {"好朋友": "好朋友：互相喜欢、常常在一起的人，与“来了，弟弟高兴得又跳又笑”相合。", "小偷": "语义：小偷来了不会让人高兴，与“高兴得又跳又笑”意思相反。", "敌人": "语义：敌人是对立的人，不会让人高兴得又跳又笑。", "陌生人": "语义：陌生人来了，孩子一般不会高兴得又跳又笑，与句意不合。"}, "sentence_index": 6, "correct_answer": "好朋友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和好朋友经常互相讨厌，从不说话。", "explanation": "这里误把〈好朋友〉当作〈冤家〉。“好朋友”指互相喜欢的人，不能用来形容互相讨厌的人。"}, {"text": "我和好朋友是邻居，却从来没说过一句话。", "explanation": "这里误把〈好朋友〉当作〈熟人〉。“好朋友”需要互相喜欢、常在一起，只是住得近、从不交谈就不能用这个词。"}, {"text": "我的好朋友昨天刚出生，还不会说话。", "explanation": "这里误把〈好朋友〉当作〈小宝宝〉。“好朋友”指能常在一起玩、互相喜欢的人，刚出生的婴儿不能与人互动，不能用这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89851, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有三好朋友，我们常常一起玩。", "corrected_sentence": "我有三个好朋友，我们常常一起玩。", "error_description": "数词“三”后缺少量词。应说“三个好朋友”，不能直接说“三好朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89851, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的好朋友的很喜欢玩具。", "corrected_sentence": "我的好朋友很喜欢玩具。", "error_description": "多出了助词“的”。“我的好朋友”已经完整，后面应直接接“很喜欢玩具”，应删去第二个“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
