INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89852, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "感情深厚、关系亲密的朋友。", "primary_collocate": null, "pronunciation": "hǎo péng you", "ipa": "xaʊ˨˩˦ pʰɤŋ˧˥ joʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是我二十年的好朋友，什么话都能说。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到难事时，好朋友总会帮我。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们做了十年好朋友，从没吵过架。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她难过的时候，只有好朋友懂她。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友生病了，我每天去医院看他。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就算离得很远，我们还是好朋友。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友之间不用说谢谢。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把心里的秘密告诉了好朋友。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后，我和好朋友常常打电话。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真正的好朋友会在你最难的时候陪着你。", "target_word": "好朋友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个好朋友", "label": "量词"}, {"form": "好朋友们", "label": "复数"}], "register": "中性", "sense_fingerprint": "感情深厚、关系亲密、可以信任的朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e9126ca-4af1-43ae-8d7f-a545c9374384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好朋友", "is_correct": true, "explanation": "好朋友：感情深厚、关系亲密的朋友，与“二十年”和“什么话都能说”相合。"}, {"text": "熟人", "is_correct": false, "explanation": "语义：熟人只是认识的人，与“什么话都能说”的亲密程度不合。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：陌生人与“二十年”和“什么话都能说”明显矛盾。"}, {"text": "路人", "is_correct": false, "explanation": "搭配：“路人”一般不会相处二十年，与“二十年的”搭配不当。"}], "explanations": {"好朋友": "好朋友：感情深厚、关系亲密的朋友，与“二十年”和“什么话都能说”相合。", "熟人": "语义：熟人只是认识的人，与“什么话都能说”的亲密程度不合。", "陌生人": "语义：陌生人与“二十年”和“什么话都能说”明显矛盾。", "路人": "搭配：“路人”一般不会相处二十年，与“二十年的”搭配不当。"}, "sentence_index": 0, "correct_answer": "好朋友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有一只好朋友，他很会讲故事。", "explanation": "这里应该用量词〈个〉。好朋友指人，“只”多用于动物。"}, {"text": "门口那个陌生人是她的好朋友，她从不认识他。", "explanation": "这里误把〈好朋友〉当作〈泛泛之交〉。“好朋友”指感情深厚、彼此信任的人，不能用来指从不认识的人。"}, {"text": "她在火车上遇到一个好朋友，只说了一句话。", "explanation": "这里误把〈好朋友〉当作〈路人〉。“好朋友”需要长期的信任与相处，只说一句话不能用这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好朋友", "is_correct": true, "explanation": "好朋友：感情深厚、可以信任的朋友，与“好朋友之间不用说谢谢”相合。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人是对立的关系，与“不用说谢谢”所说的亲密关系相反。"}, {"text": "对手", "is_correct": false, "explanation": "语义：对手之间有竞争，没有“不用说谢谢”的亲近关系。"}, {"text": "客人", "is_correct": false, "explanation": "搭配：“客人之间”一般不说“不用说谢谢”，这个搭配不当。"}], "explanations": {"好朋友": "好朋友：感情深厚、可以信任的朋友，与“好朋友之间不用说谢谢”相合。", "敌人": "语义：敌人是对立的关系，与“不用说谢谢”所说的亲密关系相反。", "对手": "语义：对手之间有竞争，没有“不用说谢谢”的亲近关系。", "客人": "搭配：“客人之间”一般不说“不用说谢谢”，这个搭配不当。"}, "sentence_index": 6, "correct_answer": "好朋友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和好朋友经常互相讨厌，从不说话。", "explanation": "这里误把〈好朋友〉当作〈冤家〉。“好朋友”以互相信任、亲近为基础，不能用来形容互相讨厌的人。"}, {"text": "我和好朋友第一次见面，只说了一句“你好”。", "explanation": "这里误把〈好朋友〉当作〈刚认识的人〉。“好朋友”需要长期相处、彼此信任，第一次见面不能这样称呼。"}, {"text": "我的好朋友昨天刚出生，还不会说话。", "explanation": "这里误把〈好朋友〉当作〈小宝宝〉。“好朋友”需要长期的信任与相处，刚出生的婴儿不能这样称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我的一只好朋友，什么都能说。", "corrected_sentence": "他是我的一个好朋友，什么都能说。", "error_description": "“好朋友”指人，量词应用“个”，不能用“只”（“只”多用于动物）。应说“他是我的一个好朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是我的好朋友的，什么都能说。", "corrected_sentence": "他是我的好朋友，什么都能说。", "error_description": "“好朋友”后面不能再加“的”。应说“他是我的好朋友，什么都能说”，去掉“好朋友”后多出的“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
