INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国外;海洋之外的地方。", "primary_collocate": null, "pronunciation": "hǎi wài", "ipa": "xaɪ˨˩ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他常常去海外出差。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的儿子在海外定居了。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在海外的中国人也很关心家乡的变化。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去海外看看不同的文化。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内的东西比海外便宜很多。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画在海外卖得很好。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在海外学了三年音乐。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海外的市场对这家工厂很重要。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，海外的亲戚都回来了。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从海外回来的人要先检查身体。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海外市场", "label": "复合"}], "register": "中性", "sense_fingerprint": "海外：国外，海洋之外的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cbaa39-5606-4121-8f90-fd77df64622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是出差的地方，与“出差”的语境冲突。"}, {"text": "海外", "is_correct": true, "explanation": "正确：“海外”指国外，可以作“去”的处所，表示到国外出差。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史不是可以前往的地方，与“去”的语境冲突。"}, {"text": "星期天", "is_correct": false, "explanation": "搭配：“去”后面要接地点，星期天是时间，不能说“去星期天出差”。"}], "explanations": {"厨房": "语义：厨房不是出差的地方，与“出差”的语境冲突。", "海外": "正确：“海外”指国外，可以作“去”的处所，表示到国外出差。", "历史": "语义：历史不是可以前往的地方，与“去”的语境冲突。", "星期天": "搭配：“去”后面要接地点，星期天是时间，不能说“去星期天出差”。"}, "sentence_index": 0, "correct_answer": "海外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们喜欢在老家的海外晒太阳，看海浪。", "explanation": "这里应该用〈海边〉。海外指国外，与“老家”连用自相矛盾；晒太阳看海浪要说海边。"}, {"text": "我每天坐一小时地铁，从海外去上班。", "explanation": "这里应该用〈市区〉。海外指国外，每天坐地铁上班说的是城市内部，不能说“从海外去”。"}, {"text": "我去过三座海外。", "explanation": "这里应该用〈国家〉。〈座〉用于山、楼等大而固定的东西，不能数“海外”，应说“去过三个国家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课桌", "is_correct": false, "explanation": "搭配：“学”的处所应是教室、琴房等，课桌不是学习音乐的地方。"}, {"text": "海外", "is_correct": true, "explanation": "正确：“在海外学”表示在国外学习，与“学了三年音乐”搭配。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能作学习的处所，与句子的语境冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是学习的地方，句子读起来不合常理。"}], "explanations": {"课桌": "搭配：“学”的处所应是教室、琴房等，课桌不是学习音乐的地方。", "海外": "正确：“在海外学”表示在国外学习，与“学了三年音乐”搭配。", "月亮": "语义：月亮不能作学习的处所，与句子的语境冲突。", "冰箱": "语义：冰箱不是学习的地方，句子读起来不合常理。"}, "sentence_index": 6, "correct_answer": "海外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个港口在北京海外，来往的船很多。", "explanation": "这里应该用〈沿海〉。海外指国外，不能和“北京”连用来说港口的位置。"}, {"text": "我买了一颗海外，回家后送给朋友。", "explanation": "这里应该用〈地方〉。〈颗〉用于粒状的小东西，海外是地方，不能当作可以买的东西来数。"}, {"text": "饭桌上摆满了海外，大家都很开心。", "explanation": "这里应该用〈食物〉。海外是地方，不能当作可以摆在桌上的东西，应说“摆满了食物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹打算去在海外留学。", "corrected_sentence": "妹妹打算去海外留学。", "error_description": "“去”后面直接接处所，不用“在”。应说“去海外留学”，不说“去在海外留学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在海外回来，就一直很忙。", "corrected_sentence": "他从海外回来，就一直很忙。", "error_description": "表示“从某地来”要用介词“从”，“在海外回来”不对。应说“从海外回来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a2f68b-351a-4939-9e8c-de2a5bc94c7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
