INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89859, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当年是很久以前的那一年。", "primary_collocate": null, "pronunciation": "dāng nián", "ipa": "taŋ˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "那年我刚上大学，当年的冬天特别冷。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年秋天，这里下了一场大雨。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，当年的雪比今年大多了。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年春天，他一个人去了南方。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书是十年前买的，当年只卖五块钱。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年的今天，我们第一次见面。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年的考试很难，很多人都没有通过。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年他离开家乡，一走就是十年。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年的秋天，我们种了这棵树。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年夏天特别热，河里的水都少了。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指很久以前的某一年，常带季节或事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab662d8-6e47-445d-add0-71f7968b21d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当年", "is_correct": true, "explanation": "正确。“当年的冬天”指很久以前的那个冬天，与前句“那年我刚上大学”呼应。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指将来，与前句“那年”所指的过去时间冲突。"}, {"text": "当天", "is_correct": false, "explanation": "搭配：“当天”指某一天，不能修饰“冬天”这样的季节。"}, {"text": "每天", "is_correct": false, "explanation": "搭配：“每天”表示日常重复，不能修饰某一个具体的冬天。"}], "explanations": {"当年": "正确。“当年的冬天”指很久以前的那个冬天，与前句“那年我刚上大学”呼应。", "明年": "语义：“明年”指将来，与前句“那年”所指的过去时间冲突。", "当天": "搭配：“当天”指某一天，不能修饰“冬天”这样的季节。", "每天": "搭配：“每天”表示日常重复，不能修饰某一个具体的冬天。"}, "sentence_index": 0, "correct_answer": "当年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我这个月很忙，当年每天都加班。", "explanation": "“当年”指过去的某一年，不能和“这个月”这样的当下时间连用。"}, {"text": "明年夏天，他当年一个人去了南方。", "explanation": "“当年”指过去，不能与“明年”这样的将来时间连用。"}, {"text": "上午十点，他当年一个人去了南方。", "explanation": "“当年”指整一年，不能指“上午十点”这样的具体时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当年", "is_correct": true, "explanation": "正确。“当年的考试”指过去某一年的考试，与“很多人都没有通过”的已发生结果相符。"}, {"text": "下周", "is_correct": false, "explanation": "语义：“下周”的考试还没有发生，不可能已经有“没有通过”的结果。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来”的考试还没有举行，不能说已经有人没通过。"}, {"text": "明年", "is_correct": false, "explanation": "时间：「明年」的考试还没有举行，不可能已经有人没有通过。"}], "explanations": {"当年": "正确。“当年的考试”指过去某一年的考试，与“很多人都没有通过”的已发生结果相符。", "下周": "语义：“下周”的考试还没有发生，不可能已经有“没有通过”的结果。", "未来": "语义：“未来”的考试还没有举行，不能说已经有人没通过。", "明年": "时间：「明年」的考试还没有举行，不可能已经有人没有通过。"}, "sentence_index": 6, "correct_answer": "当年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下个星期我们当年去爬山。", "explanation": "“当年”指过去，不能与“下个星期”这样的将来时间连用。"}, {"text": "这次比赛，我当年拿了冠军。", "explanation": "“当年”指整一年，不能指“这次比赛”这样的单次事件。"}, {"text": "一天之内，他当年去了三次医院。", "explanation": "“当年”指一整年，不能限定在“一天之内”这样的短时段中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当年了春天特别冷。", "corrected_sentence": "当年春天特别冷。", "error_description": "错误：“当年”是时间词，后面不能直接加“了”。正确：“当年春天特别冷”，“当年”指过去的某一年。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当年了下了一场大雪。", "corrected_sentence": "当年下了一场大雪。", "error_description": "错误：“当年”是时间词，后面不能直接加“了”。正确：“当年下了一场大雪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
