INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89860, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "过去某一年;那个时候。", "primary_collocate": null, "pronunciation": "dāng nián", "ipa": "taŋ˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "当年我们家很穷，一天只吃两顿饭。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当年是我们班最高的学生。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年这里没有地铁，大家都坐公共汽车。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常说，当年他走路去学校要一个小时。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当年学过画画，现在还画得很好。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年的小河现在已经看不见了。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年你说的话，我一直记得。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们当年一起住在一条小街上。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老医生当年也是从农村来的。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年没有手机，朋友们都写信。", "target_word": "当年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指过去的某个时候，常和现在对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab662d8-6e47-445d-add0-71f7968b21d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当年", "is_correct": true, "explanation": "正确。“当年”指过去某一年，与“很穷”“一天只吃两顿饭”的过去情况相符。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”指以后，与“一天只吃两顿饭”描述的过去状况冲突。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指即将到来的日子，不能用来回顾“我们家很穷”的过去生活。"}, {"text": "当天", "is_correct": false, "explanation": "搭配：“当天”指某一天，不能概括“一天只吃两顿饭”这种长期的家境状况。"}], "explanations": {"当年": "正确。“当年”指过去某一年，与“很穷”“一天只吃两顿饭”的过去情况相符。", "将来": "语义：“将来”指以后，与“一天只吃两顿饭”描述的过去状况冲突。", "明天": "语义：“明天”指即将到来的日子，不能用来回顾“我们家很穷”的过去生活。", "当天": "搭配：“当天”指某一天，不能概括“一天只吃两顿饭”这种长期的家境状况。"}, "sentence_index": 0, "correct_answer": "当年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我正在写作业，当年妈妈回来了。", "explanation": "这里应该用〈当时〉。“当年”指一整年，不能指写作业时的一个时刻；说具体时刻要用“当时”。"}, {"text": "我今年刚搬到北京，当年的生活很忙。", "explanation": "“当年”只指过去的某一年，这里却用来指说话人所在的这一年（现在），混淆了时间方向。"}, {"text": "上个星期我们去了海边，当年天气很好。", "explanation": "“当年”指整一年，不能与“上个星期”这样的一周搭配；指那一周应说“那个星期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当年", "is_correct": true, "explanation": "正确。“当年你说的话”指过去某一年说过的话，与“一直记得”相符。"}, {"text": "下周", "is_correct": false, "explanation": "语义：“下周”是将来，不能与“一直记得”这种已发生的记忆搭配。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来”还没有到来，不可能指已经说过的话。"}, {"text": "年终", "is_correct": false, "explanation": "搭配：“年终”指年末时段，不能修饰“你说的话”这样的已发生事件。"}], "explanations": {"当年": "正确。“当年你说的话”指过去某一年说过的话，与“一直记得”相符。", "下周": "语义：“下周”是将来，不能与“一直记得”这种已发生的记忆搭配。", "未来": "语义：“未来”还没有到来，不可能指已经说过的话。", "年终": "搭配：“年终”指年末时段，不能修饰“你说的话”这样的已发生事件。"}, "sentence_index": 6, "correct_answer": "当年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下个月我们当年去北京旅行。", "explanation": "“当年”指已经过去的某一年，不能和“下个月”这样的将来时间连用。"}, {"text": "刚才电话响了，当年我正在洗澡。", "explanation": "“当年”指整一年，不能用来指刚刚发生的一瞬间；这里描述的是眼前的时刻。"}, {"text": "我今天刚学会游泳，当年也学会了。", "explanation": "“当年”指过去的某一年，不能和“今天”这样的当天时间连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他当年了是北京人。", "corrected_sentence": "他当年是北京人。", "error_description": "错误：“当年”是时间词，后面不能加“了”。正确：“他当年是北京人”，“当年”指过去某一年或那个时候，不接“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当年了他们常在河边钓鱼。", "corrected_sentence": "当年他们常在河边钓鱼。", "error_description": "错误：“当年”是时间词，后面不能加“了”。正确：“当年他们常在河边钓鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
