INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89869, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在一个地方做事、帮大家的人。", "primary_collocate": null, "pronunciation": "gōng zuò rén yuán", "ipa": "kʊŋ˥ tsu̯o˥˩ ʐən˧˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "医院的工作人员很热情。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问工作人员，厕所在哪儿？", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员帮我找到了座位。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆的工作人员正在打扫。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场工作人员给老人推来轮椅。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站的工作人员告诉我怎么走。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的工作人员帮我借了书。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的工作人员把行李送到房间。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场里的工作人员穿着红衣服。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问了一位工作人员，他很耐心。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位工作人员", "label": "量词"}, {"form": "一名工作人员", "label": "量词"}, {"form": "工作人員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "车站、医院、商场等地方为大家服务、帮忙的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de9c1b0-5d2b-4ce9-8be1-a5bea4e21f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89869, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "搭配：花园不会热情，“很热情”只用于人。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：体温不能用“热情”来形容，与“很热情”搭配不当。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有情绪，不能“很热情”，“医院的石头很热情”说不通。"}, {"text": "工作人员", "is_correct": true, "explanation": "正确：医院的工作人员服务病人，可以“很热情”。"}], "explanations": {"花园": "搭配：花园不会热情，“很热情”只用于人。", "体温": "搭配：体温不能用“热情”来形容，与“很热情”搭配不当。", "石头": "语义：石头没有情绪，不能“很热情”，“医院的石头很热情”说不通。", "工作人员": "正确：医院的工作人员服务病人，可以“很热情”。"}, "sentence_index": 0, "correct_answer": "工作人员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他胸前挂着一个工作人员。", "explanation": "〈工作证〉。工作人员是人，不能挂在胸前；挂在胸前的应该是“工作证”。"}, {"text": "他把工作人员放进了包里。", "explanation": "〈文件〉。工作人员是指人的名词，不能放进包里；这里应该用“文件”。"}, {"text": "他会说三种工作人员。", "explanation": "〈语言〉。工作人员是人，不能被“说”；会说的是语言，应该说“他会说三种语言”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书架", "is_correct": false, "explanation": "语义：书架是家具，不会帮人借书。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：树木没有行为能力，不能帮我借书。"}, {"text": "工作人员", "is_correct": true, "explanation": "正确：图书馆的工作人员可以帮读者借书。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：阳光不能帮忙借书。"}], "explanations": {"书架": "语义：书架是家具，不会帮人借书。", "树木": "搭配：树木没有行为能力，不能帮我借书。", "工作人员": "正确：图书馆的工作人员可以帮读者借书。", "阳光": "搭配：阳光不能帮忙借书。"}, "sentence_index": 6, "correct_answer": "工作人员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里的工作人员生锈了。", "explanation": "〈栏杆〉。工作人员是人，不会生锈；说金属的东西生锈要用“栏杆”等物品。"}, {"text": "他把这块木头做成了工作人员。", "explanation": "〈桌子〉。工作人员是人，不能用木头做成；木头可以做成“桌子”等器物，这里应该说“做成桌子”。"}, {"text": "这次活动的结果是工作人员。", "explanation": "〈成功〉。工作人员是人，不能作为活动的结果；说活动的结果应该用“成功”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "游乐园来了一只工作人员，很热情。", "corrected_sentence": "游乐园来了一位工作人员，很热情。", "error_description": "错误：量词“只”用于动物，“工作人员”指人，应该用“位”或“名”。正确说法是“游乐园来了一位工作人员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站来了一只工作人员，主动帮我拿行李。", "corrected_sentence": "车站来了一名工作人员，主动帮我拿行李。", "error_description": "错误：量词“只”用于动物，“工作人员”指人，应该用“名”。正确说法是“车站来了一名工作人员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
