INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89870, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在机关、单位或活动中担任工作的人员。", "primary_collocate": null, "pronunciation": "gōng zuò rén yuán", "ipa": "kʊŋ˥ tsu̯o˥˩ ʐən˧˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "会议的工作人员已经到了。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛有五十名工作人员。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员在门口检查证件。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展会工作人员都戴着工作证。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府工作人员要为人民服务。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在布置会场。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的工作人员今天开会。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动结束后，工作人员收拾了场地。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这家单位的工作人员。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请出示证件给工作人员看。", "target_word": "工作人员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名工作人员", "label": "量词"}, {"form": "一位工作人员", "label": "量词"}, {"form": "工作人員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机关、单位或会议、比赛等活动里担任具体工作的人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de9c1b0-5d2b-4ce9-8be1-a5bea4e21f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病人", "is_correct": false, "explanation": "语义：病人不参加会议，“会议的病人已经到了”语义不合。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“到了”一般用于人，花朵不能“到了”会议。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会参加会议，与“会议的……已经到了”语义不合。"}, {"text": "工作人员", "is_correct": true, "explanation": "正确：会议的工作人员负责会务，可以先到场。"}], "explanations": {"病人": "语义：病人不参加会议，“会议的病人已经到了”语义不合。", "花朵": "搭配：“到了”一般用于人，花朵不能“到了”会议。", "石头": "语义：石头不会参加会议，与“会议的……已经到了”语义不合。", "工作人员": "正确：会议的工作人员负责会务，可以先到场。"}, "sentence_index": 0, "correct_answer": "工作人员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "展厅的工作人员发霉了。", "explanation": "〈墙〉。工作人员是人，不会发霉；能发霉的是墙壁等建筑材料，应该说“墙发霉了”。"}, {"text": "展览中心的工作人员今天正式开幕了。", "explanation": "〈活动〉。工作人员是人，不能“开幕”；会开幕的是活动，应该说“活动今天正式开幕”。"}, {"text": "这次比赛的结果是工作人员。", "explanation": "〈成功〉。工作人员是人，不能作为比赛的结果；说比赛的结果应该用“成功”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会去学校开会，“学校的小猫今天开会”语义不合。"}, {"text": "楼梯", "is_correct": false, "explanation": "语义：楼梯是建筑设施，不会“开会”。"}, {"text": "蔬菜", "is_correct": false, "explanation": "搭配：蔬菜不能参加开会，“蔬菜今天开会”搭配不当。"}, {"text": "工作人员", "is_correct": true, "explanation": "正确：学校的工作人员今天开会，语义和搭配都合适。"}], "explanations": {"小猫": "语义：小猫不会去学校开会，“学校的小猫今天开会”语义不合。", "楼梯": "语义：楼梯是建筑设施，不会“开会”。", "蔬菜": "搭配：蔬菜不能参加开会，“蔬菜今天开会”搭配不当。", "工作人员": "正确：学校的工作人员今天开会，语义和搭配都合适。"}, "sentence_index": 6, "correct_answer": "工作人员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请出示工作人员给大家看。", "explanation": "〈证件〉。“出示”的对象应是证件，工作人员是人，不能被出示；这里应该用“证件”。"}, {"text": "主办方要给每位来宾发放工作人员。", "explanation": "〈材料〉。“发放”的对象应是材料或资料，工作人员是人，不能发放；这里应该用“材料”。"}, {"text": "他去仓库领取了工作人员。", "explanation": "〈物资〉。工作人员是人，不能被领取；仓库里领取的是“物资”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "展会开幕那天，来了一百只工作人员。", "corrected_sentence": "展会开幕那天，来了一百名工作人员。", "error_description": "错误：量词“只”用于动物，“工作人员”指人，应该用“名”。正确说法是“来了一百名工作人员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我请了一位的工作人员帮忙。", "corrected_sentence": "我请了一位工作人员帮忙。", "error_description": "错误：数量词“一位”与名词之间不能加“的”。正确说法是“一位工作人员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
