INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89875, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人能让别人跟着他的想法去做的力量。", "primary_collocate": null, "pronunciation": "yǐng xiǎng lì", "ipa": "iŋ˨˩ ɕiɑŋ˨˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "他很有影响力，大家都愿意听他的。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师在学生中很有影响力。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好队长要有影响力，队员才会跟着他。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的影响力很大，同学们都跟她学。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李没有什么影响力，没人听他的建议。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位经理的影响力让全公司的人都愿意努力。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的老人影响力大，大家有事都找他。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要提高影响力，先要让别人相信你。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用自己的影响力，让朋友们一起做好事。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长影响力不小，同学都愿意跟着他走。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "影响", "label": "词根"}, {"form": "影響力", "label": "繁体"}], "register": "中性", "sense_fingerprint": "影响力·个人让别人听从、跟随的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60858867-7847-4d7c-829e-2ea7a1da46c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "影响力", "is_correct": true, "explanation": "正确。“很有影响力”指能让别人听从的能力，与“大家都愿意听他的”相符。"}, {"text": "汗水", "is_correct": false, "explanation": "搭配：“很有”后不接“汗水”，且与人际作用无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“很有”后接抽象的性质或能力，不接“体重”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“很有”后接抽象的性质或能力，不说“很有年龄”。"}], "explanations": {"影响力": "正确。“很有影响力”指能让别人听从的能力，与“大家都愿意听他的”相符。", "汗水": "搭配：“很有”后不接“汗水”，且与人际作用无关。", "体重": "搭配：“很有”后接抽象的性质或能力，不接“体重”。", "年龄": "搭配：“很有”后接抽象的性质或能力，不说“很有年龄”。"}, "sentence_index": 0, "correct_answer": "影响力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药对病人的身体有很好的影响力。", "explanation": "这里应该用〈作用〉。影响力指一个人让别人跟随的力量，药物对身体的效果要说“作用”。"}, {"text": "这颗炸弹的影响力很大，一下炸平了整栋楼。", "explanation": "这里应该用〈威力〉。影响力用于人对他人想法、行为的作用，炸弹的破坏力要说“威力”。"}, {"text": "他每天工作十个小时，影响力依然很旺盛。", "explanation": "这里应该用〈精力〉。影响力不指身体的能量，“精力旺盛”才是常用说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影响力", "is_correct": true, "explanation": "正确。“村里的老人影响力大”指老人能让村民听从、跟随，与“大家有事都找他”相符。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”一般说“好”或“强”，不说“性格大”。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：“脚印”指踩出的痕迹，与“大家有事都找他”无关。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”指装书的袋子，与“大家有事都找他”没有关系。"}], "explanations": {"影响力": "正确。“村里的老人影响力大”指老人能让村民听从、跟随，与“大家有事都找他”相符。", "性格": "搭配：“性格”一般说“好”或“强”，不说“性格大”。", "脚印": "语义：“脚印”指踩出的痕迹，与“大家有事都找他”无关。", "书包": "语义：“书包”指装书的袋子，与“大家有事都找他”没有关系。"}, "sentence_index": 6, "correct_answer": "影响力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位队员跑完全程，影响力还很好。", "explanation": "这里应该用〈体力〉。影响力指让别人跟随的力量，身体的力气要说“体力”。"}, {"text": "这位同学的影响力很好，能看清远处的字。", "explanation": "这里应该用〈视力〉。影响力指让别人跟随的力量，眼睛看清东西的能力要说“视力”。"}, {"text": "这个孩子的影响力很高，一学就会。", "explanation": "这里应该用〈智力〉。影响力指让别人跟随的力量，学习理解的能力要说“智力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在公司里有一条很大的影响力。", "corrected_sentence": "他在公司里有一种很大的影响力。", "error_description": "错误形式“一条影响力”，正确应为“一种影响力”。影响力是抽象名词，量词用“种”，“条”多用于河流、裤子等细长物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师有很影响力，学生们都愿意听他讲。", "corrected_sentence": "这位老师很有影响力，学生们都愿意听他讲。", "error_description": "错误形式“有很影响力”，正确应为“很有影响力”。“很”修饰的是“有影响力”，要放在“有”的前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
