INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对他人的思想或行为产生作用的能力。", "primary_collocate": null, "pronunciation": "yǐng xiǎng lì", "ipa": "iŋ˨˩ ɕiɑŋ˨˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "这位歌手的影响力很大，很多年轻人学他穿衣。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络的影响力越来越大，人们的想法也变了。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的影响力很大，很多人看了以后改变了想法。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视广告有很强的影响力，能让人买东西。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名人的影响力不小，他们说的话粉丝都当真。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在报纸的影响力比以前小多了。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母的影响力会改变孩子的行为。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新闻的影响力很大，很多人都改变了做法。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师的影响力，会让学生变得更努力。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个明星的影响力让很多人开始爱运动。", "target_word": "影响力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "影响", "label": "词根"}, {"form": "影響力", "label": "繁体"}], "register": "中性", "sense_fingerprint": "影响力·人或事物改变他人想法、行为的作用能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60858867-7847-4d7c-829e-2ea7a1da46c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "影响力", "is_correct": true, "explanation": "正确。“这位歌手的影响力很大”指他能让别人效仿，与“很多年轻人学他穿衣”相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高属于外形特征，不能说它让年轻人学穿衣。"}, {"text": "步伐", "is_correct": false, "explanation": "语义：“步伐”指走路的步子，与“学他穿衣”无关。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重属于外形体征，不能说它让年轻人学穿衣。"}], "explanations": {"影响力": "正确。“这位歌手的影响力很大”指他能让别人效仿，与“很多年轻人学他穿衣”相符。", "身高": "体貌：身高属于外形特征，不能说它让年轻人学穿衣。", "步伐": "语义：“步伐”指走路的步子，与“学他穿衣”无关。", "体重": "体貌：体重属于外形体征，不能说它让年轻人学穿衣。"}, "sentence_index": 0, "correct_answer": "影响力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位工人干了一整天活，影响力还很好。", "explanation": "这里应该用〈体力〉。影响力指对他人思想或行为的作用，身体的力量要说“体力”。"}, {"text": "这枚导弹的影响力很强，一下就炸毁了整座桥。", "explanation": "这里应该用〈威力〉。影响力用于人或想法的作用，导弹的破坏力要说“威力”。"}, {"text": "她每天跑步五公里，影响力依然很充沛。", "explanation": "这里应该用〈精力〉。影响力不指身体的能量，“精力充沛”才是常用说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影响力", "is_correct": true, "explanation": "正确。“父母的影响力会改变孩子的行为”指父母能让孩子受到作用，与句意相符。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：眼睛属于外形特征，不能说它会改变孩子的行为。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，父母的颜色不会改变孩子的行为。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：发型属于外形特征，不能说它会改变孩子的行为。"}], "explanations": {"影响力": "正确。“父母的影响力会改变孩子的行为”指父母能让孩子受到作用，与句意相符。", "眼睛": "体貌：眼睛属于外形特征，不能说它会改变孩子的行为。", "颜色": "语义：“颜色”指色彩，父母的颜色不会改变孩子的行为。", "发型": "体貌：发型属于外形特征，不能说它会改变孩子的行为。"}, "sentence_index": 6, "correct_answer": "影响力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人的影响力很好，能看清远处的字。", "explanation": "这里应该用〈视力〉。影响力指对他人思想或行为的作用，眼睛看清东西的能力要说“视力”。"}, {"text": "这个学生的影响力很高，每次考试都是第一名。", "explanation": "这里应该用〈智力〉。影响力指对他人思想或行为的作用，学习理解的能力要说“智力”。"}, {"text": "这家公司的影响力很富裕，能投资很多项目。", "explanation": "这里应该用〈财力〉。影响力指对他人思想或行为的作用，资金实力要说“财力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本杂志在年轻人中有一条很大的影响力。", "corrected_sentence": "这本杂志在年轻人中有一种很大的影响力。", "error_description": "错误形式“一条影响力”，正确应为“一种影响力”。影响力是抽象名词，量词用“种”，“条”多用于河流、裤子等细长物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目有很影响力，很多人都开始关注教育问题。", "corrected_sentence": "这个节目很有影响力，很多人都开始关注教育问题。", "error_description": "错误形式“有很影响力”，正确应为“很有影响力”。“很”要放在“有影响力”之前，不能插在“有”和“影响力”中间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
