INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89877, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "课程是学校里要上的课。", "primary_collocate": null, "pronunciation": "kè chéng", "ipa": "kʰɤ˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这学期的课程很多,我每天都很忙。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今年报了一门汉语课程。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课程老师讲得很清楚。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都在网上学习英语课程。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个课程每周只有两节课。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这些课程对工作很有用。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天开始新课程,我有点儿紧张。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他选了三门课程,星期五没有课。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了这学期的课程。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学完这门课程以后,我就能看懂中文新闻了。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "门", "label": "量词"}, {"form": "課程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学生要上的课,日常学习中的一门门课", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c16745d-ee73-4b44-8e65-a27eab05b8e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89877, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "课程", "is_correct": true, "explanation": "正确答案。听到的是“课程”kè chéng，指学生要上的课。"}, {"text": "客场", "is_correct": false, "explanation": "chǎng（第三声）与 chéng（第二声）韵母和声调都不同，意思是客场（比赛在对方场地进行）。"}, {"text": "合成", "is_correct": false, "explanation": "hé（第二声）与 kè（第四声）声母和声调不同，意思是合成。"}, {"text": "可乘", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，意思是可以利用的（如“可乘之机”）。"}, {"text": "折成", "is_correct": false, "explanation": "zhé（第二声）与 kè（第四声）声母和声调不同，意思是折成（如“折成两半”）。"}], "explanations": {"课程": "正确答案。听到的是“课程”kè chéng，指学生要上的课。", "客场": "chǎng（第三声）与 chéng（第二声）韵母和声调都不同，意思是客场（比赛在对方场地进行）。", "合成": "hé（第二声）与 kè（第四声）声母和声调不同，意思是合成。", "可乘": "kě（第三声）与 kè（第四声）声调不同，意思是可以利用的（如“可乘之机”）。", "折成": "zhé（第二声）与 kè（第四声）声母和声调不同，意思是折成（如“折成两半”）。"}, "sentence_index": null, "correct_answer": "课程"}, "level_3": {"options": [{"text": "课程", "is_correct": true, "explanation": "正确答案。“这学期的课程”指学生要上的各门课，与“很多”和“很忙”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：学期指学校的学习时段，天气与学期的学习内容无关，“这学期的天气很多”说不通。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是空间，不是学期里可以数的内容，“这学期的房间很多”不成立。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气是不可数的物质，不能说“这学期的空气很多”。"}], "explanations": {"课程": "正确答案。“这学期的课程”指学生要上的各门课，与“很多”和“很忙”相符。", "天气": "语义：学期指学校的学习时段，天气与学期的学习内容无关，“这学期的天气很多”说不通。", "房间": "语义：房间是空间，不是学期里可以数的内容，“这学期的房间很多”不成立。", "空气": "搭配：空气是不可数的物质，不能说“这学期的空气很多”。"}, "sentence_index": 0, "correct_answer": "课程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天上一节课程。", "explanation": "这里应该用〈门〉。课程按“门”计算，“节”指一次课的时段，不能说“一节课程”。"}, {"text": "开学第一天，老师给我们倒了一杯新课程。", "explanation": "这里应该用〈茶〉。课程是学科和教学安排，不能倒出来喝；倒出来的是茶。"}, {"text": "老师今天布置了很多课程。", "explanation": "这里应该用〈作业〉。布置的是要完成的题目，“课程”是要上的学科，不能布置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课程", "is_correct": true, "explanation": "正确答案。“明天开始新课程”是开学的新课，与“有点儿紧张”相符。"}, {"text": "雨", "is_correct": false, "explanation": "语义：句中说的是要开始的学习安排，雨不是学习内容，“明天开始新雨”与“有点儿紧张”的语境不符。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“开始”后面接的是学习或工作等事项，不接“新椅子”。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不能作为“开始”的对象，句子说不通。"}], "explanations": {"课程": "正确答案。“明天开始新课程”是开学的新课，与“有点儿紧张”相符。", "雨": "语义：句中说的是要开始的学习安排，雨不是学习内容，“明天开始新雨”与“有点儿紧张”的语境不符。", "椅子": "搭配：“开始”后面接的是学习或工作等事项，不接“新椅子”。", "水果": "语义：水果是食物，不能作为“开始”的对象，句子说不通。"}, "sentence_index": 6, "correct_answer": "课程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师想尽快解决这门课程。", "explanation": "这里应该用〈课题〉。解决的是问题或课题，课程是学生要学的学科，不能被解决。"}, {"text": "我们家搬到了课程附近。", "explanation": "这里应该用〈学校〉。课程是学科安排，不是地方，不能搬到它附近。"}, {"text": "我把这门课程借给了图书馆。", "explanation": "这里应该用〈书〉。借出的是书籍，课程不能借给图书馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今年选了两节课程。", "corrected_sentence": "我今年选了两门课程。", "error_description": "量词错误：“课程”应搭配量词“门”，不用“节”。错误形式是“两节课程”，正确形式是“两门课程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这学期我选了两门课程们。", "corrected_sentence": "这学期我选了两门课程。", "error_description": "词缀错误：“们”只用于指人的名词，不能加在“课程”后面。错误形式是“两门课程们”，正确形式是“两门课程”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
