INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89887, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一整天都这样，天天这样。", "primary_collocate": null, "pronunciation": "chéng rì", "ipa": "ʈʂʰɤŋ˧˥ ʐɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他成日坐在电脑前，眼睛很累。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟成日想着玩，不爱写作业。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈成日在厨房忙来忙去。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她成日笑着，好像没有烦恼。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么成日躺在沙发上看手机？", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫成日睡觉，只在吃饭时醒来。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷成日在公园下棋，天黑才回家。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成日说要减肥，却一直吃蛋糕。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天成日下雨，衣服都干不了。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板成日开会，我们很少见到他。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "整天、天天都这样，常带抱怨的口气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e9126ca-4af1-43ae-8d7f-a545c9374384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89887, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成日", "is_correct": true, "explanation": "正确答案：成日 chéng rì，一整天都这样，天天这样。"}, {"text": "城市", "is_correct": false, "explanation": "shì 与 rì 声母不同（sh 与 r），声调相同，意思是城市。"}, {"text": "成立", "is_correct": false, "explanation": "lì 与 rì 声母不同（l 与 r），意思是成立。"}, {"text": "生日", "is_correct": false, "explanation": "shēng（第一声）与 chéng（第二声）声母和声调都不同，意思是生日。"}, {"text": "成绩", "is_correct": false, "explanation": "jì 与 rì 声母不同（j 与 r），意思是成绩。"}], "explanations": {"成日": "正确答案：成日 chéng rì，一整天都这样，天天这样。", "城市": "shì 与 rì 声母不同（sh 与 r），声调相同，意思是城市。", "成立": "lì 与 rì 声母不同（l 与 r），意思是成立。", "生日": "shēng（第一声）与 chéng（第二声）声母和声调都不同，意思是生日。", "成绩": "jì 与 rì 声母不同（j 与 r），意思是成绩。"}, "sentence_index": null, "correct_answer": "成日"}, "level_3": {"options": [{"text": "成日", "is_correct": true, "explanation": "成日：整天、天天都这样，与“坐在电脑前，眼睛很累”所说的长时间用眼相合。"}, {"text": "很", "is_correct": false, "explanation": "词性：“很”一般修饰形容词，不直接修饰“坐”这类动作动词，句子不通。"}, {"text": "马上", "is_correct": false, "explanation": "语义：马上表示即将发生，而句子描述的是持续的状态，意思不合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：立刻指紧接着发生，与“眼睛很累”的长时间状态相矛盾。"}], "explanations": {"成日": "成日：整天、天天都这样，与“坐在电脑前，眼睛很累”所说的长时间用眼相合。", "很": "词性：“很”一般修饰形容词，不直接修饰“坐”这类动作动词，句子不通。", "马上": "语义：马上表示即将发生，而句子描述的是持续的状态，意思不合。", "立刻": "语义：立刻指紧接着发生，与“眼睛很累”的长时间状态相矛盾。"}, "sentence_index": 0, "correct_answer": "成日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这周我成日请假了一天。", "explanation": "这里误把〈成日〉当作〈个别的日子〉。“成日”指天天、整天都这样，不能只指某一天。"}, {"text": "他偶尔成日去健身房。", "explanation": "这里应该用〈经常〉。“成日”指整天、天天不断，不能与表示次数很少的副词同用，语义自相矛盾。"}, {"text": "我成日看了一个小时的书。", "explanation": "这里误把〈成日〉当作〈很久〉。“成日”指整天、天天不断，不能与“一个小时”这样的短时段搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89887, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成日", "is_correct": true, "explanation": "正确答案：成日 chéng rì，一整天都这样，天天这样。"}, {"text": "成事", "is_correct": false, "explanation": "shì 与 rì 声母不同（sh 与 r），声调相同，意思是成事。"}, {"text": "乘机", "is_correct": false, "explanation": "jī（第一声）与 rì（第四声）声母和声调都不同，意思是乘机。"}, {"text": "城里", "is_correct": false, "explanation": "lǐ（第三声）与 rì（第四声）声母和声调都不同，意思是城里。"}, {"text": "诚实", "is_correct": false, "explanation": "shí（第二声）与 rì（第四声）声母和声调都不同，意思是诚实。"}], "explanations": {"成日": "正确答案：成日 chéng rì，一整天都这样，天天这样。", "成事": "shì 与 rì 声母不同（sh 与 r），声调相同，意思是成事。", "乘机": "jī（第一声）与 rì（第四声）声母和声调都不同，意思是乘机。", "城里": "lǐ（第三声）与 rì（第四声）声母和声调都不同，意思是城里。", "诚实": "shí（第二声）与 rì（第四声）声母和声调都不同，意思是诚实。"}, "sentence_index": null, "correct_answer": "成日"}, "level_3": {"options": [{"text": "成日", "is_correct": true, "explanation": "成日：整天、天天都这样，与“在公园下棋，天黑才回家”的整日活动相合。"}, {"text": "刚", "is_correct": false, "explanation": "体貌：刚表示动作刚发生，与“天黑才回家”所说的整日活动不合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：忽然指突然发生，与整日、长期在公园下棋的习惯不合。"}, {"text": "终于", "is_correct": false, "explanation": "语义：终于表示经过等待后才实现，与句中的日常习惯不合。"}], "explanations": {"成日": "成日：整天、天天都这样，与“在公园下棋，天黑才回家”的整日活动相合。", "刚": "体貌：刚表示动作刚发生，与“天黑才回家”所说的整日活动不合。", "忽然": "语义：忽然指突然发生，与整日、长期在公园下棋的习惯不合。", "终于": "语义：终于表示经过等待后才实现，与句中的日常习惯不合。"}, "sentence_index": 6, "correct_answer": "成日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他成日来我家做过一次客。", "explanation": "这里误把〈成日〉当作〈偶然〉。“成日”强调天天、整天都这样，不能与只发生一次的“做过一次客”搭配。"}, {"text": "他成日第一次来中国。", "explanation": "这里误把〈成日〉当作〈首次〉。“成日”指天天、整天都这样，不能修饰只发生一次的“第一次来中国”。"}, {"text": "那个孩子成日出生在春天。", "explanation": "这里误把〈成日〉当作〈经常〉。“出生”是一次性发生的动作，不能用表示天天持续的“成日”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸成日的在工厂里上班。", "corrected_sentence": "爸爸成日在工厂里上班。", "error_description": "“成日”是副词，后面不能加“的”。应说“爸爸成日在工厂里上班”，去掉“成日”后多出的“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷很成日在公园里散步，天黑才回家。", "corrected_sentence": "爷爷成日在公园里散步，天黑才回家。", "error_description": "“很”不能修饰副词“成日”，应删去“很”，写作“爷爷成日在公园里散步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2eae7f5-f92d-427c-8c1d-97c798e6227b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
