INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89901, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "首次是第一回做某件事。", "primary_collocate": null, "pronunciation": "shǒu cì", "ipa": "ʂoʊ˨˩˦ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "昨天我首次去医院看病。", "target_word": "首次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她首次坐飞机，有点儿怕。", "target_word": "首次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们首次见面。", "target_word": "首次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥首次拿到工资。", "target_word": "首次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他首次说出了自己的想法。", "target_word": "首次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班首次去公园玩。", "target_word": "首次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟首次骑自行车上路。", "target_word": "首次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我首次吃到这么好吃的饭。", "target_word": "首次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师首次来我家做客。", "target_word": "首次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹首次自己做饭。", "target_word": "首次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "首次:第一回做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab662d8-6e47-445d-add0-71f7968b21d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89901, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "首次", "is_correct": true, "explanation": "正确答案：首次（shǒu cì），表示第一回做某件事。"}, {"text": "手册", "is_correct": false, "explanation": "cè（第四声）与 cì（第四声）韵母不同，意思是手册。"}, {"text": "首字", "is_correct": false, "explanation": "zì（第四声）与 cì（第四声）声母不同（z 与 c），意思是第一个字。"}, {"text": "首席", "is_correct": false, "explanation": "xí（第二声）与 cì（第四声）声母和声调都不同，意思是首席。"}], "explanations": {"首次": "正确答案：首次（shǒu cì），表示第一回做某件事。", "手册": "cè（第四声）与 cì（第四声）韵母不同，意思是手册。", "首字": "zì（第四声）与 cì（第四声）声母不同（z 与 c），意思是第一个字。", "首席": "xí（第二声）与 cì（第四声）声母和声调都不同，意思是首席。"}, "sentence_index": null, "correct_answer": "首次"}, "level_3": {"options": [{"text": "从来", "is_correct": false, "explanation": "搭配：「从来」多与否定词连用，「昨天我从来去医院看病」不通。"}, {"text": "必", "is_correct": false, "explanation": "语义：「必」表示一定、必定，「昨天我必去医院看病」与已发生的时间不合，语义不通。"}, {"text": "首次", "is_correct": true, "explanation": "“首次”作副词，表示昨天第一次去医院看病，句子通顺。"}, {"text": "永远", "is_correct": false, "explanation": "语义：「永远」表示长久，与「昨天」这一具体时间冲突。"}], "explanations": {"从来": "搭配：「从来」多与否定词连用，「昨天我从来去医院看病」不通。", "必": "语义：「必」表示一定、必定，「昨天我必去医院看病」与已发生的时间不合，语义不通。", "首次": "“首次”作副词，表示昨天第一次去医院看病，句子通顺。", "永远": "语义：「永远」表示长久，与「昨天」这一具体时间冲突。"}, "sentence_index": 0, "correct_answer": "首次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "首次，哥哥要做好准备工作。", "explanation": "这里应该用〈首先〉。「首先」表示先后顺序，用于引出步骤；「首次」只表示第一次做某事，不能这样用。"}, {"text": "哥哥首次总是拿到工资。", "explanation": "「首次」表示第一次，与「总是」表示一贯如此的意思矛盾，两者不能同用。"}, {"text": "哥哥每个月首次拿到工资。", "explanation": "「首次」表示第一次，不能与「每个月」这类表示周期反复的词连用，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "猛", "is_correct": false, "explanation": "搭配：「猛」多修饰动作，表示用力或突然，「弟弟猛骑自行车上路」不自然。"}, {"text": "忽", "is_correct": false, "explanation": "语义：「忽」表示突然，与「首次」所指的第一次及其动作过程不合，「弟弟忽骑自行车上路」语义不通。"}, {"text": "首次", "is_correct": true, "explanation": "“首次”作副词，表示弟弟第一次骑自行车上路，句子通顺。"}, {"text": "微", "is_correct": false, "explanation": "搭配：「微」多修饰「小、弱」等，不说「微骑」。"}], "explanations": {"猛": "搭配：「猛」多修饰动作，表示用力或突然，「弟弟猛骑自行车上路」不自然。", "忽": "语义：「忽」表示突然，与「首次」所指的第一次及其动作过程不合，「弟弟忽骑自行车上路」语义不通。", "首次": "“首次”作副词，表示弟弟第一次骑自行车上路，句子通顺。", "微": "搭配：「微」多修饰「小、弱」等，不说「微骑」。"}, "sentence_index": 6, "correct_answer": "首次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹妹经常首次自己做饭。", "explanation": "「经常」表示反复，与「首次」表示的第一次矛盾，两者不能同用。"}, {"text": "妹妹一直首次自己做饭。", "explanation": "「一直」表示持续，与「首次」表示一次性的第一次矛盾。"}, {"text": "妹妹不曾首次自己做饭。", "explanation": "「首次」表示第一次，而「不曾」表示从未有过，两者语义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班第一次首次去了动物园。", "corrected_sentence": "我们班首次去了动物园。", "error_description": "错误形式：「第一次首次」；正确形式：「首次」。「首次」已含“第一次”的意思，不能重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
