INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89918, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧", "is_correct": true, "explanation": "正确。“紧”与“松”是反义词，指不松散、结实。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”指光线充足或明亮，与“不紧”无关。"}, {"text": "圆", "is_correct": false, "explanation": "“圆”指形状像圆圈，与“不紧”无关。"}, {"text": "深", "is_correct": false, "explanation": "“深”指距离表面远，与“不紧”无关。"}], "correct_answer": "紧", "explanations": {"紧": "正确。“紧”与“松”是反义词，指不松散、结实。", "亮": "“亮”指光线充足或明亮，与“不紧”无关。", "圆": "“圆”指形状像圆圈，与“不紧”无关。", "深": "“深”指距离表面远，与“不紧”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
