INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89918, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不紧；不紧密。", "primary_collocate": null, "pronunciation": "sōng", "ipa": "sʊŋ˥", "syllable_count": 1, "sentences": [{"text": "这块地的土很松，种花很容易。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件毛衣织得太松，冬天穿不暖。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把行李包得太松，里面的东西乱动。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布织得很松，能看到后面的东西。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪刚下过，地上的雪很松，一脚踩下去很深。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子里的东西放得太松，还可以再放一些。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的头发编得有点松，看起来很轻。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕很松，口感很好。", "target_word": "松", "complexity_tier": "T3", "furigana": "zhè gè dàngāo hěn sōng, kǒugǎn hěn hǎo.", "sentence_source": "generated"}, {"text": "这床棉被的棉花很松，盖起来很暖和。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子太松了，房子不能盖在上面。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "松了", "label": "体标"}, {"form": "松松的", "label": "重叠"}, {"form": "松软", "label": "复合词"}, {"form": "鬆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "松·形容词·质地、结构不紧密", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60858867-7847-4d7c-829e-2ea7a1da46c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89918, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "松", "is_correct": true, "explanation": "正确。松，sōng，意思是不紧。"}, {"text": "送", "is_correct": false, "explanation": "sòng（第四声）与 sōng（第一声）声调不同，意思是送。"}, {"text": "葱", "is_correct": false, "explanation": "cōng 与 sōng 声母不同（c 与 s），意思是葱。"}, {"text": "桑", "is_correct": false, "explanation": "sāng 与 sōng 韵母不同（a 与 o），意思是桑树。"}, {"text": "搜", "is_correct": false, "explanation": "sōu 与 sōng 韵尾不同（u 与 ng），意思是搜索。"}], "explanations": {"松": "正确。松，sōng，意思是不紧。", "送": "sòng（第四声）与 sōng（第一声）声调不同，意思是送。", "葱": "cōng 与 sōng 声母不同（c 与 s），意思是葱。", "桑": "sāng 与 sōng 韵母不同（a 与 o），意思是桑树。", "搜": "sōu 与 sōng 韵尾不同（u 与 ng），意思是搜索。"}, "sentence_index": null, "correct_answer": "松"}, "level_3": {"options": [{"text": "松", "is_correct": true, "explanation": "正确。“这块地的土很松，种花很容易”中，“松”指土质不紧实，便于种花。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”指质地坚实，与“种花很容易”矛盾。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”说价格，不说土的质地。"}, {"text": "紧", "is_correct": false, "explanation": "语义：“紧”指板结、密实，同样不利于种花，与“种花很容易”矛盾。"}], "explanations": {"松": "正确。“这块地的土很松，种花很容易”中，“松”指土质不紧实，便于种花。", "硬": "语义：“硬”指质地坚实，与“种花很容易”矛盾。", "贵": "搭配：“贵”说价格，不说土的质地。", "紧": "语义：“紧”指板结、密实，同样不利于种花，与“种花很容易”矛盾。"}, "sentence_index": 0, "correct_answer": "松"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子很松，我一个人能抬起来。", "explanation": "这里应该用〈轻〉。松指结构不紧，说重量小要用“轻”。"}, {"text": "他的动作很松，大家都在等他。", "explanation": "这里应该用〈慢〉。松不用来形容速度，动作慢要用“慢”。"}, {"text": "这条路很松，两辆车能并排走。", "explanation": "这里应该用〈宽〉。松指不紧，说路面的宽窄要用“宽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "松", "is_correct": true, "explanation": "正确。“她的头发编得有点松，看起来很轻”中，“松”指编得不紧。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”指分量大，与“看起来很轻”矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“编”后不接“亮”，不说“编得有点亮”。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”会让人觉得分量大，与“看起来很轻”矛盾。"}], "explanations": {"松": "正确。“她的头发编得有点松，看起来很轻”中，“松”指编得不紧。", "重": "语义：“重”指分量大，与“看起来很轻”矛盾。", "亮": "搭配：“编”后不接“亮”，不说“编得有点亮”。", "厚": "语义：“厚”会让人觉得分量大，与“看起来很轻”矛盾。"}, "sentence_index": 6, "correct_answer": "松"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小区很松，夜里大家都睡得很早。", "explanation": "这里应该用〈安静〉。松表示不紧，说环境清静、没有噪音要用“安静”。"}, {"text": "这辆车开得很松，一下就超过了大家。", "explanation": "这里应该用〈快〉。松表示不紧，说车速快要用“快”。"}, {"text": "这间屋子很松，大家都热得出汗。", "explanation": "这里应该用〈热〉。松表示不紧，说屋里温度高要用“热”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这床被子松很，盖着不暖和。", "corrected_sentence": "这床被子很松，盖着不暖和。", "error_description": "错误形式“松很”，正确应为“很松”。形容词作谓语时，程度副词“很”要放在形容词之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把围巾织很松，戴起来很暖和。", "corrected_sentence": "她把围巾织得很松，戴起来很暖和。", "error_description": "错误形式“织很松”，正确应为“织得很松”。动词后带程度补语时要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
