INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89925, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有图案、有字的一小块硬片，可以挂起来或拿来玩。", "primary_collocate": null, "pronunciation": "pái", "ipa": "pʰai˧˥", "syllable_count": 1, "sentences": [{"text": "他们坐在桌旁打牌。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的牌不好，这一局会输。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先洗牌，再发给大家。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里有一张红色的牌。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这副牌少了一张。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，爷爷喜欢和朋友玩牌。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮到我出牌了。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在地上摆了很多牌。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把牌放在桌子中间。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脖子上挂着一块牌，上面有名字。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "副", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "扑克牌", "label": "复合"}], "register": "中性", "sense_fingerprint": "牌：带图案或字的小硬片，如扑克牌，也指挂在身上的牌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf08968a-b4cb-4d8f-9f5e-355294b2811a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89925, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "牌", "is_correct": true, "explanation": "正确。牌（pái）：有图案或字的一小块硬片。"}, {"text": "拍", "is_correct": false, "explanation": "pāi（第一声）与 pái（第二声）声调不同，意思是拍打。"}, {"text": "派", "is_correct": false, "explanation": "pài（第四声）与 pái（第二声）声调不同，意思是派别或派遣。"}, {"text": "白", "is_correct": false, "explanation": "bái 与 pái 声母不同（b 与 p），意思是白色。"}, {"text": "盘", "is_correct": false, "explanation": "pán 与 pái 韵母不同（an 与 ai），意思是盘子。"}, {"text": "台", "is_correct": false, "explanation": "tái 与 pái 声母不同（t 与 p），意思是台子。"}], "explanations": {"牌": "正确。牌（pái）：有图案或字的一小块硬片。", "拍": "pāi（第一声）与 pái（第二声）声调不同，意思是拍打。", "派": "pài（第四声）与 pái（第二声）声调不同，意思是派别或派遣。", "白": "bái 与 pái 声母不同（b 与 p），意思是白色。", "盘": "pán 与 pái 韵母不同（an 与 ai），意思是盘子。", "台": "tái 与 pái 声母不同（t 与 p），意思是台子。"}, "sentence_index": null, "correct_answer": "牌"}, "level_3": {"options": [{"text": "牌", "is_correct": true, "explanation": "正确。牌：扑克牌，“打牌”表示玩牌游戏。"}, {"text": "雷", "is_correct": false, "explanation": "语义：「雷」指自然现象，与“坐在桌旁”的室内打牌场景不合。"}, {"text": "针", "is_correct": false, "explanation": "搭配：「打针」的搭配对象是医疗注射，不能用于“桌旁”的娱乐场景。"}, {"text": "巴掌", "is_correct": false, "explanation": "语义：「打巴掌」指打人，与打牌的娱乐语境不合。"}], "explanations": {"牌": "正确。牌：扑克牌，“打牌”表示玩牌游戏。", "雷": "语义：「雷」指自然现象，与“坐在桌旁”的室内打牌场景不合。", "针": "搭配：「打针」的搭配对象是医疗注射，不能用于“桌旁”的娱乐场景。", "巴掌": "语义：「打巴掌」指打人，与打牌的娱乐语境不合。"}, "sentence_index": 0, "correct_answer": "牌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他手里有一只红色的牌。", "explanation": "这里应该用〈张〉。“只”用于动物等，“牌”应用“张”计量。"}, {"text": "他钱包里有一张银行牌。", "explanation": "这里应该用〈卡〉。“牌”指有图案或字的硬片，不指银行卡。"}, {"text": "他掏出一张牌付了钱。", "explanation": "这里应该用〈钞票〉或〈纸币〉。“牌”指有图案或字的硬片，不指纸币。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89925, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "牌", "is_correct": true, "explanation": "正确。牌（pái）：有图案或字的一小块硬片。"}, {"text": "才", "is_correct": false, "explanation": "cái 与 pái 声母不同（c 与 p），意思是才能或刚刚。"}, {"text": "来", "is_correct": false, "explanation": "lái 与 pái 声母不同（l 与 p），意思是来到。"}, {"text": "埋", "is_correct": false, "explanation": "mái 与 pái 声母不同（m 与 p），意思是埋藏。"}, {"text": "孩", "is_correct": false, "explanation": "hái 与 pái 声母不同（h 与 p），意思是孩子。"}], "explanations": {"牌": "正确。牌（pái）：有图案或字的一小块硬片。", "才": "cái 与 pái 声母不同（c 与 p），意思是才能或刚刚。", "来": "lái 与 pái 声母不同（l 与 p），意思是来到。", "埋": "mái 与 pái 声母不同（m 与 p），意思是埋藏。", "孩": "hái 与 pái 声母不同（h 与 p），意思是孩子。"}, "sentence_index": null, "correct_answer": "牌"}, "level_3": {"options": [{"text": "牌", "is_correct": true, "explanation": "正确。牌：可用于出牌游戏的硬片，与“轮到我出……了”的语境相合。"}, {"text": "汗", "is_correct": false, "explanation": "语义：「出汗」指身体排汗，与“轮到我”出牌的游戏语境不合。"}, {"text": "血", "is_correct": false, "explanation": "语义：「出血」指受伤流血，与出牌游戏的语境不合。"}, {"text": "疹子", "is_correct": false, "explanation": "搭配：「出疹子」的搭配对象是皮肤病，与“出牌”的游戏语境不协调。"}], "explanations": {"牌": "正确。牌：可用于出牌游戏的硬片，与“轮到我出……了”的语境相合。", "汗": "语义：「出汗」指身体排汗，与“轮到我”出牌的游戏语境不合。", "血": "语义：「出血」指受伤流血，与出牌游戏的语境不合。", "疹子": "搭配：「出疹子」的搭配对象是皮肤病，与“出牌”的游戏语境不协调。"}, "sentence_index": 6, "correct_answer": "牌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他脖子上挂着一本牌，上面有名字。", "explanation": "这里应该用〈块〉或〈张〉。“本”用于书籍，不用于“牌”。"}, {"text": "他看了一眼手上的牌，已经十点了。", "explanation": "这里应该用〈手表〉。“牌”指有图案或字的硬片，不指看时间的手表。"}, {"text": "他拿到了一块牌，吃起来很甜。", "explanation": "这里应该用〈蛋糕〉。“牌”是有图案或字的硬片，挂起来或拿来玩，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师拿了一只牌放在桌上。", "corrected_sentence": "老师拿了一张牌放在桌上。", "error_description": "“牌”的量词用错。“只”用于动物等，“牌”应用“张”，正确形式是“一张牌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上摆着很多牌们。", "corrected_sentence": "桌上摆着很多牌。", "error_description": "“们”只用于指人，不能加在“牌”后，正确形式是“很多牌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
