INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89929, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "我们用的各种东西。", "primary_collocate": null, "pronunciation": "wù pǐn", "ipa": "u˥˩ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "请带好自己的物品，再下车。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些物品都是我们家常用的。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贵重物品请放在柜子里。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把物品一件一件放进箱子。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以前，我先整理了物品。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场不让带危险物品上飞机。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宾馆可以帮客人保管物品。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在地铁里丢了一些物品。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给新来的同事发了办公物品。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门旅行要带的物品很多。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "样", "label": "量词"}], "register": "中性", "sense_fingerprint": "物品：我们使用的各种东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7424e-dd54-40b2-af10-b5c6420f3f6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是可以带着下车的东西。"}, {"text": "物品", "is_correct": true, "explanation": "正确。“带好”“下车”的对象是随身携带的东西，物品最合适。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法被拿起来随身带着下车。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，无法随身带着下车。"}], "explanations": {"天气": "语义：天气是气象状况，不是可以带着下车的东西。", "物品": "正确。“带好”“下车”的对象是随身携带的东西，物品最合适。", "空气": "语义：空气无法被拿起来随身带着下车。", "房子": "语义：房子是建筑，无法随身带着下车。"}, "sentence_index": 0, "correct_answer": "物品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一只物品回家。", "explanation": "这里应该用〈件〉。物品是泛指的东西，不用“只”计量，“只”多用于动物、鞋袜等。"}, {"text": "这个想法是一件很重要的物品。", "explanation": "物品指看得见、摸得着、用来使用或保管的东西，不能用来指想法这类抽象概念。"}, {"text": "昨天的物品非常精彩。", "explanation": "这里应该用〈比赛〉。比赛指体育或竞技活动，物品指人们使用或买卖的东西，不能用来指一场竞赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象的时段，宾馆不能“保管”时间。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“保管”不能与房间搭配，宾馆保留房间不说保管。"}, {"text": "物品", "is_correct": true, "explanation": "正确。宾馆替客人保管的是可以放置的具体东西，物品符合语境。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称呼，不是可以交给宾馆保管的东西。"}], "explanations": {"时间": "语义：时间是抽象的时段，宾馆不能“保管”时间。", "房间": "搭配：“保管”不能与房间搭配，宾馆保留房间不说保管。", "物品": "正确。宾馆替客人保管的是可以放置的具体东西，物品符合语境。", "名字": "语义：名字是称呼，不是可以交给宾馆保管的东西。"}, "sentence_index": 6, "correct_answer": "物品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首交响曲是他最好的物品。", "explanation": "这里应该用〈作品〉。作品指艺术或文学的创作成果，物品指人们使用或买卖的东西，不能用来指一首交响曲这类创作。"}, {"text": "书中最有趣的物品是那位老侦探。", "explanation": "这里应该用〈人物〉。人物指人或书中的角色，物品只指东西，不能用来指人。"}, {"text": "这条河是一件美丽的物品。", "explanation": "这里应该用〈景观〉。景观指自然或人造的风景，物品指人们使用或买卖的东西，河流属于景观，不能称为物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个仓库里堆满了很多物品们。", "corrected_sentence": "这个仓库里堆满了很多物品。", "error_description": "错误形式：“物品们”；正确形式：“物品”。“们”只用于指人或拟人的名词，物品是无生命的东西，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "用完以后，请把这只物品放回原处。", "corrected_sentence": "用完以后，请把这些物品放回原处。", "error_description": "错误形式：“这只物品”；正确形式：“这些物品”。“只”是量词，多用于单个的动物、鞋袜等成对或个体的东西；物品是泛指的东西，多件时应用“这些”统指。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
