INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "日常使用的各种东西。", "primary_collocate": null, "pronunciation": "wù pǐn", "ipa": "u˥˩ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "超市里卖的日常物品很便宜。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子里的物品都放得很整齐。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个柜子是用来放小物品的。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了很多生活物品回家。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把个人物品放在桌子上。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失物招领处有很多没人要的物品。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，旧物品太多了。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些物品用完以后要放回原处。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的物品应该让他自己收拾。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家检查自己的物品。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "样", "label": "量词"}], "register": "中性", "sense_fingerprint": "物品：日常生活中使用的各种东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7424e-dd54-40b2-af10-b5c6420f3f6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：时间不是可以在超市里出售的东西。"}, {"text": "物品", "is_correct": true, "explanation": "正确。超市里出售的日常用品用物品指称，与“很便宜”搭配自然。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不能在超市里卖，与“超市里卖的”矛盾。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“便宜”用于价格，不能用来形容感情。"}], "explanations": {"时间": "语义：时间不是可以在超市里出售的东西。", "物品": "正确。超市里出售的日常用品用物品指称，与“很便宜”搭配自然。", "房间": "语义：房间不能在超市里卖，与“超市里卖的”矛盾。", "感情": "搭配：“便宜”用于价格，不能用来形容感情。"}, "sentence_index": 0, "correct_answer": "物品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一辆物品回家。", "explanation": "这里应该用〈件〉。“辆”用于车辆，物品不能用“辆”计量。"}, {"text": "这只小猫是我最可爱的物品。", "explanation": "这里应该用〈宠物〉。宠物指人饲养的动物，物品指人们使用或买卖的东西，不能用来指活的动物。"}, {"text": "他对朋友的信任是一件珍贵的物品。", "explanation": "物品只指有形的东西，信任是抽象的情感，不能称为物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以搬走的东西，与搬家语境不符。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是人体器官，不能说“旧眼睛太多了”。"}, {"text": "节日", "is_correct": false, "explanation": "搭配：“搬家时”不能与节日这类时间事件搭配。"}, {"text": "物品", "is_correct": true, "explanation": "正确。搬家时要搬运的旧东西用物品指称，语境吻合。"}], "explanations": {"天空": "语义：天空不是可以搬走的东西，与搬家语境不符。", "眼睛": "语义：眼睛是人体器官，不能说“旧眼睛太多了”。", "节日": "搭配：“搬家时”不能与节日这类时间事件搭配。", "物品": "正确。搬家时要搬运的旧东西用物品指称，语境吻合。"}, "sentence_index": 6, "correct_answer": "物品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这部电影的主要物品。", "explanation": "这里应该用〈人物〉。人物指影视、小说中的角色，物品只指东西，不能用来指人。"}, {"text": "北京是我最想去的物品。", "explanation": "这里应该用〈城市〉。城市指人口聚集的地方，物品指人们使用或买卖的东西，不能用来指地方。"}, {"text": "这条河是一件美丽的物品。", "explanation": "这里应该用〈景观〉。景观指自然或人造的风景，物品指人们使用或买卖的东西，河流属于景观，不能称为物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个柜子里放着几本日常物品。", "corrected_sentence": "这个柜子里放着几件日常物品。", "error_description": "错误形式：“几本日常物品”；正确形式：“几件日常物品”。“本”用于书籍等，物品应用量词“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "搬家那天，我把很多旧物品们都扔掉了。", "corrected_sentence": "搬家那天，我把很多旧物品都扔掉了。", "error_description": "错误形式：“旧物品们”；正确形式：“旧物品”。“们”只用于指人的名词，物品是无生命的东西，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "反义：此义项的“当今”与“过去”相对，二者构成反义关系。"}, {"text": "早上", "is_correct": false, "explanation": "无反义关系：早上是一天中的时段，与“当今”不构成反义。"}, {"text": "冬天", "is_correct": false, "explanation": "无反义关系：冬天是季节，与“当今”不构成反义。"}, {"text": "星期一", "is_correct": false, "explanation": "无反义关系：星期一是具体的日子，与“当今”不构成反义。"}], "correct_answer": "过去", "explanations": {"过去": "反义：此义项的“当今”与“过去”相对，二者构成反义关系。", "早上": "无反义关系：早上是一天中的时段，与“当今”不构成反义。", "冬天": "无反义关系：冬天是季节，与“当今”不构成反义。", "星期一": "无反义关系：星期一是具体的日子，与“当今”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "反义：此义项的“当今”与“过去”相对，二者构成反义关系。"}, {"text": "夏天", "is_correct": false, "explanation": "无反义关系：夏天是季节，与“当今”不构成反义。"}, {"text": "下午", "is_correct": false, "explanation": "无反义关系：下午是一天中的时段，与“当今”不构成反义。"}, {"text": "周末", "is_correct": false, "explanation": "无反义关系：周末是具体的时间段，与“当今”不构成反义。"}], "correct_answer": "过去", "explanations": {"过去": "反义：此义项的“当今”与“过去”相对，二者构成反义关系。", "夏天": "无反义关系：夏天是季节，与“当今”不构成反义。", "下午": "无反义关系：下午是一天中的时段，与“当今”不构成反义。", "周末": "无反义关系：周末是具体的时间段，与“当今”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现在这个时候。", "primary_collocate": null, "pronunciation": "dāng jīn", "ipa": "tɑŋ˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "当今的物价比十年前高多了。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的孩子都会用电脑。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的年轻人很少写信了。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的房价让很多人买不起房。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今最受欢迎的歌手是谁？", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太了解当今的流行音乐。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的医生有很多新办法。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，当今的生活比过去好。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的饭馆都可以用手机点菜。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很关心当今的新闻。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "当今：现在这个时候，与过去相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7424e-dd54-40b2-af10-b5c6420f3f6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当今", "is_correct": true, "explanation": "当今：现在这个时候，与“物价比十年前高多了”的时间比较一致。"}, {"text": "古代", "is_correct": false, "explanation": "语义：古代与“比十年前高多了”的时间比较相矛盾。"}, {"text": "童年", "is_correct": false, "explanation": "搭配：“童年的物价”不是常用说法，且与“比十年前”的时间不合。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子的物价”不成立，与“物价比十年前高多了”无法搭配。"}], "explanations": {"当今": "当今：现在这个时候，与“物价比十年前高多了”的时间比较一致。", "古代": "语义：古代与“比十年前高多了”的时间比较相矛盾。", "童年": "搭配：“童年的物价”不是常用说法，且与“比十年前”的时间不合。", "桌子": "搭配：“桌子的物价”不成立，与“物价比十年前高多了”无法搭配。"}, "sentence_index": 0, "correct_answer": "当今"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我当今去过北京三次。", "explanation": "这里应该用〈曾经〉。当今指现在，不能与“去过”这种表示过去经历的说法搭配。"}, {"text": "我小时候当今很怕黑。", "explanation": "这里应该用〈从前〉。当今指现在这个时候，与“小时候”所指的过去时间矛盾。"}, {"text": "这台机器是当今那年买的。", "explanation": "这里应该用〈去年〉。当今指现在这个时候，与“那年”所指的过去时间矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当今", "is_correct": true, "explanation": "当今：现在这个时候，与“医生有很多新办法”的现代语境一致。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘不是人，不能说“棋盘的医生”。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不是人，不能当医生，句子无法成立。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：桌子与“医生”不能构成修饰关系，搭配不当。"}], "explanations": {"当今": "当今：现在这个时候，与“医生有很多新办法”的现代语境一致。", "棋盘": "语义：棋盘不是人，不能说“棋盘的医生”。", "猫": "语义：猫不是人，不能当医生，句子无法成立。", "桌子": "搭配：桌子与“医生”不能构成修饰关系，搭配不当。"}, "sentence_index": 6, "correct_answer": "当今"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他当今出生在北京。", "explanation": "这里应该用〈当年〉。当今指现在这个时候，不能用来说明过去已经发生的出生。"}, {"text": "他当今十岁时很聪明。", "explanation": "这里应该用〈以前〉。当今指现在这个时候，与“十岁时”所指的过去时间矛盾。"}, {"text": "他1995年当今进入这家公司。", "explanation": "这里应该用〈那时候〉。当今指现在这个时候，不能与“1995年”这样的过去时间并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当今地学生都有手机。", "corrected_sentence": "当今的学生都有手机。", "error_description": "错误：“当今”修饰“学生”时应用“的”，“地”是状语标记，不能用在名词前。正确：“当今的学生都有手机。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当今了公交车越来越多了。", "corrected_sentence": "当今的公交车越来越多了。", "error_description": "错误：“当今”修饰“公交车”时应用“的”连接，“了”是动态助词，不能加在“当今”后面。正确：“当今的公交车越来越多了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1488c451-18d7-42f2-8ba4-c98f12f9b7da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
