INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在家照看门户。", "primary_collocate": null, "pronunciation": "kān jiā", "ipa": "kʰan⁵⁵ tɕja⁵⁵", "syllable_count": 2, "sentences": [{"text": "我们都出去玩，只有小明留下来看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈去上班，奶奶负责看家。", "target_word": "看家", "complexity_tier": "T3", "furigana": "bà ba mā ma qù shàng bān nǎi nai fù zé kān jiā", "sentence_source": "generated"}, {"text": "过年回老家，邻居帮我们看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚我要出门，你来看家吧。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗很会看家，有人来就叫。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人看家，觉得有点无聊。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假我们去旅游，请朋友来看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟今天不想出去，他说要看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出差一周，我负责看家和喂猫。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家养了一只猫，不过它不会看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看了家", "label": "体标"}, {"form": "看过家", "label": "体标"}, {"form": "看家狗", "label": "复合"}], "register": "口语", "sense_fingerprint": "留在家中照看门户(动词)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede64bf9-61fe-41ae-8fa2-9847150bb0ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看家", "is_correct": true, "explanation": "正确：看家指留在家中照看门户，与“我们都出去玩”形成对照。"}, {"text": "出门", "is_correct": false, "explanation": "语义：出门是外出，与“留下来”意思相反，句子前后矛盾。"}, {"text": "上学", "is_correct": false, "explanation": "语义：上学是去学校，与“留下来”的留守含义不一致。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”是因工作外出，不能与“留下来”搭配，句意矛盾。"}], "explanations": {"看家": "正确：看家指留在家中照看门户，与“我们都出去玩”形成对照。", "出门": "语义：出门是外出，与“留下来”意思相反，句子前后矛盾。", "上学": "语义：上学是去学校，与“留下来”的留守含义不一致。", "出差": "搭配：“出差”是因工作外出，不能与“留下来”搭配，句意矛盾。"}, "sentence_index": 0, "correct_answer": "看家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天我去医院看家。", "explanation": "场所错误：〈看家〉指留在自己家中守门户，去医院应说〈陪床〉或〈看护〉。"}, {"text": "我们在饭店看家，客人很多。", "explanation": "场所错误：饭店是营业场所，应说〈看店〉；〈看家〉只指在家中守门户。"}, {"text": "我每天在公司看家，很认真。", "explanation": "场所错误：〈看家〉指留在家中守门户，公司应说〈看守〉或〈值班〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看家", "is_correct": true, "explanation": "正确：看家指留在家中照看门户，与“暑假去旅游，请朋友帮忙”的语境相符。"}, {"text": "上班", "is_correct": false, "explanation": "语义：上班是去工作，不能请朋友来代替，句意不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚是人生大事，与“旅游时请人帮忙”的语境不符。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“考试”是学习的活动，不能与“请朋友来”搭配。"}], "explanations": {"看家": "正确：看家指留在家中照看门户，与“暑假去旅游，请朋友帮忙”的语境相符。", "上班": "语义：上班是去工作，不能请朋友来代替，句意不通。", "结婚": "语义：结婚是人生大事，与“旅游时请人帮忙”的语境不符。", "考试": "搭配：“考试”是学习的活动，不能与“请朋友来”搭配。"}, "sentence_index": 6, "correct_answer": "看家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天给花看家，很认真。", "explanation": "配价错误：〈看家〉是不及物动词，不能带“花”这样的对象；照料花应说〈照顾〉。"}, {"text": "我们每天都在河边看家。", "explanation": "场所错误：〈看家〉指留守家中门户，河边的守卫应说〈看守〉。"}, {"text": "我每天在图书馆看家。", "explanation": "场所错误：〈看家〉指留在家中守门户，图书馆应说〈值班〉或〈看管〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天我出门，弟弟在家看家过。", "corrected_sentence": "今天我出门，弟弟在家看家。", "error_description": "错误：多余的“过”。“过”不能放在“看家”之后表示这一动作，应直接说“弟弟在家看家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一个人在家看家们。", "corrected_sentence": "他一个人在家看家。", "error_description": "多余的“们”：“看家”是动词，不能加“们”表示复数，正确为“他一个人在家看家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
