INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89951, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "下月是这个月的后一个月。", "primary_collocate": null, "pronunciation": "xià yuè", "ipa": "ɕja˥˩ ɥœ˥˩", "syllable_count": 2, "sentences": [{"text": "今天是三月，下月是四月。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下月的第一天是星期一。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月有三十天，下月有三十一天。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想下月买一台新电脑。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下月老师要去上海开会。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下月我哥哥结婚。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你下月把钱还给我。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下月的工作已经安排好了。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说下月有时间。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们下月再决定吧。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下个月", "label": "复合"}], "register": "中性", "sense_fingerprint": "下月:这个月的后一个月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab662d8-6e47-445d-add0-71f7968b21d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89951, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下月", "is_correct": true, "explanation": "正确。“下月”指这个月之后的那个月，三月之后正是四月。"}, {"text": "上月", "is_correct": false, "explanation": "语义：“上月”指上个月，应是二月，与“是四月”冲突。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指过去的整一年，不能与“三月”“四月”这样的月份对应。"}, {"text": "本月", "is_correct": false, "explanation": "语义：「本月」指这个月，即三月，与「是四月」冲突。"}], "explanations": {"下月": "正确。“下月”指这个月之后的那个月，三月之后正是四月。", "上月": "语义：“上月”指上个月，应是二月，与“是四月”冲突。", "去年": "语义：“去年”指过去的整一年，不能与“三月”“四月”这样的月份对应。", "本月": "语义：「本月」指这个月，即三月，与「是四月」冲突。"}, "sentence_index": 0, "correct_answer": "下月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试是下月举行的。", "explanation": "这里应该用〈上月〉。“是……的”强调已经发生的事，“下月”指将来，不能用于已经举行过的考试。"}, {"text": "今天是三月，下月是二月。", "explanation": "“下月”指这个月之后的那个月，应是四月，不能是二月。"}, {"text": "这本书是下月买的。", "explanation": "这里应该用〈上月〉。“是……的”强调已经发生的事，“下月”指将来，不能用来说已经买下的书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89951, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下月", "is_correct": true, "explanation": "正确。“请你下月把钱还给我”是对将来的请求，与“下月”相符。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指过去，不能用来请求对方在将来还钱。"}, {"text": "前年", "is_correct": false, "explanation": "语义：“前年”已经过去，与请对方将来还钱的语境冲突。"}, {"text": "上月", "is_correct": false, "explanation": "语义：「上月」指过去的月份，与请对方将来还钱的语境冲突。"}], "explanations": {"下月": "正确。“请你下月把钱还给我”是对将来的请求，与“下月”相符。", "昨天": "语义：“昨天”指过去，不能用来请求对方在将来还钱。", "前年": "语义：“前年”已经过去，与请对方将来还钱的语境冲突。", "上月": "语义：「上月」指过去的月份，与请对方将来还钱的语境冲突。"}, "sentence_index": 6, "correct_answer": "下月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们前年下月再决定吧。", "explanation": "“下月”指将来，不能与“前年”这样已经过去的时间并用。"}, {"text": "我们这个星期下月再决定吧。", "explanation": "“下月”是以月为单位的时间，不能与“这个星期”并用。"}, {"text": "我们这个月下月再决定吧。", "explanation": "“下月”指这个月之后的那个月，不能与“这个月”同时出现在一个时间短语里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下月的在家休息。", "corrected_sentence": "我们下月在家休息。", "error_description": "错误：“下月”作状语修饰动词时，后面不能加“的”，“的”只用于名词前。正确：“我们下月在家休息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下月了我们再去看看吧。", "corrected_sentence": "下月我们再去看看吧。", "error_description": "错误：“下月”是将来的时间词，后面不能加“了”，“了”表示完成，与将来的邀请不符。正确：“下月我们再去看看吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88202cab-7fa2-4f4d-81a2-8ea45efa3d70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "线下", "is_correct": true, "explanation": "线下：不在网络上、面对面进行，与“线上”相对。"}, {"text": "屋里", "is_correct": false, "explanation": "屋里指室内，与“线上”没有反义关系。"}, {"text": "外面", "is_correct": false, "explanation": "外面指室外，与“线上”没有反义关系。"}, {"text": "墙角", "is_correct": false, "explanation": "墙角指墙与墙相交的地方，与“线上”没有反义关系。"}], "correct_answer": "线下", "explanations": {"线下": "线下：不在网络上、面对面进行，与“线上”相对。", "屋里": "屋里指室内，与“线上”没有反义关系。", "外面": "外面指室外，与“线上”没有反义关系。", "墙角": "墙角指墙与墙相交的地方，与“线上”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "线下", "is_correct": true, "explanation": "线下：不在网络上、面对面进行，与“线上”相对。"}, {"text": "家里", "is_correct": false, "explanation": "家里指家中，与“线上”没有反义关系。"}, {"text": "河边", "is_correct": false, "explanation": "河边指河的旁边，与“线上”没有反义关系。"}, {"text": "树下", "is_correct": false, "explanation": "树下指树的下方，与“线上”没有反义关系。"}], "correct_answer": "线下", "explanations": {"线下": "线下：不在网络上、面对面进行，与“线上”相对。", "家里": "家里指家中，与“线上”没有反义关系。", "河边": "河边指河的旁边，与“线上”没有反义关系。", "树下": "树下指树的下方，与“线上”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在网络上，用电脑或手机连着网。", "primary_collocate": null, "pronunciation": "xiàn shàng", "ipa": "ɕiɛn˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "今晚我们在线上见面吧，我不出门了。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都在线上玩游戏。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在线上买了一双鞋。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们在线上聊了一个小时。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在在线上吗？我有事找你。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手机在线上交了作业。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的老师今天在线上讲课。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在线上认识了很多朋友。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在线上给奶奶订了蛋糕。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在线上看电影，不去电影院了。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "線上", "label": "繁体"}], "register": "中性", "sense_fingerprint": "线上：在网络上（处所），连着网做某事或处于联网状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60858867-7847-4d7c-829e-2ea7a1da46c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线上", "is_correct": true, "explanation": "线上：在网络上，与“我不出门了”相符，说明是网上见面。"}, {"text": "线下", "is_correct": false, "explanation": "语义：线下见面要出门，与“我不出门了”矛盾。"}, {"text": "外面", "is_correct": false, "explanation": "语义：去外面见面需要出门，与“我不出门了”矛盾。"}, {"text": "桌下", "is_correct": false, "explanation": "搭配：见面不说在“桌下”，地点搭配不当。"}], "explanations": {"线上": "线上：在网络上，与“我不出门了”相符，说明是网上见面。", "线下": "语义：线下见面要出门，与“我不出门了”矛盾。", "外面": "语义：去外面见面需要出门，与“我不出门了”矛盾。", "桌下": "搭配：见面不说在“桌下”，地点搭配不当。"}, "sentence_index": 0, "correct_answer": "线上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他晚上在线上踢了一场足球。", "explanation": "这里的“线上”指通过网络，踢足球要在场地上进行，不能在网上踢。"}, {"text": "他在线上刷了一面墙。", "explanation": "这里的“线上”指通过网络，刷墙要在墙面上进行，不能在网上完成。"}, {"text": "他在线上洗了一个热水澡。", "explanation": "这里的“线上”指通过网络，洗澡要在浴室里进行，不能在网上完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线上", "is_correct": true, "explanation": "线上：在网络上，与“老师讲课”的远程方式相符。"}, {"text": "床下", "is_correct": false, "explanation": "语义：床下不是讲课的地方，与“讲课”不符。"}, {"text": "水里", "is_correct": false, "explanation": "语义：人不能在水里讲课，句子不成立。"}, {"text": "冰箱里", "is_correct": false, "explanation": "语义：冰箱里不是讲课的地方，句子不成立。"}], "explanations": {"线上": "线上：在网络上，与“老师讲课”的远程方式相符。", "床下": "语义：床下不是讲课的地方，与“讲课”不符。", "水里": "语义：人不能在水里讲课，句子不成立。", "冰箱里": "语义：冰箱里不是讲课的地方，句子不成立。"}, "sentence_index": 6, "correct_answer": "线上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在线上打扫了房间。", "explanation": "这里的“线上”指通过网络，打扫房间要在现场进行，不能在网上完成。"}, {"text": "我每天都在线上洗碗。", "explanation": "这里的“线上”指通过网络，洗碗要在厨房里进行，不能在网上完成。"}, {"text": "他在线上吃了一个苹果。", "explanation": "这里的“线上”指通过网络，吃苹果要在现场进行，不能在网上完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他晚上在一个线上订了一张票。", "corrected_sentence": "他晚上在线上订了一张票。", "error_description": "表示网络这一处所的“线上”不能受数量词“一个”修饰，应说“在线上订了一张票”，不说“在一个线上订了一张票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥在线上的买了一本书。", "corrected_sentence": "哥哥在线上买了一本书。", "error_description": "表示网上这一处所的“在线上”是状语，直接放在动词前，中间不加“的”。应说“在线上买了一本书”，不说“在线上的买了一本书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
