INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89962, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "线下", "is_correct": true, "explanation": "线下：不通过网络、面对面进行，与“线上”构成反义。"}, {"text": "远", "is_correct": false, "explanation": "远与近相对，与“线上”没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "厚与薄相对，与“线上”没有反义关系。"}, {"text": "贵", "is_correct": false, "explanation": "贵与便宜相对，与“线上”没有反义关系。"}], "correct_answer": "线下", "explanations": {"线下": "线下：不通过网络、面对面进行，与“线上”构成反义。", "远": "远与近相对，与“线上”没有反义关系。", "厚": "厚与薄相对，与“线上”没有反义关系。", "贵": "贵与便宜相对，与“线上”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89962, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "通过网络联网进行的；在网络中的。", "primary_collocate": null, "pronunciation": "xiàn shàng", "ipa": "ɕiɛn˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们明天开线上会议。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他报了一个线上英语班。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行提供线上服务。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "线上活动比线下活动方便。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校今天改成线上授课，不用去教室。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加了一场线上音乐会。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次线上考试一共有五十道题。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "线上购物不用出门，很方便。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在群里发了线上会议的链接。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院提供线上咨询，不用排队。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "線上", "label": "繁体"}], "register": "中性", "sense_fingerprint": "线上：修饰名词，表示通过网络进行的（与线下相对）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60858867-7847-4d7c-829e-2ea7a1da46c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线上", "is_correct": true, "explanation": "线上：通过网络进行，与“明天开会”相符。"}, {"text": "高", "is_correct": false, "explanation": "体貌：会议没有高矮，不能说“高会议”。"}, {"text": "红", "is_correct": false, "explanation": "语义：颜色不能修饰会议，句子不成立。"}, {"text": "旧", "is_correct": false, "explanation": "搭配：“旧”说事物陈旧，与“明天”开的会搭配不当。"}], "explanations": {"线上": "线上：通过网络进行，与“明天开会”相符。", "高": "体貌：会议没有高矮，不能说“高会议”。", "红": "语义：颜色不能修饰会议，句子不成立。", "旧": "搭配：“旧”说事物陈旧，与“明天”开的会搭配不当。"}, "sentence_index": 0, "correct_answer": "线上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天线上去学校上课。", "explanation": "这里应该用〈线下〉。“线上”指通过网络，与“去学校上课”矛盾。"}, {"text": "他昨天在线上吃了一顿饭。", "explanation": "这里应该用〈线下〉。“线上”指通过网络，吃饭要在现场进行，不能说“在线上吃”。"}, {"text": "这次比赛我在线上拿了第一名。", "explanation": "这里应该用〈线下〉。“线上”指通过网络，比赛名次要在现场比出，不能说“在线上拿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线上", "is_correct": true, "explanation": "线上：通过网络进行，与“五十道题”的考试相符。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”说形状，不能用来修饰考试。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：“脏”描述物体的状态，不能修饰考试。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，不能用来修饰考试。"}], "explanations": {"线上": "线上：通过网络进行，与“五十道题”的考试相符。", "圆": "语义：“圆”说形状，不能用来修饰考试。", "脏": "搭配：“脏”描述物体的状态，不能修饰考试。", "甜": "语义：“甜”指味道，不能用来修饰考试。"}, "sentence_index": 6, "correct_answer": "线上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这学期我们一直线上坐在教室里上课。", "explanation": "这里应该用〈线下〉。“线上”指通过网络，与“坐在教室里”矛盾。"}, {"text": "他在线上洗了一条鱼。", "explanation": "这里的“线上”指网络，洗鱼要在水边或厨房进行，不能在网上进行。"}, {"text": "我们在线上做了一顿晚饭。", "explanation": "这里的“线上”指网络，做饭要在厨房里进行，不能说“在线上做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下周开在线上培训班。", "corrected_sentence": "我们下周开线上培训班。", "error_description": "“线上”作定语时直接放在名词前，应说“线上培训班”。前面加介词“在”变成“在线上”，是处所短语，不能直接修饰名词，所以不说“在线上培训班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次线上了考试很顺利。", "corrected_sentence": "这次线上考试很顺利。", "error_description": "“线上”作定语修饰名词时，后面不能直接加“了”，“线上了考试”不成立，应说“线上考试”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
