INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89971, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不要。", "primary_collocate": null, "pronunciation": "mò", "ipa": "mwo˥˩", "syllable_count": 1, "sentences": [{"text": "这事是我不对，你莫怪我。", "target_word": "莫", "complexity_tier": "T3", "furigana": "zhè shì shì wǒ bù duì nǐ mò guài wǒ", "sentence_source": "generated"}, {"text": "你莫怕，我在这儿呢。", "target_word": "莫", "complexity_tier": "T3", "furigana": "nǐ mò pà wǒ zài zhèr ne", "sentence_source": "generated"}, {"text": "这么晚了，你莫再出去了。", "target_word": "莫", "complexity_tier": "T3", "furigana": "zhème wǎn le nǐ mò zài chūqù le", "sentence_source": "generated"}, {"text": "你莫急，饭马上就好。", "target_word": "莫", "complexity_tier": "T3", "furigana": "nǐ mò jí fàn mǎshàng jiù hǎo", "sentence_source": "generated"}, {"text": "你莫笑他，他刚学会呢。", "target_word": "莫", "complexity_tier": "T3", "furigana": "nǐ mò xiào tā tā gāng xuéhuì ne", "sentence_source": "generated"}, {"text": "路上车多，你莫乱跑。", "target_word": "莫", "complexity_tier": "T3", "furigana": "lùshang chē duō nǐ mò luàn pǎo", "sentence_source": "generated"}, {"text": "你莫生气，是我的错。", "target_word": "莫", "complexity_tier": "T3", "furigana": "nǐ mò shēngqì shì wǒ de cuò", "sentence_source": "generated"}, {"text": "路上滑，你莫跑太快。", "target_word": "莫", "complexity_tier": "T3", "furigana": "lùshang huá nǐ mò pǎo tài kuài", "sentence_source": "generated"}, {"text": "这事你莫问我，我也不知道。", "target_word": "莫", "complexity_tier": "T3", "furigana": "zhè shì nǐ mò wèn wǒ wǒ yě bù zhīdào", "sentence_source": "generated"}, {"text": "莫慌，车很快就来了。", "target_word": "莫", "complexity_tier": "T3", "furigana": "mò huāng chē hěn kuài jiù lái le", "sentence_source": "generated"}], "morphological_forms": [{"form": "莫要", "label": "复合"}], "register": "口语", "sense_fingerprint": "莫：放在动词或形容词前，劝对方不要做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf08968a-b4cb-4d8f-9f5e-355294b2811a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89971, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫（mò）：副词，表示劝阻“不要”。"}, {"text": "破", "is_correct": false, "explanation": "pò 与 mò 声母不同（p 与 m），意思是破损。"}, {"text": "木", "is_correct": false, "explanation": "mù 与 mò 韵母不同（u 与 o），意思是树木。"}, {"text": "骂", "is_correct": false, "explanation": "mà 与 mò 韵母不同（a 与 o），意思是责骂。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 mò（第四声）声调不同，意思是用手触碰。"}, {"text": "磨", "is_correct": false, "explanation": "mó（第二声）与 mò（第四声）声调不同，意思是研磨。"}, {"text": "密", "is_correct": false, "explanation": "mì 与 mò 韵母不同（i 与 o），意思是紧密或秘密。"}], "explanations": {"莫": "正确。莫（mò）：副词，表示劝阻“不要”。", "破": "pò 与 mò 声母不同（p 与 m），意思是破损。", "木": "mù 与 mò 韵母不同（u 与 o），意思是树木。", "骂": "mà 与 mò 韵母不同（a 与 o），意思是责骂。", "摸": "mō（第一声）与 mò（第四声）声调不同，意思是用手触碰。", "磨": "mó（第二声）与 mò（第四声）声调不同，意思是研磨。", "密": "mì 与 mò 韵母不同（i 与 o），意思是紧密或秘密。"}, "sentence_index": null, "correct_answer": "莫"}, "level_3": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫：表示劝阻“不要”，与“你……怪我”的请求语气相合。"}, {"text": "竟", "is_correct": false, "explanation": "语域：「竟」偏书面，与口语化的请求语气不合；且「竟」表示出乎意料，与“是我不对”的承认过错不协调。"}, {"text": "也", "is_correct": false, "explanation": "语义：「也」表示同样的情况，需要前文有另一人同样怪罪，句中没有这样的语境。"}, {"text": "刚", "is_correct": false, "explanation": "语义：「刚」表示动作刚刚发生，与“怪我”之后的劝阻语气相悖。"}], "explanations": {"莫": "正确。莫：表示劝阻“不要”，与“你……怪我”的请求语气相合。", "竟": "语域：「竟」偏书面，与口语化的请求语气不合；且「竟」表示出乎意料，与“是我不对”的承认过错不协调。", "也": "语义：「也」表示同样的情况，需要前文有另一人同样怪罪，句中没有这样的语境。", "刚": "语义：「刚」表示动作刚刚发生，与“怪我”之后的劝阻语气相悖。"}, "sentence_index": 0, "correct_answer": "莫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我莫想去北京。", "explanation": "这里应该用〈不想〉。莫表示劝阻，不能用来否定“想”。"}, {"text": "他莫愿意帮忙。", "explanation": "这里应该用〈不愿意〉。莫表示劝阻，不能用来表示不愿意。"}, {"text": "我莫明白他的意思。", "explanation": "这里应该用〈不明白〉。莫表示劝阻，不能用来否定“明白”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89971, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫（mò）：副词，表示劝阻“不要”。"}, {"text": "妈", "is_correct": false, "explanation": "mā（第一声）与 mò（第四声）声调不同，意思是母亲。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 mò（第四声）声调不同，意思是马匹。"}, {"text": "握", "is_correct": false, "explanation": "wò 与 mò 声母不同（w 与 m），意思是握住。"}, {"text": "模", "is_correct": false, "explanation": "mó（第二声）与 mò（第四声）声调不同，意思是模样或模型。"}], "explanations": {"莫": "正确。莫（mò）：副词，表示劝阻“不要”。", "妈": "mā（第一声）与 mò（第四声）声调不同，意思是母亲。", "马": "mǎ（第三声）与 mò（第四声）声调不同，意思是马匹。", "握": "wò 与 mò 声母不同（w 与 m），意思是握住。", "模": "mó（第二声）与 mò（第四声）声调不同，意思是模样或模型。"}, "sentence_index": null, "correct_answer": "莫"}, "level_3": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫：表示劝阻“不要”，与“你……生气”的劝慰语气相合。"}, {"text": "偏", "is_correct": false, "explanation": "语义：「偏」表示故意与常理相反，与“是我的错”的承认语气不合。"}, {"text": "才", "is_correct": false, "explanation": "搭配：「才」需要“才……”的限定格式配合，单独用在“生气”前与“是我的错”的语境不协调。"}, {"text": "却", "is_correct": false, "explanation": "语义：「却」表示转折，与“是我的错”的因果关系不合。"}], "explanations": {"莫": "正确。莫：表示劝阻“不要”，与“你……生气”的劝慰语气相合。", "偏": "语义：「偏」表示故意与常理相反，与“是我的错”的承认语气不合。", "才": "搭配：「才」需要“才……”的限定格式配合，单独用在“生气”前与“是我的错”的语境不协调。", "却": "语义：「却」表示转折，与“是我的错”的因果关系不合。"}, "sentence_index": 6, "correct_answer": "莫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天莫去学校。", "explanation": "这里应该用〈没〉，表示否定已经发生的动作。莫只用于劝阻，不能用于过去的事。"}, {"text": "这个房间莫大，很舒服。", "explanation": "这里应该用〈很大〉或〈宽敞〉。“莫大”是书面语，多用于“荣幸、损失”等抽象事物，不用于形容房间的大小。"}, {"text": "我莫会游泳。", "explanation": "这里应该用〈不会〉。莫表示劝阻，不能用于说明能力上的否定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你不莫担心，明天会好的。", "corrected_sentence": "你莫担心，明天会好的。", "error_description": "多余的“不”与“莫”重复否定。“莫”本身已表示劝阻，不能再加“不”，正确形式是“你莫担心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你莫的着急，事情会解决的。", "corrected_sentence": "你莫着急，事情会解决的。", "error_description": "助词错误：“莫”后不能加“的”，“莫的着急”不通。正确形式是“你莫着急”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
