INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89972, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "（书面）表示禁止或劝阻，相当于“不要”。", "primary_collocate": null, "pronunciation": "mò", "ipa": "mwo˥˩", "syllable_count": 1, "sentences": [{"text": "闲人莫入。", "target_word": "莫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "危险区域，游客莫靠近。", "target_word": "莫", "complexity_tier": "T3", "furigana": "wēixiǎn qūyù yóukè mò kàojìn", "sentence_source": "generated"}, {"text": "车厢内，乘客莫大声通话。", "target_word": "莫", "complexity_tier": "T3", "furigana": "chēxiāng nèi chéngkè mò dàshēng tōnghuà", "sentence_source": "generated"}, {"text": "展品易碎，莫用手触摸。", "target_word": "莫", "complexity_tier": "T3", "furigana": "zhǎnpǐn yì suì mò yòng shǒu chùmō", "sentence_source": "generated"}, {"text": "莫以善小而不为。", "target_word": "莫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "莫愁前路无知己。", "target_word": "莫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会场内，观众莫随意走动。", "target_word": "莫", "complexity_tier": "T3", "furigana": "huìchǎng nèi guānzhòng mò suíyì zǒudòng", "sentence_source": "generated"}, {"text": "此处施工，行人莫入。", "target_word": "莫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆内，读者莫高声喧哗。", "target_word": "莫", "complexity_tier": "T3", "furigana": "túshūguǎn nèi dúzhě mò gāoshēng xuānhuá", "sentence_source": "generated"}, {"text": "遇事应冷静，莫冲动行事。", "target_word": "莫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "莫要", "label": "复合"}], "register": "书面", "sense_fingerprint": "莫：书面语中用于告示、劝诫，表示禁止或劝阻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf08968a-b4cb-4d8f-9f5e-355294b2811a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫（mò）：书面语，表示禁止或劝阻。"}, {"text": "破", "is_correct": false, "explanation": "pò 与 mò 声母不同（p 与 m），意思是破损。"}, {"text": "木", "is_correct": false, "explanation": "mù 与 mò 韵母不同（u 与 o），意思是树木。"}, {"text": "骂", "is_correct": false, "explanation": "mà 与 mò 韵母不同（a 与 o），意思是责骂。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 mò（第四声）声调不同，意思是用手触碰。"}, {"text": "磨", "is_correct": false, "explanation": "mó（第二声）与 mò（第四声）声调不同，意思是研磨。"}], "explanations": {"莫": "正确。莫（mò）：书面语，表示禁止或劝阻。", "破": "pò 与 mò 声母不同（p 与 m），意思是破损。", "木": "mù 与 mò 韵母不同（u 与 o），意思是树木。", "骂": "mà 与 mò 韵母不同（a 与 o），意思是责骂。", "摸": "mō（第一声）与 mò（第四声）声调不同，意思是用手触碰。", "磨": "mó（第二声）与 mò（第四声）声调不同，意思是研磨。"}, "sentence_index": null, "correct_answer": "莫"}, "level_3": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫：书面语中表示禁止，与“闲人……入”的告示语境相合。"}, {"text": "才", "is_correct": false, "explanation": "语义：「才」表示限定，“闲人才入”与告示禁止闲人入内的意思相反。"}, {"text": "都", "is_correct": false, "explanation": "语义：「都」表示全部，“闲人都入”与告示的禁止意思相悖。"}, {"text": "偏", "is_correct": false, "explanation": "语域：「偏」偏口语，与告示的书面语体不符；且「偏」表示故意，与禁止的语境不合。"}], "explanations": {"莫": "正确。莫：书面语中表示禁止，与“闲人……入”的告示语境相合。", "才": "语义：「才」表示限定，“闲人才入”与告示禁止闲人入内的意思相反。", "都": "语义：「都」表示全部，“闲人都入”与告示的禁止意思相悖。", "偏": "语域：「偏」偏口语，与告示的书面语体不符；且「偏」表示故意，与禁止的语境不合。"}, "sentence_index": 0, "correct_answer": "莫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我莫想来参加会议。", "explanation": "这里应该用〈不想〉。莫表示禁止，不能用来否定“想”。"}, {"text": "我莫明白他的意思。", "explanation": "这里应该用〈不明白〉。莫表示禁止，不能用来否定“明白”。"}, {"text": "这份报告莫写完了。", "explanation": "这里应该用〈没〉，表示已经完成的事。“莫”只用于禁止或劝阻，不能陈述已完成的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89972, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫（mò）：书面语，表示禁止或劝阻。"}, {"text": "妈", "is_correct": false, "explanation": "mā（第一声）与 mò（第四声）声调不同，意思是母亲。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 mò（第四声）声调不同，意思是马匹。"}, {"text": "握", "is_correct": false, "explanation": "wò 与 mò 声母不同（w 与 m），意思是握住。"}, {"text": "模", "is_correct": false, "explanation": "mó（第二声）与 mò（第四声）声调不同，意思是模样或模型。"}], "explanations": {"莫": "正确。莫（mò）：书面语，表示禁止或劝阻。", "妈": "mā（第一声）与 mò（第四声）声调不同，意思是母亲。", "马": "mǎ（第三声）与 mò（第四声）声调不同，意思是马匹。", "握": "wò 与 mò 声母不同（w 与 m），意思是握住。", "模": "mó（第二声）与 mò（第四声）声调不同，意思是模样或模型。"}, "sentence_index": null, "correct_answer": "莫"}, "level_3": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫：书面语中表示禁止，与“观众……随意走动”的会场规定相合。"}, {"text": "竟", "is_correct": false, "explanation": "语义：「竟」表示出乎意料，与会场规定观众不得随意走动的语境相悖。"}, {"text": "却", "is_correct": false, "explanation": "语义：「却」表示转折，与会场内的禁止语境不协调。"}, {"text": "又", "is_correct": false, "explanation": "体貌：「又」表示重复发生，与“莫……”的劝阻语境不合。"}], "explanations": {"莫": "正确。莫：书面语中表示禁止，与“观众……随意走动”的会场规定相合。", "竟": "语义：「竟」表示出乎意料，与会场规定观众不得随意走动的语境相悖。", "却": "语义：「却」表示转折，与会场内的禁止语境不协调。", "又": "体貌：「又」表示重复发生，与“莫……”的劝阻语境不合。"}, "sentence_index": 6, "correct_answer": "莫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天莫来上班。", "explanation": "这里应该用〈没〉，表示否定已经发生的事。莫只用于劝阻，不能用于过去。"}, {"text": "这张书桌莫正好放我的电脑。", "explanation": "这里应该删去〈莫〉。“莫”表示禁止，不能修饰“正好”。"}, {"text": "她莫会开车。", "explanation": "这里应该用〈不会〉。莫表示禁止，不能用于说明能力上的否定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请乘客不莫随意开门。", "corrected_sentence": "请乘客莫随意开门。", "error_description": "多余的“不”与“莫”重复否定。“莫”已表示禁止，不能再加“不”，正确形式是“请乘客莫随意开门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "展厅内，游客莫的随意触碰展品。", "corrected_sentence": "展厅内，游客莫随意触碰展品。", "error_description": "助词错误：“莫”后不能加“的”，“莫的随意”不通。正确形式是“游客莫随意触碰展品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14428e8-cee6-41bf-a394-88fa470dface') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
