INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89977, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常喜欢、很亲近。", "primary_collocate": null, "pronunciation": "qīn ài", "ipa": "tɕʰin ai", "syllable_count": 2, "sentences": [{"text": "亲爱的妈妈，生日快乐，我很想你。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在信的开头写了“亲爱的爸爸”。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲爱的朋友们，欢迎你们来我家做客。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说：“亲爱的，早上好！”", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲爱的老师，谢谢您这一年的帮助。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲爱的奶奶，天冷了，请多穿衣服。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给亲爱的姐姐寄了一张卡片。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲爱的同学们，明天请带好课本。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对妻子说：“亲爱的，别担心。”", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲爱的读者，感谢您阅读这本书。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲爱的", "label": "定语形式"}, {"form": "親愛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "称呼语中表示喜爱、亲近，多用于信件开头或呼唤对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c28d83a-6b09-4f23-ba3e-738046e27c83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陌生", "is_correct": false, "explanation": "语义：妈妈是亲近的家人，“陌生”与称呼“妈妈”和“生日快乐”的亲切语气相矛盾。"}, {"text": "亲爱", "is_correct": true, "explanation": "“亲爱”修饰“妈妈”，表示亲近喜爱，符合信件中对母亲的称呼。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”描写肤色或颜色，不能用来修饰亲人的称呼，句子不通。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”表示感情疏远，与后半句“我很想你”的情感相冲突。"}], "explanations": {"陌生": "语义：妈妈是亲近的家人，“陌生”与称呼“妈妈”和“生日快乐”的亲切语气相矛盾。", "亲爱": "“亲爱”修饰“妈妈”，表示亲近喜爱，符合信件中对母亲的称呼。", "雪白": "体貌：“雪白”描写肤色或颜色，不能用来修饰亲人的称呼，句子不通。", "冷淡": "语义：“冷淡”表示感情疏远，与后半句“我很想你”的情感相冲突。"}, "sentence_index": 0, "correct_answer": "亲爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师用亲爱的语气跟我说话。", "explanation": "这里应该用〈亲切〉。“亲爱”指对亲近之人的感情或称呼，不修饰语气，描述语气要用“亲切”。"}, {"text": "这个问题很亲爱。", "explanation": "这里应该用〈简单〉。「亲爱」指对人的喜爱或亲近，不用来形容问题的难易，应说「这个问题很简单」。"}, {"text": "他们俩的关系很亲爱。", "explanation": "这里应该用〈亲密〉。“亲爱”说的是人对人的感情或称呼，描述关系要用“亲密”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咸", "is_correct": false, "explanation": "搭配：“咸”说的是味道，不能用来修饰“姐姐”。"}, {"text": "炎热", "is_correct": false, "explanation": "搭配：“炎热”描写天气，不用来修饰人，句子不通。"}, {"text": "废弃", "is_correct": false, "explanation": "语义：“废弃”指被丢弃的东西，与“姐姐”和寄卡片的温情语境相矛盾。"}, {"text": "亲爱", "is_correct": true, "explanation": "“亲爱”修饰“姐姐”，表示感情深厚，符合寄卡片给亲人的语境。"}], "explanations": {"咸": "搭配：“咸”说的是味道，不能用来修饰“姐姐”。", "炎热": "搭配：“炎热”描写天气，不用来修饰人，句子不通。", "废弃": "语义：“废弃”指被丢弃的东西，与“姐姐”和寄卡片的温情语境相矛盾。", "亲爱": "“亲爱”修饰“姐姐”，表示感情深厚，符合寄卡片给亲人的语境。"}, "sentence_index": 6, "correct_answer": "亲爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用亲爱的声音讲了一个故事。", "explanation": "这里应该用〈温柔〉。“亲爱”说人与人之间的感情或称呼，不修饰声音。"}, {"text": "他对陌生人很亲爱。", "explanation": "这里应该用〈友善〉。“亲爱”表示对亲近者的深厚感情，对陌生人应该说“友善”。"}, {"text": "他亲爱地招待客人。", "explanation": "这里应该用〈热情〉。“亲爱”表示对亲近者的深厚感情，招待一般客人这类待人之举要说“热情地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "亲爱爸爸，节日快乐。", "corrected_sentence": "亲爱的爸爸，节日快乐。", "error_description": "错误：“亲爱爸爸”漏掉了“的”。正确：“亲爱的爸爸”。“亲爱”作定语修饰称呼时，后面要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "亲爱地同学们，明天见。", "corrected_sentence": "亲爱的同学们，明天见。", "error_description": "错误：“亲爱地同学们”用了“地”。正确：“亲爱的同学们”。“地”修饰动词，名词前的修饰语要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
