INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89978, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "感情深厚、关系亲近的。", "primary_collocate": null, "pronunciation": "qīn ài", "ipa": "tɕʰin ai", "syllable_count": 2, "sentences": [{"text": "亲爱的祖国，我为你骄傲。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我最亲爱的朋友。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都爱我们亲爱的老师。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很想念亲爱的家人。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲爱的战友们，我们一起走过了很多年。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他握着亲爱的外婆的手，不想松开。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶是我最亲爱的人。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临走前，他抱了抱亲爱的女儿。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有我亲爱的同事们。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给亲爱的弟弟买了一份礼物。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲爱的", "label": "定语形式"}, {"form": "最亲爱的", "label": "最高程度形式"}, {"form": "親愛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "修饰人或事物，表示感情深厚、关系亲近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c28d83a-6b09-4f23-ba3e-738046e27c83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”与“祖国”和“我为你骄傲”的情感相冲突，句子语义不通。"}, {"text": "亲爱", "is_correct": true, "explanation": "“亲爱”修饰“祖国”，表示感情深厚，与“为你骄傲”的情感一致。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”说的是味道，不能用来修饰“祖国”。"}, {"text": "废弃", "is_correct": false, "explanation": "语义：“废弃”指被弃置的东西，与“祖国”和“为你骄傲”的语境相矛盾。"}], "explanations": {"冷漠": "语义：“冷漠”与“祖国”和“我为你骄傲”的情感相冲突，句子语义不通。", "亲爱": "“亲爱”修饰“祖国”，表示感情深厚，与“为你骄傲”的情感一致。", "咸": "搭配：“咸”说的是味道，不能用来修饰“祖国”。", "废弃": "语义：“废弃”指被弃置的东西，与“祖国”和“为你骄傲”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "亲爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的服务很亲爱。", "explanation": "这里应该用〈亲切〉。“亲爱”不用来形容服务，形容服务态度要用“亲切”。"}, {"text": "我们要打倒亲爱的敌人。", "explanation": "这里应该用〈可恨〉。「亲爱」表示感情深厚，用来修饰敌人不合逻辑，形容敌人应说「可恨的敌人」。"}, {"text": "我和同桌的关系很亲爱。", "explanation": "这里应该用〈亲密〉。“亲爱”侧重人的感情或称呼，描述关系要用“亲密”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陌生", "is_correct": false, "explanation": "语义：“奶奶”是亲人，“最陌生的人”与前半句的亲近关系相矛盾。"}, {"text": "亲爱", "is_correct": true, "explanation": "“亲爱”修饰“人”，表示感情深厚，与“奶奶是我最……的人”的语境一致。"}, {"text": "炎热", "is_correct": false, "explanation": "搭配：“炎热”描写天气，不用来形容人与人之间的关系。"}, {"text": "生疏", "is_correct": false, "explanation": "语义：“生疏”表示不熟悉，与“奶奶”的亲近关系相矛盾。"}], "explanations": {"陌生": "语义：“奶奶”是亲人，“最陌生的人”与前半句的亲近关系相矛盾。", "亲爱": "“亲爱”修饰“人”，表示感情深厚，与“奶奶是我最……的人”的语境一致。", "炎热": "搭配：“炎热”描写天气，不用来形容人与人之间的关系。", "生疏": "语义：“生疏”表示不熟悉，与“奶奶”的亲近关系相矛盾。"}, "sentence_index": 6, "correct_answer": "亲爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的价格很亲爱。", "explanation": "这里应该用〈便宜〉。“亲爱”不用来形容价格，说价格低要用“便宜”。"}, {"text": "这件衣服的颜色很亲爱。", "explanation": "这里应该用〈鲜艳〉。“亲爱”不用来形容颜色，说颜色醒目要用“鲜艳”。"}, {"text": "他对陌生人很亲爱。", "explanation": "这里应该用〈友善〉。“亲爱”表示对亲近者的深厚感情，对陌生人应该说“友善”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "亲爱故乡，我为你骄傲。", "corrected_sentence": "亲爱的故乡，我为你骄傲。", "error_description": "错误：“亲爱故乡”漏掉了“的”。正确：“亲爱的故乡”。“亲爱”作定语修饰名词时，后面要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "亲爱地家人，请回家吃饭。", "corrected_sentence": "亲爱的家人，请回家吃饭。", "error_description": "错误：“亲爱地家人”用了“地”。正确：“亲爱的家人”。“地”修饰动词，名词前的修饰语要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89983, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "正确：“正常”与“变态”（不正常）构成反义，指合乎常规。"}, {"text": "勇敢", "is_correct": false, "explanation": "无关：“勇敢”形容胆量，与“变态”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容明白、分明，与“变态”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "无关：“热情”形容待人友好，与“变态”没有反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "正确：“正常”与“变态”（不正常）构成反义，指合乎常规。", "勇敢": "无关：“勇敢”形容胆量，与“变态”没有反义关系。", "清楚": "无关：“清楚”形容明白、分明，与“变态”没有反义关系。", "热情": "无关：“热情”形容待人友好，与“变态”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89983, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "正确：“正常”与“变态”（不正常）构成反义，指合乎常规。"}, {"text": "温柔", "is_correct": false, "explanation": "无关：“温柔”形容性情或态度柔和，与“变态”没有反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "无关：“认真”形容做事专心踏实，与“变态”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”形容智力好，与“变态”没有反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "正确：“正常”与“变态”（不正常）构成反义，指合乎常规。", "温柔": "无关：“温柔”形容性情或态度柔和，与“变态”没有反义关系。", "认真": "无关：“认真”形容做事专心踏实，与“变态”没有反义关系。", "聪明": "无关：“聪明”形容智力好，与“变态”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89983, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不正常，样子或做法很怪、让人不舒服。", "primary_collocate": null, "pronunciation": "biàn tài", "ipa": "piɛn˥˩ tʰai˥˩", "syllable_count": 2, "sentences": [{"text": "他的做法太变态了，大家都很不舒服。", "target_word": "变态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人笑得很变态，我有点怕。", "target_word": "变态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的辣度真变态，我吃不下去。", "target_word": "变态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他老是盯着别人看，样子很变态。", "target_word": "变态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个电影的结局很变态，看完我睡不着。", "target_word": "变态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别这么变态，这样做让人很不舒服。", "target_word": "变态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出的要求太变态了，没人答应。", "target_word": "变态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的难度很变态，我玩了十次都没过。", "target_word": "变态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爱好有点变态，喜欢收集旧牙刷。", "target_word": "变态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的规定很变态，连上厕所都要记录。", "target_word": "变态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "變態", "label": "繁体"}], "register": "口语", "sense_fingerprint": "变态：口语，形容样子或做法怪异、让人不舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60858867-7847-4d7c-829e-2ea7a1da46c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89983, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变态", "is_correct": true, "explanation": "正确：“变态”形容做法怪异、让人不舒服，与语境相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”指外貌或事物好看，与“做法太……大家都很不舒服”的语境矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不能修饰“做法”。"}, {"text": "体贴", "is_correct": false, "explanation": "语义：“体贴”指待人周到，与“大家都很不舒服”矛盾。"}], "explanations": {"变态": "正确：“变态”形容做法怪异、让人不舒服，与语境相符。", "漂亮": "语义：“漂亮”指外貌或事物好看，与“做法太……大家都很不舒服”的语境矛盾。", "热闹": "搭配：“热闹”形容场面或气氛，不能修饰“做法”。", "体贴": "语义：“体贴”指待人周到，与“大家都很不舒服”矛盾。"}, "sentence_index": 0, "correct_answer": "变态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆里的气氛很变态，大家都在认真看书。", "explanation": "这里应该用〈安静〉。“变态”形容怪异、让人不舒服，不能用来形容图书馆里安静的气氛。"}, {"text": "店员的态度很变态，我们都很满意。", "explanation": "这里应该用〈热情〉。“变态”形容做法怪异、令人不舒服，不能用来形容待人友好。"}, {"text": "服务员对我们很变态，我们吃得很开心。", "explanation": "这里应该用〈亲切〉。“变态”形容怪异、令人不舒服，不能用来形容服务态度友好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变态", "is_correct": true, "explanation": "正确：“变态”形容要求怪异、让人难以接受，与语境相符。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用来修饰“要求”。"}, {"text": "凉爽", "is_correct": false, "explanation": "搭配：“凉爽”形容天气或感觉，不能修饰“要求”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰“要求”。"}], "explanations": {"变态": "正确：“变态”形容要求怪异、让人难以接受，与语境相符。", "明亮": "搭配：“明亮”形容光线或颜色，不能用来修饰“要求”。", "凉爽": "搭配：“凉爽”形容天气或感觉，不能修饰“要求”。", "清脆": "搭配：“清脆”形容声音，不能修饰“要求”。"}, "sentence_index": 6, "correct_answer": "变态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器经过变态，性能提高了不少。", "explanation": "这是“变态”的生物学义（动物个体发育中的形态变化），只用于动物，用在机器上不通，与此处形容做法怪、让人不舒服的义项不同。"}, {"text": "他经过变态，个子长高了不少。", "explanation": "这是“变态”的生物学义（动物个体发育中的形态变化），人不会经过变态，与此处形容做法怪的义项不同。"}, {"text": "这种液体经过变态，凝固成了固体。", "explanation": "“变态”没有化学状态变化的义项，液体凝固不能用“变态”，与此处形容做法怪、让人不舒服的义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人的眼神变态了过，让人发毛。", "corrected_sentence": "那个人的眼神变态了，让人发毛。", "error_description": "“了”与“过”不能同时用在同一个谓词后，应只保留“了”，说“变态了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我觉得这个规定很的变态，实在受不了。", "corrected_sentence": "我觉得这个规定很变态，实在受不了。", "error_description": "程度副词“很”直接修饰形容词，中间不能加“的”。应说“很变态”，不说“很的变态”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616cdad6-db06-43bd-97d6-25812ac8967d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89985, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "鼓舞", "is_correct": true, "explanation": "正确答案。鼓舞与“打击”构成反义：鼓舞指激发人的信心和勇气，与使人失去信心相反。"}, {"text": "思考", "is_correct": false, "explanation": "思考是动词，但与“打击”没有反义关系，指用脑子考虑问题。"}, {"text": "保存", "is_correct": false, "explanation": "保存是动词，但与“打击”没有反义关系，指使东西保持原样或留存。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运是动词，但与“打击”没有反义关系，指把东西从一处移到另一处。"}], "correct_answer": "鼓舞", "explanations": {"鼓舞": "正确答案。鼓舞与“打击”构成反义：鼓舞指激发人的信心和勇气，与使人失去信心相反。", "思考": "思考是动词，但与“打击”没有反义关系，指用脑子考虑问题。", "保存": "保存是动词，但与“打击”没有反义关系，指使东西保持原样或留存。", "搬运": "搬运是动词，但与“打击”没有反义关系，指把东西从一处移到另一处。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89985, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89985, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打击是用力打,或者让人很伤心。", "primary_collocate": null, "pronunciation": "dǎ jī", "ipa": "ta˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "他失败了,朋友不该再打击他。", "target_word": "打击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的话打击了他学画画的信心。", "target_word": "打击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别打击孩子,他们需要鼓励。", "target_word": "打击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛输了,这个结果打击了全队。", "target_word": "打击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是打击我,我越来越没自信。", "target_word": "打击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈从不打击我,总是鼓励我。", "target_word": "打击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们的笑声打击着她的自尊心。", "target_word": "打击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他那句话打击过我,我现在还记得。", "target_word": "打击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坏消息把他打击得说不出话。", "target_word": "打击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌军的炮火猛烈打击了我们的阵地。", "target_word": "打击", "complexity_tier": "T3", "furigana": "dí jūn de pào huǒ měng liè dǎ jī le wǒ men de zhèn dì", "sentence_source": "generated"}], "morphological_forms": [{"form": "打击了", "label": "完成体"}, {"form": "打击着", "label": "进行体"}, {"form": "打击过", "label": "经历体"}, {"form": "打擊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "打击:用力打,或让人伤心、没信心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d3da1c-9c58-4131-8533-51a4d2c792cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89985, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打击", "is_correct": true, "explanation": "正确答案。打击，dǎjī，意思是用力打，或使人伤心、失去信心。"}, {"text": "打气", "is_correct": false, "explanation": "声母与声调都不同（qì 与 jī），意思是打气、鼓劲。"}, {"text": "打进", "is_correct": false, "explanation": "jìn（第四声）与 jī（第一声）韵母不同，意思是打入、打进。"}, {"text": "大吉", "is_correct": false, "explanation": "dà jí 与 dǎ jī 两个音节声调都不同，意思是大吉、运气好。"}, {"text": "大计", "is_correct": false, "explanation": "dà jì 与 dǎ jī 两个音节声调都不同，意思是重大的计划。"}], "explanations": {"打击": "正确答案。打击，dǎjī，意思是用力打，或使人伤心、失去信心。", "打气": "声母与声调都不同（qì 与 jī），意思是打气、鼓劲。", "打进": "jìn（第四声）与 jī（第一声）韵母不同，意思是打入、打进。", "大吉": "dà jí 与 dǎ jī 两个音节声调都不同，意思是大吉、运气好。", "大计": "dà jì 与 dǎ jī 两个音节声调都不同，意思是重大的计划。"}, "sentence_index": null, "correct_answer": "打击"}, "level_3": {"options": [{"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是为喜事道喜，朋友在他失败之后不能这样说，与“失败了”矛盾。"}, {"text": "嘉奖", "is_correct": false, "explanation": "语域：“嘉奖”是正式的官方表扬，用于朋友之间的私下语境不合适。"}, {"text": "打击", "is_correct": true, "explanation": "正确答案。“不该再打击他”表示朋友不应该继续让他失去信心。"}, {"text": "表彰", "is_correct": false, "explanation": "语域：“表彰”是公开、正式的表扬，与朋友之间的口吻不合。"}], "explanations": {"祝贺": "语义：“祝贺”是为喜事道喜，朋友在他失败之后不能这样说，与“失败了”矛盾。", "嘉奖": "语域：“嘉奖”是正式的官方表扬，用于朋友之间的私下语境不合适。", "打击": "正确答案。“不该再打击他”表示朋友不应该继续让他失去信心。", "表彰": "语域：“表彰”是公开、正式的表扬，与朋友之间的口吻不合。"}, "sentence_index": 0, "correct_answer": "打击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次胜利打击了全队的信心。", "explanation": "这里应该用〈鼓舞〉。胜利会振奋人心，不是使人失去信心，句意与“打击”相反。"}, {"text": "他打击了一封信给朋友。", "explanation": "这里应该用〈写〉。打击不能用于书信，给朋友写信要用“写”。"}, {"text": "王老师打击了我的作业，给了我一个好分数。", "explanation": "这里应该用〈批改〉。打击不用于作业，批改作业要用“批改”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89985, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "打击", "is_correct": true, "explanation": "正确答案。打击，dǎjī，意思是用力打，或使人伤心、失去信心。"}, {"text": "打劫", "is_correct": false, "explanation": "jié（第二声）与 jī（第一声）韵母与声调都不同，意思是抢劫。"}, {"text": "打金", "is_correct": false, "explanation": "jīn（第一声）与 jī 韵母不同，多一个 n，意思是打制金器。"}, {"text": "打酒", "is_correct": false, "explanation": "jiǔ（第三声）与 jī 韵母不同，意思是去买酒。"}, {"text": "打起", "is_correct": false, "explanation": "qǐ（第三声）与 jī 声母不同（q 与 j），意思是打起精神。"}], "explanations": {"打击": "正确答案。打击，dǎjī，意思是用力打，或使人伤心、失去信心。", "打劫": "jié（第二声）与 jī（第一声）韵母与声调都不同，意思是抢劫。", "打金": "jīn（第一声）与 jī 韵母不同，多一个 n，意思是打制金器。", "打酒": "jiǔ（第三声）与 jī 韵母不同，意思是去买酒。", "打起": "qǐ（第三声）与 jī 声母不同（q 与 j），意思是打起精神。"}, "sentence_index": null, "correct_answer": "打击"}, "level_3": {"options": [{"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”需要有人动手去擦，笑声不能擦拭自尊心。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”要有人把涂料刷在具体物体表面上，笑声不能粉刷自尊心。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：“烘烤”是用热力加工食物，与“笑声”和“自尊心”都不相干。"}, {"text": "打击", "is_correct": true, "explanation": "正确答案。“笑声打击着她的自尊心”表示笑声持续地让她的自尊心受到伤害。"}], "explanations": {"擦拭": "搭配：“擦拭”需要有人动手去擦，笑声不能擦拭自尊心。", "粉刷": "搭配：“粉刷”要有人把涂料刷在具体物体表面上，笑声不能粉刷自尊心。", "烘烤": "语义：“烘烤”是用热力加工食物，与“笑声”和“自尊心”都不相干。", "打击": "正确答案。“笑声打击着她的自尊心”表示笑声持续地让她的自尊心受到伤害。"}, "sentence_index": 6, "correct_answer": "打击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师的鼓励打击了他的斗志。", "explanation": "这里应该用〈鼓舞〉。打击是使人泄气，与句中“鼓励”的作用相反，激发斗志要用“鼓舞”。"}, {"text": "他用铅笔打击了一幅画。", "explanation": "这里应该用〈画〉。打击不能用于绘画，用铅笔画画要说“画”。"}, {"text": "妈妈轻轻地打击了孩子的背。", "explanation": "这里应该用〈拍打〉。打击强调用力打，轻拍孩子的背要用“拍打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那次失败打击了着他的信心。", "corrected_sentence": "那次失败打击了他的信心。", "error_description": "错误：“打击”后同时用了“了”和“着”，二者不能同时出现在同一动词后面。正确：只用“了”，即“打击了他的信心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个消息把她打击的哭了。", "corrected_sentence": "这个消息把她打击得哭了。", "error_description": "错误：“打击”后的补语用了“的”。正确：应用“得”，写作“打击得……”。补语要用“得”连接，“的”用于名词前的修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
