INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90001, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回到原来的地方。", "primary_collocate": null, "pronunciation": "fǎn huí", "ipa": "fan˨˩˦ xweɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他下午三点返回学校。", "target_word": "返回", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "旅行结束后,我们返回了北京。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王明天要返回老家看父母。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人吃完饭,就返回了酒店。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他离开多年,终于返回了家乡。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们走了一小时,才返回营地。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "登山队员已经返回山下的小镇。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他带着行李,急忙返回车站。", "target_word": "返回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说,下课后请马上返回教室。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去过国外,但很快返回了公司。", "target_word": "返回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "返回了", "label": "完成体"}, {"form": "返回过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "返回:人回到原来所在的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d3da1c-9c58-4131-8533-51a4d2c792cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90001, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”是心理活动，不是人身体回到学校，与“下午三点”的行动不符。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”针对申请或计划，不能用来表示人回到学校。"}, {"text": "返回", "is_correct": true, "explanation": "正确答案。“返回”表示人回到原来所在的地方，符合“下午三点回学校”。"}, {"text": "冲击", "is_correct": false, "explanation": "语义：“冲击”是猛烈撞击或攻入，与普通地回到学校不符。"}], "explanations": {"回忆": "语义：“回忆”是心理活动，不是人身体回到学校，与“下午三点”的行动不符。", "批准": "搭配：“批准”针对申请或计划，不能用来表示人回到学校。", "返回": "正确答案。“返回”表示人回到原来所在的地方，符合“下午三点回学校”。", "冲击": "语义：“冲击”是猛烈撞击或攻入，与普通地回到学校不符。"}, "sentence_index": 0, "correct_answer": "返回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快就返回了我的邮件。", "explanation": "这里应该用〈回复〉。返回指人或物回到原来的地方，回复邮件要用“回复”，不能说返回邮件。"}, {"text": "他把借的钱返回给了朋友。", "explanation": "这里应该用〈返还〉。返回指人或物回到原处，归还钱款要用“返还”。"}, {"text": "他每天早上返回了两杯咖啡。", "explanation": "这里应该用〈喝〉。返回指回到原处，喝咖啡要用“喝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90001, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攀登", "is_correct": false, "explanation": "语义：“攀登”是向上爬，与“山下”的方向相反。"}, {"text": "返回", "is_correct": true, "explanation": "正确答案。“已经返回山下的小镇”表示登山队员回到了山下的小镇。"}, {"text": "搬迁", "is_correct": false, "explanation": "语义：“搬迁”是整体迁移，登山队员不会去搬迁山下的小镇，句意不通。"}, {"text": "冶炼", "is_correct": false, "explanation": "语义：“冶炼”是加工金属，与登山队员和小镇毫无关系。"}], "explanations": {"攀登": "语义：“攀登”是向上爬，与“山下”的方向相反。", "返回": "正确答案。“已经返回山下的小镇”表示登山队员回到了山下的小镇。", "搬迁": "语义：“搬迁”是整体迁移，登山队员不会去搬迁山下的小镇，句意不通。", "冶炼": "语义：“冶炼”是加工金属，与登山队员和小镇毫无关系。"}, "sentence_index": 6, "correct_answer": "返回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于返回了全部欠款。", "explanation": "这里应该用〈偿还〉。返回指回到原处，还清欠款要用“偿还”，不能说返回欠款。"}, {"text": "他把借来的雨伞返回给了同学。", "explanation": "这里应该用〈送还〉。返回不用于把借来的物品还给别人，归还雨伞要用“送还”。"}, {"text": "他把捡到的钱包返回给了失主。", "explanation": "这里应该用〈交还〉。返回不用于把捡到的东西还给失主，要用“交还”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天晚上返回着宿舍。", "corrected_sentence": "他昨天晚上返回了宿舍。", "error_description": "错误：“返回”是一次性完成的动作，后面不能加表示持续的“着”。正确：应用“了”。“昨天晚上”只是时间，不决定能否用“着”（“昨天晚上坐着看书”就可以）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚下班就返回过宿舍。", "corrected_sentence": "他刚下班就返回了宿舍。", "error_description": "错误：“返回”后用了“过”，表示经历。正确：应用“了”。“刚下班就”描述的是紧接着发生的已完成动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90002, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出发", "is_correct": true, "explanation": "正确答案。出发与“返回”构成反义：出发指离开起点前往别处，与飞船返回地球的方向相反。"}, {"text": "修理", "is_correct": false, "explanation": "修理是动词，但与“返回”没有反义关系，指修复损坏的东西。"}, {"text": "思考", "is_correct": false, "explanation": "思考是动词，但与“返回”没有反义关系，指用脑子考虑问题。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运是动词，但与“返回”没有反义关系，指把东西从一处移到另一处。"}], "correct_answer": "出发", "explanations": {"出发": "正确答案。出发与“返回”构成反义：出发指离开起点前往别处，与飞船返回地球的方向相反。", "修理": "修理是动词，但与“返回”没有反义关系，指修复损坏的东西。", "思考": "思考是动词，但与“返回”没有反义关系，指用脑子考虑问题。", "搬运": "搬运是动词，但与“返回”没有反义关系，指把东西从一处移到另一处。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90002, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90002, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回到原处。", "primary_collocate": null, "pronunciation": "fǎn huí", "ipa": "fan˨˩˦ xweɪ˧˥", "syllable_count": 2, "sentences": [{"text": "飞机因为天气,返回了机场。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点这个键,就能返回上一页。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小船出海后,又返回原来的码头。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞船完成任务后,返回了地球。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看完地图,请返回首页。", "target_word": "返回", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "按错了,你可以返回原来的页面。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公交车到了终点,又返回起点。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关闭窗口前，要先返回桌面。", "target_word": "返回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼游向大海,几年后又返回河里。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "程序出错时,会自动返回开始的画面。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "返回了", "label": "完成体"}, {"form": "返回过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "返回:交通工具、页面、程序等回到原处或起点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d3da1c-9c58-4131-8533-51a4d2c792cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "返回", "is_correct": true, "explanation": "正确答案。返回，fǎnhuí，意思是回到原处，多指交通工具、页面等回到原处或起点。"}, {"text": "反悔", "is_correct": false, "explanation": "huǐ（第三声）与 huí（第二声）声调不同，意思是后悔、反悔。"}, {"text": "反馈", "is_correct": false, "explanation": "kuì 与 huí 声母不同（k 与 h），意思是把信息反映回去。"}, {"text": "翻回", "is_correct": false, "explanation": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻转回来。"}], "explanations": {"返回": "正确答案。返回，fǎnhuí，意思是回到原处，多指交通工具、页面等回到原处或起点。", "反悔": "huǐ（第三声）与 huí（第二声）声调不同，意思是后悔、反悔。", "反馈": "kuì 与 huí 声母不同（k 与 h），意思是把信息反映回去。", "翻回": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻转回来。"}, "sentence_index": null, "correct_answer": "返回"}, "level_3": {"options": [{"text": "起飞", "is_correct": false, "explanation": "配价：“起飞”是不及物动词，后面不能直接带“机场”作宾语，要说“从机场起飞”。"}, {"text": "装载", "is_correct": false, "explanation": "语义：“装载”的对象是货物，机场不能被装载，句意不通。"}, {"text": "返回", "is_correct": true, "explanation": "正确答案。“飞机因为天气，返回了机场”表示飞机因天气原因回到机场。"}, {"text": "滑行", "is_correct": false, "explanation": "语义：“滑行”是沿地面移动，不能表示飞机因天气而回到机场。"}], "explanations": {"起飞": "配价：“起飞”是不及物动词，后面不能直接带“机场”作宾语，要说“从机场起飞”。", "装载": "语义：“装载”的对象是货物，机场不能被装载，句意不通。", "返回": "正确答案。“飞机因为天气，返回了机场”表示飞机因天气原因回到机场。", "滑行": "语义：“滑行”是沿地面移动，不能表示飞机因天气而回到机场。"}, "sentence_index": 0, "correct_answer": "返回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快返回了十个俯卧撑。", "explanation": "这里应该用〈做〉。返回指回到原处，做俯卧撑要用“做”。"}, {"text": "他终于返回了这首诗。", "explanation": "这里应该用〈写出〉。返回指回到原处，诗是创作出来的，不能说返回这首诗。"}, {"text": "这部电影返回了三个小时。", "explanation": "这里应该用〈长达〉。返回不表示时长，电影的时长要用“长达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漂流", "is_correct": false, "explanation": "语义：“漂流”指随水流漂动，与公交车的行驶路线无关。"}, {"text": "行驶", "is_correct": false, "explanation": "配价：“行驶”是不及物动词，后面不能直接带“起点”作宾语，要说“行驶到起点”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复，与“又……起点”的行驶路线不符。"}, {"text": "返回", "is_correct": true, "explanation": "正确答案。“公交车到了终点，又返回起点”表示车辆沿原路回到起点。"}], "explanations": {"漂流": "语义：“漂流”指随水流漂动，与公交车的行驶路线无关。", "行驶": "配价：“行驶”是不及物动词，后面不能直接带“起点”作宾语，要说“行驶到起点”。", "修理": "语义：“修理”指修复，与“又……起点”的行驶路线不符。", "返回": "正确答案。“公交车到了终点，又返回起点”表示车辆沿原路回到起点。"}, "sentence_index": 6, "correct_answer": "返回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员把多收的钱返回给了客人。", "explanation": "这里应该用〈退还〉。返回指交通工具、页面等回到原处，把钱退给客人要用“退还”。"}, {"text": "他把捡到的证件返回给了失主。", "explanation": "这里应该用〈交还〉。返回不用于把捡到的东西还给失主，要用“交还”。"}, {"text": "他把借来的外套返回给了同学。", "explanation": "这里应该用〈送还〉。返回不用于把借来的物品还给别人，归还外套要用“送还”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火车因为大雪，返回着车站。", "corrected_sentence": "火车因为大雪，返回了车站。", "error_description": "错误：“返回”是一次性完成的动作，后面不能加表示持续的“着”。正确：应用“了”。“因为大雪”只是原因，不决定能否用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
